INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_visiting_info', 'ade66480-3d19-4e93-a149-4f796bdeb466', 'accessibility_info', 'am', 'ሕንጻው ታሪካዊ በመሆኑ ተደራሽነቱ ውስን ነው።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
