INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'am', 'እድሳት', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'am', 'ይህ ፕሮጀክት በባዚሊካው አስቸኳይ የእድሳት ፍላጎቶች ላይ ያተኩራል፤ ከእነዚህም መካከል የመዋቅር ጥገና፣ የፊት ገጽታ ጽዳት እና የመጀመሪያዎቹን የሥነ ሕንጻ ክፍሎች መጠበቅ ይገኙበታል። ሥራው ሕንጻው ለመጪው ትውልድ ደኅንነቱ የተጠበቀና ተደራሽ ሆኖ እንዲቀጥል ያደርጋል።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'am', 'የብሥራት ባዚሊካ ዋና አዳራሽና የፊት ገጽታ እድሳት።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'am', 'የባዚሊካው እድሳት - ምዕራፍ 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'am', 'ሰነዳ', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'am', 'በእስራኤልና በአጎራባች አካባቢዎች የሚገኙ የክርስትና ቅርስ ስፍራዎችን፣ ቅርሳ ቅርሶችንና የብራና መጻሕፍትን ፎቶግራፍ ለማንሳት፣ በስካነር ለመቅዳትና ለመሰነድ የተዘጋጀ ሁሉን አቀፍ ጅምር ነው። ይህ ዲጂታል ማኅደር ዋጋ የማይተመንላቸውን ታሪካዊ መዛግብት ለተመራማሪዎችና ለመጪው ትውልድ ይጠብቃል።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'am', 'በመላው ቅድስት ምድር የሚገኙ የክርስትና ቅርስ ስፍራዎችን በዲጂታል መንገድ መሰነድ።', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'am', 'የቅድስት ምድር ቅርስ ሰነዳ', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ar', 'كنيسة البشارة هي كنيسة كاثوليكية تقع في الناصرة، إسرائيل. وهي واحدة من أكبر الكنائس في الشرق الأوسط وتحتفل بالموقع التقليدي حيث بشّر الملاك جبرائيل مريم بأنها ستلد يسوع.', 'تم بناء البازيليكا الحالية عام 1969، صممها المهندس المعماري الإيطالي جيوفاني موتسيو. تقف على أنقاض كنائس بيزنطية وصليبية سابقة. كان الموقع مكانًا للحج المسيحي منذ العصور القديمة.', 'تخدم الكنيسة المجتمع الكاثوليكي المحلي في الناصرة وترحب بالحجاج من جميع أنحاء العالم. تقام القداس بانتظام بلغات متعددة.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ar', 'تقوم كنيسة المهد في بيت لحم فوق المغارة التي يُكرّمها التقليد المسيحي منذ القرن الثاني باعتبارها مكان ولادة يسوع المسيح. وهي واحدة من أقدم الكنائس التي لا تزال قيد الاستخدام المستمر في العالم، وموقع مدرج على لائحة التراث العالمي لليونسكو.', 'أمر الإمبراطور قسطنطين ووالدته هيلانة ببناء البازيليكا الأولى حوالي عام 327 م. وبعد أن تضررت في القرن السادس، أعاد الإمبراطور جستنيان بناءها على نطاق أوسع، ويعود جزء كبير من الكنيسة الحالية إلى ذلك البناء. لا تزال الفسيفساء والأعمدة المرسومة من العصر الصليبي باقية في الداخل.', 'تشترك في الكنيسة طوائف الروم الأرثوذكس والكاثوليك (الفرنسيسكان) والأرمن الأرثوذكس بموجب ترتيب الوضع الراهن التاريخي. تصلي فيها عائلات بيت لحم المسيحية المحلية جنبًا إلى جنب مع الحجاج القادمين من جميع أنحاء العالم، خاصة في عيد الميلاد.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ar', 'تضم كنيسة القيامة في البلدة القديمة بالقدس أقدس موقعين في المسيحية: الجلجثة، حيث صُلب يسوع، والقبر الذي دُفن فيه وقام منه، بحسب التقليد.', 'بنى الإمبراطور قسطنطين الكنيسة الأولى هنا في القرن الرابع، وكُرِّست عام 335 م. دُمِّرت عام 1009 وأُعيد بناؤها في القرن الحادي عشر، ومنحها الصليبيون معظم شكلها الحالي في القرن الثاني عشر. رُمِّم الإيديكول (الكنيسة الصغيرة) فوق القبر بين عامي 2016 و2017.', 'تتشارك في رعاية الكنيسة طوائف الروم الأرثوذكس والكاثوليك (الفرنسيسكان) والأرمن الأرثوذكس، كما تحتفظ الطوائف القبطية والإثيوبية والسريانية الأرثوذكسية بمصليات فيها، وذلك بموجب الوضع الراهن لعام 1852. تُفتح أبوابها كل صباح على يد عائلات مسلمة تحافظ على مفاتيحها منذ قرون.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'ar', 'كنيسة جميع الأمم، المعروفة أيضًا باسم بازيليك النزاع، هي كنيسة كاثوليكية رومانية تقع في الجثمانية على جبل الزيتون في القدس. تضم في داخلها الصخرة التي يحددها التقليد باعتبارها المكان الذي صلّى فيه يسوع في نزاعه في الليلة التي سبقت صلبه.', 'شُيّدت البازيليك الحالية بين عامي 1919 و1924 على أساسات كنائس بيزنطية وصليبية سابقة اكتُشفت أثناء البناء. عُرفت باسم كنيسة جميع الأمم لأن تبرعات من بلدان عديدة موّلت بناءها، وقد وُضعت شعاراتها في السقف.', 'تعتني بالبازيليك حراسة الأرض المقدسة الفرنسيسكانية، التي تحافظ على الموقع وبستان الجثمانية المجاور بأشجار زيتونه العتيقة. ولا تزال مكانًا نشطًا للصلاة ومحطة رئيسية للحجاج الزائرين لجبل الزيتون.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'ar', 'كنيسة مريم المجدلية هي كنيسة روسية أرثوذكسية تقع على المنحدر الغربي لجبل الزيتون في القدس، بالقرب من بستان الجثمانية. تشتهر على نطاق واسع بقبابها البصلية المذهّبة السبع، وهي معلم مميز في أفق القدس.', 'بُنيت الكنيسة بين عامي 1886 و1888 على يد القيصر ألكسندر الثالث إمبراطور روسيا إحياءً لذكرى والدته الإمبراطورة ماريا ألكسندروفنا. وقد كُرّست لمريم المجدلية، القديسة التي سُمّيت الإمبراطورة على اسمها، وتعكس الحضور الروسي في الأرض المقدسة في أواخر القرن التاسع عشر.', 'تتبع الكنيسة ديرًا لراهبات أرثوذكسيات ولا تزال جماعة رهبانية نشطة ترحب بالزوار والحجاج. وتقوم ضمن محيط الجثمانية على منحدرات جبل الزيتون.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'ar', 'دومينوس فليفيت، ومعناها باللاتينية «الربّ بكى»، هي كنيسة صغيرة كاثوليكية رومانية تقع على المنحدر الغربي لجبل الزيتون في القدس. تحيي ذكرى المكان الذي بكى فيه يسوع، بحسب إنجيل لوقا، وهو ينظر نحو القدس ويتنبأ بخرابها.', 'بُنيت الكنيسة الحالية عام 1955 فوق مبانٍ دينية سابقة، من بينها بقايا كنيسة من العصر البيزنطي. كما كشفت الحفريات في الموقع عن قبور وأجران عظام قديمة، تشهد على استخدام المنحدر مدفنًا منذ زمن بعيد.', 'تعتني بدومينوس فليفيت حراسة الأرض المقدسة الفرنسيسكانية ضمن شبكة مقدساتها في القدس وحولها. وهي محطة متكررة للحجاج المتجهين نزولًا من جبل الزيتون نحو الجثمانية.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'ar', 'كنيسة القديسة حنة هي كنيسة كاثوليكية رومانية تقع في البلدة القديمة بالقدس، في الحي الإسلامي إلى جانب بركتَي بيت حسدا. تقوم فوق موقع يكرّمه التقليد باعتباره منزل حنة ويواكيم ومكان ولادة العذراء مريم.', 'بُنيت الكنيسة في القرن الثاني عشر إبان مملكة القدس الصليبية. وبعد فتح صلاح الدين للمدينة عام 1187 حُوّلت إلى مدرسة إسلامية، وفي القرن التاسع عشر منحتها السلطات العثمانية لفرنسا التي رمّم القائمون عليها المبنى.', 'عُهد بالكنيسة وأرضها إلى المرسلين الأفارقة، المعروفين باسم الآباء البيض، الذين يعتنون بالموقع ويرحبون بالحجاج. ولا تزال مكانًا نشطًا للصلاة والدراسة داخل البلدة القديمة.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'ar', 'كنيسة الأبانا هي كنيسة كاثوليكية رومانية ودير للكرمليات على جبل الزيتون في القدس. تقوم على موقع يرتبط تقليديًا بتعليم يسوع تلاميذه الصلاة الربّية، المعروفة باللاتينية باسم «الأبانا» (Pater Noster).', 'يحفظ الموقع ذكرى كنيسة إليونا البيزنطية التي بُنيت في القرن الرابع فوق مغارة على جبل الزيتون في عهد قسطنطين. وبعد قرون من الخراب، أُنشئ هنا دير فرنسي في القرن التاسع عشر، واستمر بناء الكنيسة حتى القرن العشرين.', 'تعتني بالموقع جماعة من الراهبات الكرمليات اللواتي يحافظن على الدير والكنيسة والرواق. وهو محطة معتادة للحجاج والزوار الذين يستكشفون جبل الزيتون.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'ar', 'كنيسة الزيارة هي كنيسة كاثوليكية رومانية في قرية عين كارم، على الطرف الغربي للقدس. تحيي ذكرى الموقع التقليدي حيث زارت مريم نسيبتها أليصابات، ونطقت، بحسب إنجيل لوقا، بالنشيد المعروف باسم نشيد التعظيم (الماجنيفيكات). يعتني بالموقع الفرنسيسكان وهو وجهة يقصدها الحجاج إلى الأرض المقدسة على نطاق واسع.', 'يحدّد التقليد المسيحي عين كارم قرية زكريا وأليصابات ومسرح الزيارة الموصوفة في إنجيل لوقا. قامت كنيسة على الموقع في العصرين البيزنطي والصليبي، ويحفظ المبنى الحالي المكوّن من طابقين عناصر من هذه المنشآت السابقة. طُوّرت الكنيسة الحالية في النصف الأول من القرن العشرين تحت حراسة الأرض المقدسة الفرنسيسكانية.', 'تملك الموقع وتصونه حراسة الأرض المقدسة الفرنسيسكانية التي تعتني بمزارات عديدة في أنحاء المنطقة. ولا يزال مكانًا نشطًا للصلاة ومحطة معتادة على مسارات الحج عبر عين كارم، التي تضم أيضًا كنائس أخرى مرتبطة بميلاد يوحنا المعمدان.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'ar', 'كنيسة التطويبات هي كنيسة كاثوليكية رومانية على تلة تشرف على الشاطئ الشمالي الغربي لبحر الجليل. تحيي ذكرى الموقع التقليدي للموعظة على الجبل، وتستمد اسمها من التطويبات، البركات التي تفتتح الموعظة في إنجيل متى. يوفر الموقع إطلالة واسعة على البحيرة والقرى المحيطة بها.', 'التقليد الذي يجعل تلةً قرب كفرناحوم مكانًا للموعظة على الجبل قديم العهد، وقد لُوحظت بقايا سابقة في جوار الطابغة أسفلها. بُنيت الكنيسة الحالية عام 1938 من تصميم المهندس المعماري الإيطالي أنطونيو بارلوتزي. ودُعم بناؤها جزئيًا بتمويل من إيطاليا.', 'تعتني بالكنيسة وأرضها الراهبات الفرنسيسكانيات المرسلات لقلب يسوع الأقدس. ويؤدي الموقع دور مكان للعبادة ووجهة حج يقصدها كثيرون في الجليل.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'ar', 'كنيسة تكثير الخبز والسمك هي كنيسة كاثوليكية رومانية في الطابغة، على الشاطئ الشمالي الغربي لبحر الجليل. تحيي ذكرى رواية الإنجيل عن تكثير الأرغفة والأسماك التي أُطعم بها الجمع. تشتهر الكنيسة بأرضياتها الفسيفسائية المسيحية المبكرة.', 'كُرّمت الطابغة في العصر البيزنطي باعتبارها موقع المعجزة، واستُبدل بمصلى صغير من القرن الرابع كنيسة أكبر في القرن الخامس. خرِبت هذه المباني المبكرة، ثم أُعيد اكتشاف بقاياها والتنقيب عنها في العصر الحديث. وتستنسخ الكنيسة الحالية، المبنية في القرن العشرين، مخطط البازيليك البيزنطية.', 'يخدم الكنيسة رهبان بينديكتيون ألمان مرتبطون بدير الرقاد في القدس. ولا تزال موقعًا رهبانيًا وحجّيًا نشطًا؛ وقد أضرّ حريق بأجزاء من المجمع عام 2015، ثم رُمّم بعده.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'ar', 'كنيسة أولوية القديس بطرس هي كنيسة صغيرة كاثوليكية رومانية في الطابغة، على شاطئ بحر الجليل. تحيي ذكرى ظهور يسوع لتلاميذه بعد قيامته، الموصوف في إنجيل يوحنا، ومنح الأولوية لبطرس. تقوم الكنيسة الصغيرة مباشرة إلى جانب الماء.', 'يستحضر الموقع رواية إنجيل يوحنا (الإصحاح 21)، حيث يظهر يسوع القائم للتلاميذ عند البحيرة، ويشاركهم وجبة من الخبز والسمك، ويكلّف بطرس ثلاث مرات برعاية قطيعه. قامت هنا في قرون سابقة كنيسة مرتبطة بهذا التقليد، ولا تزال آثار منشآت سابقة باقية في الجوار. بُنيت الكنيسة الحالية عام 1933.', 'تعتني بالكنيسة الصغيرة حراسة الأرض المقدسة الفرنسيسكانية. وهي محطة متكررة للحجاج الزائرين للمواقع المحيطة بالشاطئ الشمالي لبحر الجليل.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'ar', 'كنيسة التجلي هي بازيليك كاثوليكية رومانية على قمة جبل طابور، الذي يرتفع فوق مرج بن عامر في الجليل الأسفل. تحيي ذكرى تجلي يسوع، حين شوهد بحسب الأناجيل متغيّر الهيئة في حضرة موسى وإيليا. وتقوم أيضًا كنيسة للروم الأرثوذكس في موضع آخر من الجبل.', 'حظي جبل طابور بالتكريم منذ العصر البيزنطي باعتباره الموقع التقليدي للتجلي، وبُنيت فيه كنائس في العصرين البيزنطي والصليبي. خرِبت هذه المنشآت لاحقًا، ولا تزال أساساتها باقية على القمة. اكتمل بناء البازيليك الحالية عام 1924.', 'تعتني بالبازيليك وأرضها حراسة الأرض المقدسة الفرنسيسكانية. ولا يزال الجبل وجهة حج، وتتقاسم القمة معه دير وكنيسة للروم الأرثوذكس.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'ar', 'تقوم كنيسة العرس الفرنسيسكانية في كفر كنا، البلدة التي يُرجّح تحديدها بقانا الجليل الواردة في الأناجيل، شمالي الناصرة. تحيي ذكرى وليمة العرس التي حوّل فيها يسوع، بحسب إنجيل يوحنا، الماء إلى خمر، وهي موصوفة بأنها أولى آياته. يجتذب الموقع الحجاج، ولا سيما الأزواج الذين يأتون لإحياء عهودهم الزوجية وتجديدها.', 'يضع إنجيل يوحنا (الإصحاح 2) يسوع وأمه وتلاميذه في عرس بقانا، حيث نفد خمر المضيف فأمر يسوع بملء ست جرار حجرية بالماء الذي صار خمرًا. تطوّر عبر القرون تقليد كنسي يكرّم المعجزة في كفر كنا، وقامت أماكن عبادة سابقة على الموقع الحالي أو قربه. بُنيت الكنيسة الفرنسيسكانية الحالية بين عامي 1879 و1905.', 'تعتني بكنيسة العرس رهبان الفرنسيسكان في حراسة الأرض المقدسة، الذين يصونونها مكانًا للعبادة والحج. كما تحفظ كنيسة منفصلة للروم الأرثوذكس في كفر كنا تقليد المعجزة في الجوار.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'ar', 'كفرناحوم، على الشاطئ الشمالي لبحر الجليل، هي بلدة على ضفة البحيرة تصفها الأناجيل مركزًا لخدمة يسوع في الجليل. يحفظ الموقع الأثري البقايا المكرّمة باعتبارها بيت الرسول بطرس ومجمعًا قديمًا. وهو من أهم مواقع العهد الجديد في المنطقة.', 'تقدّم الأناجيل كفرناحوم مكانًا علّم فيه يسوع ودعا التلاميذ وأجرى الشفاء، وتربط البلدة ببطرس وسواه من الأتباع. ومنذ القرون الأولى كرّم المسيحيون بيتًا في الموقع، ثم أُحيط لاحقًا بكنيسة مثمّنة الأضلاع. سُكنت البلدة قرونًا قبل أن تضمحل، تاركةً الأطلال التي يدرسها علماء الآثار المحدثون.', 'تملك الموقع وتعتني به حراسة الأرض المقدسة الفرنسيسكانية، التي تشرف على الكنيسة والحفريات ووصول الحجاج والزوار. وتقوم كنيسة ودير منفصلان للروم الأرثوذكس عند الطرف الشرقي للمنطقة.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'ar', 'تقوم كنيسة حقل الرعاة في بيت ساحور، شرقي بيت لحم، في الموقع الذي يُحدَّد تقليديًا بحقول الرعاة في رواية الميلاد. بحسب إنجيل لوقا، أعلنت الملائكة هناك ميلاد يسوع لرعاة يحرسون قطعانهم ليلًا. الكنيسة وأرضها المحيطة مكان للصلاة والحج، خاصة في عيد الميلاد.', 'يصف إنجيل لوقا (الإصحاح 2) رعاة قرب بيت لحم أُخبروا بميلاد المخلّص فذهبوا ليجدوا الطفل. تكريم المسيحيين لحقول الرعاة قرب بيت ساحور قديم جدًا، وقد عُثر في المنطقة على بقايا كنائس ومنشآت رهبانية سابقة. بُنيت كنيسة الفرنسيسكان الحالية عام 1953.', 'تعتني بالكنيسة وحقلها حراسة الأرض المقدسة الفرنسيسكانية. ويقع في الجوار حقل رعاة منفصل للروم الأرثوذكس، بكنيسته وبقاياه القديمة، في المنطقة نفسها من بيت ساحور.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'ar', 'مغارة الحليب هي كنيسة صغيرة بُنيت حول مغارة من الطباشير الأبيض الطري في بيت لحم، على مسافة قصيرة من كنيسة المهد. يربط التقليد المغارة بالعائلة المقدسة، ويصلها بالفترة السابقة للهروب إلى مصر أو أثناءه. وهي مكان هادئ للصلاة، يزوره خصوصًا الأمهات والأزواج الراجون الإنجاب.', 'يرى التقليد المحلي أن العائلة المقدسة لجأت إلى هذه المغارة وأن صخرتها صارت بيضاء، فأُطلق عليها الاسم ونشأت عبادات مرتبطة بالحليب والأمومة. وتكريم المسيحيين للموقع موثّق عبر قرون عديدة. كانت المغارة منذ زمن بعيد في عهدة الفرنسيسكان، وأُضيفت كنيسة أحدث في العصر الحديث إلى جانب المقدس القديم.', 'تعتني بمغارة الحليب حراسة الأرض المقدسة الفرنسيسكانية، التي تصونها مكانًا للصلاة وتستقبل الحجاج من بلدان عديدة. ولا تزال محورًا للتقوى الشخصية، خاصة لمن يصلّون طلبًا للأمومة والأسرة.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
