INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'ar', 'ترميم البازيليكا - المرحلة الأولى', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'ar', 'توثيق', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ar', 'مبادرة شاملة لتصوير ومسح وتوثيق مواقع التراث المسيحي والقطع الأثرية والمخطوطات في جميع أنحاء إسرائيل والمناطق المحيطة بها. سيحافظ هذا الأرشيف الرقمي على سجلات تاريخية لا تقدَّر بثمن للباحثين وللأجيال القادمة.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ar', 'توثيق رقمي لمواقع التراث المسيحي في جميع أنحاء الأرض المقدسة.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'ar', 'توثيق تراث الأرض المقدسة', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'bg', 'Базиликата на Благовещение е католическа църква в Назарет, Израел. Тя е една от най-големите църкви в Близкия изток и отбелязва мястото, което според преданието е там, където архангел Гавраил възвестил на Мария, че ще роди Иисус.', 'Днешната базилика е построена през 1969 г. по проект на италианския архитект Джовани Муцио. Тя се издига над руините на по-ранни византийски и кръстоносни църкви. Мястото е средище на християнски поклонения от древни времена.', 'Църквата служи на местната католическа общност в Назарет и посреща поклонници от цял свят. Литургии се отслужват редовно на няколко езика.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'bg', 'Църквата на Рождество Христово във Витлеем се издига над пещерата, която християнската традиция от 2 век почита като място на раждането на Иисус. Тя е една от най-старите непрекъснато използвани църкви в света и обект на световното наследство на ЮНЕСКО.', 'Първата базилика е построена около 327 г. по поръка на император Константин и майка му Елена. След като е повредена през 6 век, император Юстиниан я възстановява в по-голям мащаб и голяма част от днешната църква е от това възстановяване. Вътре все още са запазени мозайки и изписани колони от епохата на кръстоносците.', 'Църквата е поделена между гръцката православна, римокатолическата (францисканска) и арменската апостолическа общност съгласно историческото статукво. Местните християнски семейства от Витлеем се молят тук заедно с поклонници от цял свят, особено по Коледа.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'bg', 'Църквата на Божи гроб в Стария град на Йерусалим съдържа двете най-свети места на християнството: Голгота, където Иисус е разпнат, и гроба, в който според преданието е погребан и възкръснал.', 'Император Константин построява първата църква тук през 4 век; тя е осветена през 335 г. Разрушена е през 1009 г. и възстановена през 11 век, а кръстоносците ѝ придават голяма част от днешния облик през 12 век. Едикулата над гроба е реставрирана през 2016–2017 г.', 'Грижата за църквата е поделена между гръцката православна, римокатолическата (францисканска) и арменската апостолическа църква, като коптската, етиопската и сирийската православна общност също имат параклиси, съгласно статуквото от 1852 г. Вратите ѝ се отварят всяка сутрин от мюсюлмански семейства, които пазят ключовете от векове.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'bg', 'Църквата на всички народи, известна още като Базиликата на агонията, е римокатолическа църква в Гетсимания на Елеонската планина в Йерусалим. Тя съхранява частта от скалната основа, която според преданието се отъждествява с мястото, където Иисус се молил в агония в нощта преди разпятието си.', 'Днешната базилика е построена между 1919 и 1924 г. върху основите на по-ранни византийски и кръстоносни църкви, разкрити по време на строежа. Тя става известна като Църквата на всички народи, защото дарения от много страни финансират изграждането ѝ, а гербовете им са вградени в тавана.', 'За базиликата се грижи Францисканската кустодия на Светата земя, която поддържа мястото и съседната Гетсиманска градина с нейните древни маслинови дървета. Тя остава живо място за молитва и важна спирка за поклонниците, посещаващи Елеонската планина.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'bg', 'Църквата „Света Мария Магдалена“ е руска православна църква на западния склон на Елеонската планина в Йерусалим, близо до Гетсиманската градина. Тя е широко известна със своите седем позлатени луковични куполи — отличителна забележителност на йерусалимския силует.', 'Църквата е построена между 1886 и 1888 г. от руския цар Александър III в памет на майка му, императрица Мария Александровна. Посветена е на Мария Магдалена, светицата, на която е кръстена императрицата, и отразява руското присъствие в Светата земя в края на деветнадесети век.', 'Църквата принадлежи на манастир на православни монахини и остава жива монашеска общност, която посреща посетители и поклонници. Тя се намира в околностите на Гетсимания по склоновете на Елеонската планина.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'bg', 'Доминус Флевит, което на латински означава „Господ заплака“, е римокатолически параклис на западния склон на Елеонската планина в Йерусалим. Той отбелязва мястото, където според Евангелието от Лука Иисус заплакал, гледайки към Йерусалим, и предсказал неговото разрушение.', 'Днешният параклис е построен през 1955 г. на мястото на по-ранни религиозни сгради, включително останки от църква от византийската епоха. Разкопките на терена откриват и древни гробници и костници, свидетелстващи за дълготрайната употреба на склона като гробище.', 'За Доминус Флевит се грижи Францисканската кустодия на Светата земя като част от мрежата ѝ от светилища в Йерусалим и около него. Той е честа спирка за поклонниците, които слизат по Елеонската планина към Гетсимания.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'bg', 'Църквата „Света Анна“ е римокатолическа църква в Стария град на Йерусалим, в Мюсюлманския квартал до къпалните Витезда. Тя се издига над място, което по предание се почита като дома на Анна и Йоаким и родното място на Дева Мария.', 'Църквата е построена през дванадесети век по време на кръстоносното Йерусалимско кралство. След завладяването на града от Саладин през 1187 г. тя е превърната в ислямско училище, а през деветнадесети век османските власти я предоставят на Франция, чиито попечители възстановяват сградата.', 'Църквата и нейният терен са поверени на Мисионерите на Африка, известни като Белите отци, които се грижат за мястото и посрещат поклонници. Тя остава живо място за молитва и учение в Стария град.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'bg', 'Църквата „Патер Ностер“ е римокатолическа църква и кармелитски манастир на Елеонската планина в Йерусалим. Тя се издига на място, което преданието свързва с това, че Иисус научил учениците си на молитвата „Отче наш“, известна на латински като „Патер Ностер“.', 'Мястото пази паметта за византийската църква Елеона, построена през четвърти век над пещера на Елеонската планина по времето на Константин. След векове на разруха тук през деветнадесети век е основан френски манастир, а строежът на църковните сгради продължава и през двадесети век.', 'За мястото се грижи общност от кармелитски сестри, които поддържат манастира, църквата и клаустъра. То е редовна спирка за поклонници и посетители, разглеждащи Елеонската планина.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'bg', 'Църквата на Посещението е римокатолическа църква в село Ейн Керем, в западния край на Йерусалим. Тя отбелязва традиционното място, където Мария посетила роднината си Елисавета и според Евангелието от Лука изрекла песента, известна като Магнификат. За мястото се грижат францисканците и то е широко посещавана цел за поклонниците в Светата земя.', 'Християнското предание отъждествява Ейн Керем с родното село на Захария и Елисавета и с мястото на Посещението, описано в Евангелието от Лука. Църква е стояла на мястото през византийския и кръстоносния период, а днешната двуетажна сграда запазва елементи от тези по-ранни постройки. Сегашната църква е изградена през първата половина на двадесети век под Францисканската кустодия на Светата земя.', 'Мястото е собственост и се поддържа от Францисканската кустодия на Светата земя, която се грижи за многобройни светилища из региона. То остава живо място за молитва и редовна спирка по поклонническите маршрути през Ейн Керем, където се намират и други църкви, свързани с рождението на Йоан Кръстител.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'bg', 'Църквата на блаженствата е римокатолическа църква на склон над северозападния бряг на Галилейското езеро. Тя отбелязва традиционното място на Проповедта на планината и носи името си от блаженствата — благословиите, с които започва проповедта в Евангелието от Матей. Местоположението предлага широка гледка към езерото и околните села.', 'Преданието за хълм близо до Капернаум като място на Проповедта на планината е отдавнашно, а по-ранни останки са отбелязани в околността на Табга под него. Днешната църква е построена през 1938 г. по проект на италианския архитект Антонио Барлуци. Строежът ѝ е подпомогнат отчасти със средства от Италия.', 'За църквата и нейния терен се грижат Францисканските мисионерки на Пресвето Сърце. Мястото служи както за богослужение, така и като широко посещавана поклонническа цел в Галилея.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'bg', 'Църквата на умножаването на хлябовете е римокатолическа църква в Табга, на северозападния бряг на Галилейското езеро. Тя възпоменава евангелския разказ за умножаването на хлябовете и рибите, с които е нахранено множество хора. Църквата е добре известна с ранните си християнски мозаечни подове.', 'Табга е почитана през византийския период като мястото на чудото, а малък параклис от четвърти век по-късно е заменен от по-голяма църква през пети век. Тези ранни сгради изпадат в разруха, а останките им са преоткрити и разкопани в ново време. Днешната църква, построена през двадесети век, възпроизвежда плана на византийската базилика.', 'На църквата служат немски бенедиктински монаси, свързани с абатството „Успение Богородично“ в Йерусалим. Тя остава живо монашеско и поклонническо място; пожар през 2015 г. поврежда части от комплекса, който след това е възстановен.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'bg', 'Църквата на първенството на свети Петър е малък римокатолически параклис в Табга, на брега на Галилейското езеро. Тя възпоменава едно явяване на Иисус пред учениците след възкресението, описано в Евангелието от Йоан, и предаването на първенството на Петър. Параклисът се издига непосредствено до водата.', 'Мястото напомня за разказа в Йоан 21, в който възкръсналият Иисус се явява на учениците край езерото, споделя с тях трапеза от хляб и риба и три пъти възлага на Петър да пасе стадото му. Църква, свързана с това предание, е съществувала тук в предишни векове, а следи от по-стари постройки са запазени наблизо. Днешният параклис е построен през 1933 г.', 'За параклиса се грижи Францисканската кустодия на Светата земя. Той е честа спирка за поклонниците, посещаващи местата около северния бряг на Галилейското езеро.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'bg', 'Църквата на Преображението е римокатолическа базилика на върха на планината Тавор, която се издига над Изреелската долина в Долна Галилея. Тя възпоменава Преображението на Иисус, когато според евангелията Той бил видян преобразен в присъствието на Моисей и Илия. На друго място на планината се издига и гръцка православна църква.', 'Планината Тавор е почитана от византийския период като традиционното място на Преображението, а тук са построени църкви през византийско и кръстоносно време. Тези постройки по-късно изпадат в разруха, а основите им остават на върха. Днешната базилика е завършена през 1924 г.', 'За базиликата и нейния терен се грижи Францисканската кустодия на Светата земя. Планината остава поклонническа цел, а върхът се споделя с гръцки православен манастир и църква.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'bg', 'Францисканската църква на сватбата се намира в Кафр Кана — градът, широко отъждествяван с евангелската Кана Галилейска, северно от Назарет. Тя възпоменава сватбеното пиршество, на което според Евангелието от Йоан Иисус превърнал водата във вино — описано като първото от знаменията му. Мястото привлича поклонници, и особено семейни двойки, които идват да отбележат и подновят своите обети.', 'Евангелието от Йоан (глава 2) поставя Иисус, майка му и учениците му на сватба в Кана, където на домакина свършило виното, а Иисус наредил да напълнят шест каменни делви с вода, която станала вино. Църковно предание, почитащо чудото в Кафр Кана, се развива през вековете, а по-ранни места за богослужение са стояли на днешното място или в близост до него. Сегашната францисканска църква е построена между 1879 и 1905 г.', 'За Църквата на сватбата се грижат францисканските братя от Кустодията на Светата земя, които я поддържат като място за богослужение и поклонение. Отделна гръцка православна църква в Кафр Кана също пази предания за чудото наблизо.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'bg', 'Капернаум, на северния бряг на Галилейското езеро, е крайезерният град, който евангелията описват като средище на служението на Иисус в Галилея. Археологическият обект пази останките, почитани като къщата на апостол Петър, и древна синагога. Той е едно от най-важните новозаветни места в региона.', 'Евангелията представят Капернаум като мястото, където Иисус учил, призовавал ученици и изцелявал, и свързват града с Петър и други последователи. От ранните векове една къща на мястото била почитана от християните и по-късно обградена от осмоъгълна църква. Градът бил обитаван векове, преди да запада, оставяйки руините, изучавани от съвременните археолози.', 'Обектът е притежаван и поддържан от Францисканската кустодия на Светата земя, която надзирава църквата, разкопките и достъпа за поклонници и посетители. Отделна гръцка православна църква и манастир се издигат в източния край на района.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'bg', 'Параклисът на Пастирското поле се намира в Бейт Сахур, източно от Витлеем, на мястото, традиционно отъждествявано с полята на пастирите от разказа за Рождество. Според Евангелието от Лука там ангели възвестили на пастирите, пазещи стадата си нощем, раждането на Иисус. Параклисът и околният му терен са място за молитва и поклонение, особено по Коледа.', 'Евангелието от Лука (глава 2) описва пастири близо до Витлеем, на които било възвестено раждането на Спасителя и които тръгнали да намерят детето. Християнското почитане на пастирските полета близо до Бейт Сахур е много старо, а в района са открити останки от по-ранни църкви и монашески постройки. Днешният францискански параклис е построен през 1953 г.', 'За параклиса и полето му се грижи Францисканската кустодия на Светата земя. Отделно гръцко православно Пастирско поле, със собствена църква и древни останки, се намира наблизо, в същата част на Бейт Сахур.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'bg', 'Млечната пещера е параклис, изграден около пещера от мек бял тебешир във Витлеем, на кратко разстояние пеша от Църквата на Рождество Христово. Преданието свързва пещерата със Светото семейство, отнасяйки я към времето преди или по време на бягството в Египет. Тя е тихо място за молитва, посещавано особено от майки и от двойки, надяващи се на деца.', 'Местното предание твърди, че Светото семейство се приютило в тази пещера и че скалата ѝ станала бяла, откъдето идват името и набожните почитания, свързани с млякото и майчинството. Християнското почитане на мястото е засвидетелствано през много векове. Пещерата отдавна е под грижата на францисканците, а в ново време до по-старото светилище е добавен по-нов параклис.', 'За Млечната пещера се грижи Францисканската кустодия на Светата земя, която я поддържа като място за молитва и приема поклонници от много страни. Тя остава средоточие на лична набожност, особено за онези, които се молят за майчинство и семейство.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
