INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'de', 'Restaurierung', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'de', 'Dieses Projekt konzentriert sich auf die dringendsten Restaurierungsbedürfnisse der Basilika, einschließlich struktureller Reparaturen, der Reinigung der Fassade und der Bewahrung originaler architektonischer Elemente. Die Arbeiten werden sicherstellen, dass das Gebäude für künftige Generationen sicher und zugänglich bleibt.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'de', 'Restaurierung des Hauptschiffs und der Fassade der Verkündigungsbasilika.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'de', 'Restaurierung der Basilika – Phase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'de', 'Dokumentation', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'de', 'Eine umfassende Initiative zur Fotografie, Digitalisierung und Dokumentation christlicher Erbestätten, Artefakte und Manuskripte in Israel und den umliegenden Regionen. Dieses digitale Archiv wird unschätzbare historische Aufzeichnungen für Forscher und künftige Generationen bewahren.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'de', 'Digitale Dokumentation christlicher Erbestätten im gesamten Heiligen Land.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'de', 'Dokumentation des Erbes des Heiligen Landes', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'el', 'Η Βασιλική του Ευαγγελισμού είναι καθολικός ναός στη Ναζαρέτ του Ισραήλ. Είναι ένας από τους μεγαλύτερους ναούς στη Μέση Ανατολή και σηματοδοτεί τον παραδοσιακό τόπο όπου ο Αρχάγγελος Γαβριήλ ανήγγειλε στη Μαρία ότι θα γεννούσε τον Ιησού.', 'Η σημερινή βασιλική χτίστηκε το 1969, σχεδιασμένη από τον Ιταλό αρχιτέκτονα Τζιοβάνι Μούτζιο. Υψώνεται πάνω από τα ερείπια παλαιότερων βυζαντινών ναών και ναών της εποχής των Σταυροφοριών. Ο τόπος αποτελεί προορισμό χριστιανικού προσκυνήματος από τους αρχαίους χρόνους.', 'Ο ναός εξυπηρετεί την τοπική καθολική κοινότητα της Ναζαρέτ και υποδέχεται προσκυνητές από όλο τον κόσμο. Τακτικές λειτουργίες τελούνται σε πολλές γλώσσες.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'el', 'Ο Ναός της Γεννήσεως στη Βηθλεέμ υψώνεται πάνω από το σπήλαιο που η χριστιανική παράδοση τιμά από τον 2ο αιώνα ως τον τόπο γέννησης του Ιησού. Είναι ένας από τους παλαιότερους ναούς σε συνεχή χρήση στον κόσμο και Μνημείο Παγκόσμιας Κληρονομιάς της UNESCO.', 'Η πρώτη βασιλική ανεγέρθηκε κατ'' εντολή του αυτοκράτορα Κωνσταντίνου και της μητέρας του Ελένης γύρω στο 327 μ.Χ. Αφού υπέστη ζημιές τον 6ο αιώνα, ο αυτοκράτορας Ιουστινιανός την ανοικοδόμησε σε μεγαλύτερη κλίμακα, και μεγάλο μέρος του σημερινού ναού χρονολογείται από εκείνη την ανοικοδόμηση. Ψηφιδωτά και ζωγραφισμένοι κίονες της εποχής των Σταυροφοριών σώζονται ακόμη στο εσωτερικό.', 'Ο ναός μοιράζεται μεταξύ των κοινοτήτων των Ελληνορθόδοξων, των Ρωμαιοκαθολικών (Φραγκισκανών) και των Αρμενίων Αποστολικών, σύμφωνα με την ιστορική συμφωνία του Καθεστώτος Status Quo. Οι τοπικές χριστιανικές οικογένειες της Βηθλεέμ προσεύχονται εδώ μαζί με προσκυνητές από όλο τον κόσμο, ιδίως τα Χριστούγεννα.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'el', 'Ο Ναός της Αναστάσεως στην Παλιά Πόλη της Ιερουσαλήμ περιλαμβάνει τους δύο ιερότερους τόπους του Χριστιανισμού: τον Γολγοθά, όπου σταυρώθηκε ο Ιησούς, και τον τάφο όπου, σύμφωνα με την παράδοση, ενταφιάστηκε και αναστήθηκε.', 'Ο αυτοκράτορας Κωνσταντίνος έχτισε εδώ τον πρώτο ναό τον 4ο αιώνα· τα εγκαίνιά του τελέστηκαν το 335 μ.Χ. Καταστράφηκε το 1009 και ανοικοδομήθηκε τον 11ο αιώνα, ενώ οι Σταυροφόροι του έδωσαν σε μεγάλο βαθμό τη σημερινή του μορφή τον 12ο αιώνα. Το Κουβούκλιο πάνω από τον Τάφο αναστηλώθηκε το 2016–2017.', 'Τη φροντίδα του ναού μοιράζονται οι Ελληνορθόδοξοι, οι Ρωμαιοκαθολικοί (Φραγκισκανοί) και οι Αρμένιοι Αποστολικοί, ενώ οι κοπτική, αιθιοπική και συριακή ορθόδοξη κοινότητα διατηρούν επίσης δικά τους παρεκκλήσια, σύμφωνα με το Καθεστώς Status Quo του 1852. Οι πύλες του ανοίγουν κάθε πρωί από μουσουλμανικές οικογένειες που φυλάσσουν τα κλειδιά επί αιώνες.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'el', 'Η Βασιλική Όλων των Εθνών, γνωστή και ως Βασιλική της Αγωνίας, είναι ρωμαιοκαθολικός ναός στη Γεθσημανή, στο Όρος των Ελαιών της Ιερουσαλήμ. Περικλείει το τμήμα του βράχου που η παράδοση ταυτίζει με τον τόπο όπου ο Ιησούς προσευχήθηκε εν αγωνία τη νύχτα πριν από τη σταύρωσή του.', 'Η σημερινή βασιλική χτίστηκε μεταξύ 1919 και 1924 πάνω στα θεμέλια προγενέστερων βυζαντινών και σταυροφορικών ναών, που αποκαλύφθηκαν κατά την ανέγερση. Έγινε γνωστή ως Βασιλική Όλων των Εθνών επειδή δωρεές από πολλές χώρες χρηματοδότησαν την κατασκευή της, και τα εθνόσημά τους είναι ενσωματωμένα στην οροφή.', 'Της βασιλικής φροντίδα έχει η Φραγκισκανική Κουστωδία των Αγίων Τόπων, που συντηρεί τον χώρο και τον γειτονικό Κήπο της Γεθσημανή με τις αρχαίες ελιές του. Παραμένει ενεργός τόπος προσευχής και σημαντικός σταθμός για τους προσκυνητές που επισκέπτονται το Όρος των Ελαιών.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'el', 'Ο Ναός της Αγίας Μαρίας Μαγδαληνής είναι ρωσικός ορθόδοξος ναός στη δυτική πλαγιά του Όρους των Ελαιών στην Ιερουσαλήμ, κοντά στον Κήπο της Γεθσημανή. Είναι ευρέως αναγνωρίσιμος για τους επτά επίχρυσους βολβοειδείς τρούλους του, χαρακτηριστικό ορόσημο του ορίζοντα της Ιερουσαλήμ.', 'Ο ναός χτίστηκε μεταξύ 1886 και 1888 από τον τσάρο Αλέξανδρο Γʹ της Ρωσίας στη μνήμη της μητέρας του, της αυτοκράτειρας Μαρίας Αλεξάνδροβνα. Αφιερώθηκε στη Μαρία τη Μαγδαληνή, την αγία από την οποία πήρε το όνομά της η αυτοκράτειρα, και αντικατοπτρίζει τη ρωσική παρουσία στους Αγίους Τόπους στα τέλη του 19ου αιώνα.', 'Ο ναός ανήκει σε μονή ορθοδόξων μοναζουσών και παραμένει ενεργή μοναστική κοινότητα που υποδέχεται επισκέπτες και προσκυνητές. Υψώνεται στο περιβάλλον της Γεθσημανή, στις πλαγιές του Όρους των Ελαιών.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'el', 'Το Dominus Flevit, που στα λατινικά σημαίνει «ο Κύριος έκλαψε», είναι ρωμαιοκαθολικό παρεκκλήσι στη δυτική πλαγιά του Όρους των Ελαιών στην Ιερουσαλήμ. Σηματοδοτεί τον τόπο όπου, σύμφωνα με το κατά Λουκάν Ευαγγέλιο, ο Ιησούς έκλαψε καθώς αντίκριζε την Ιερουσαλήμ και προείπε την καταστροφή της.', 'Το σημερινό παρεκκλήσι χτίστηκε το 1955 στον χώρο προγενέστερων θρησκευτικών κτισμάτων, μεταξύ των οποίων λείψανα ναού βυζαντινής εποχής. Οι ανασκαφές στον χώρο έφεραν επίσης στο φως αρχαίους τάφους και οστεοφυλάκια, μαρτυρία της μακράς χρήσης της πλαγιάς ως τόπου ταφής.', 'Το Dominus Flevit το φροντίζει η Φραγκισκανική Κουστωδία των Αγίων Τόπων, στο πλαίσιο του δικτύου προσκυνημάτων της στην Ιερουσαλήμ και τα περίχωρά της. Είναι συχνός σταθμός για τους προσκυνητές που κατεβαίνουν το Όρος των Ελαιών προς τη Γεθσημανή.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'el', 'Ο Ναός της Αγίας Άννας είναι ρωμαιοκαθολικός ναός στην Παλιά Πόλη της Ιερουσαλήμ, στη μουσουλμανική συνοικία, δίπλα στις κολυμβήθρες της Βηθεσδά. Υψώνεται πάνω από τόπο που τιμάται από την παράδοση ως το σπίτι της Άννας και του Ιωακείμ και ο τόπος γέννησης της Παρθένου Μαρίας.', 'Ο ναός χτίστηκε τον 12ο αιώνα, κατά τη διάρκεια του σταυροφορικού Βασιλείου της Ιερουσαλήμ. Μετά την κατάκτηση της πόλης από τον Σαλαδίνο το 1187 μετατράπηκε σε ισλαμική σχολή, και τον 19ο αιώνα οι οθωμανικές αρχές τον παραχώρησαν στη Γαλλία, της οποίας οι υπεύθυνοι αποκατέστησαν το κτίριο.', 'Ο ναός και ο περίβολός του είναι εμπιστευμένοι στους Ιεραποστόλους της Αφρικής, κοινώς γνωστούς ως Λευκούς Πατέρες, που φροντίζουν τον χώρο και υποδέχονται τους προσκυνητές. Παραμένει ενεργός τόπος προσευχής και μελέτης εντός της Παλιάς Πόλης.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'el', 'Ο Ναός Pater Noster είναι ρωμαιοκαθολικός ναός και μονή Καρμηλιτών στο Όρος των Ελαιών στην Ιερουσαλήμ. Υψώνεται σε τόπο που η παράδοση συνδέει με τη διδασκαλία, από τον Ιησού προς τους μαθητές του, της Κυριακής Προσευχής, γνωστής στα λατινικά ως Pater Noster.', 'Ο χώρος διατηρεί τη μνήμη του βυζαντινού ναού της Ελεώνας, που ανεγέρθηκε τον 4ο αιώνα πάνω από σπήλαιο του Όρους των Ελαιών επί Κωνσταντίνου. Ύστερα από αιώνες ερείπωσης, τον 19ο αιώνα ιδρύθηκε εδώ γαλλική μονή, και η κατασκευή των ναϊκών κτισμάτων συνεχίστηκε μέσα στον 20ό αιώνα.', 'Τον χώρο φροντίζει κοινότητα Καρμηλιτισσών αδελφών, που συντηρούν τη μονή, τον ναό και το περιστύλιο. Είναι σύνηθης σταθμός για προσκυνητές και επισκέπτες που εξερευνούν το Όρος των Ελαιών.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'el', 'Ο Ναός της Επίσκεψης είναι ρωμαιοκαθολικός ναός στο χωριό Έιν Κάρεμ, στο δυτικό άκρο της Ιερουσαλήμ. Σηματοδοτεί τον παραδοσιακό τόπο όπου η Μαρία επισκέφθηκε τη συγγενή της Ελισάβετ και, σύμφωνα με το κατά Λουκάν Ευαγγέλιο, εκφώνησε τον ύμνο γνωστό ως Magnificat. Τον χώρο φροντίζουν οι Φραγκισκανοί και αποτελεί ευρέως επισκεπτόμενο προορισμό για τους προσκυνητές στους Αγίους Τόπους.', 'Η χριστιανική παράδοση ταυτίζει το Έιν Κάρεμ με το γενέθλιο χωριό του Ζαχαρία και της Ελισάβετ και με το σκηνικό της Επίσκεψης που περιγράφεται στο κατά Λουκάν Ευαγγέλιο. Ναός υψωνόταν στον χώρο κατά τη βυζαντινή και τη σταυροφορική περίοδο, και το σημερινό διώροφο κτίριο διατηρεί στοιχεία αυτών των προγενέστερων κατασκευών. Ο σημερινός ναός διαμορφώθηκε στο πρώτο μισό του 20ού αιώνα υπό τη Φραγκισκανική Κουστωδία των Αγίων Τόπων.', 'Ο χώρος ανήκει στη Φραγκισκανική Κουστωδία των Αγίων Τόπων και συντηρείται από αυτήν, που φροντίζει πλήθος προσκυνημάτων σε όλη την περιοχή. Παραμένει ενεργός τόπος προσευχής και σύνηθης σταθμός στις προσκυνηματικές διαδρομές μέσα από το Έιν Κάρεμ, το οποίο περιλαμβάνει και άλλους ναούς συνδεδεμένους με τη γέννηση του Ιωάννη του Βαπτιστή.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'el', 'Ο Ναός των Μακαρισμών είναι ρωμαιοκαθολικός ναός σε λόφο πάνω από τη βορειοδυτική ακτή της Θάλασσας της Γαλιλαίας. Σηματοδοτεί τον παραδοσιακό τόπο της Επί του Όρους Ομιλίας και παίρνει το όνομά του από τους Μακαρισμούς, τις ευλογίες με τις οποίες ανοίγει η ομιλία στο κατά Ματθαίον Ευαγγέλιο. Ο χώρος προσφέρει ευρεία θέα στη λίμνη και στα γύρω χωριά.', 'Η παράδοση που τοποθετεί σε λόφο κοντά στην Καπερναούμ τον τόπο της Επί του Όρους Ομιλίας είναι παλαιά, και προγενέστερα λείψανα έχουν επισημανθεί στην περιοχή της Ταμπγκά, πιο κάτω. Ο σημερινός ναός χτίστηκε το 1938 σε σχέδια του Ιταλού αρχιτέκτονα Αντόνιο Μπαρλούτσι. Η κατασκευή του υποστηρίχθηκε εν μέρει από χρηματοδότηση της Ιταλίας.', 'Τον ναό και τον περίβολό του φροντίζουν οι Φραγκισκανές Ιεραπόστολες Αδελφές της Ιεράς Καρδίας. Ο χώρος λειτουργεί τόσο ως τόπος λατρείας όσο και ως ευρέως επισκεπτόμενος προσκυνηματικός προορισμός στη Γαλιλαία.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'el', 'Ο Ναός του Πολλαπλασιασμού των Άρτων είναι ρωμαιοκαθολικός ναός στην Ταμπγκά, στη βορειοδυτική ακτή της Θάλασσας της Γαλιλαίας. Μνημονεύει την ευαγγελική αφήγηση του πολλαπλασιασμού των άρτων και των ιχθύων, με τους οποίους τράφηκε ένα πλήθος. Ο ναός είναι γνωστός για τα παλαιοχριστιανικά ψηφιδωτά δάπεδά του.', 'Η Ταμπγκά τιμήθηκε κατά τη βυζαντινή περίοδο ως ο τόπος του θαύματος, και ένα μικρό παρεκκλήσι του 4ου αιώνα αντικαταστάθηκε αργότερα από μεγαλύτερο ναό τον 5ο αιώνα. Αυτά τα πρώιμα κτίσματα ερειπώθηκαν, και τα λείψανά τους ανακαλύφθηκαν εκ νέου και ανασκάφηκαν στους νεότερους χρόνους. Ο σημερινός ναός, χτισμένος τον 20ό αιώνα, αναπαράγει την κάτοψη της βυζαντινής βασιλικής.', 'Τον ναό υπηρετούν Γερμανοί Βενεδικτίνοι μοναχοί συνδεδεμένοι με το Αββαείο της Κοιμήσεως στην Ιερουσαλήμ. Παραμένει ενεργός μοναστικός και προσκυνηματικός τόπος· πυρκαγιά προκάλεσε ζημιές σε τμήματα του συγκροτήματος το 2015, μετά την οποία αποκαταστάθηκε.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'el', 'Ο Ναός του Πρωτείου του Αγίου Πέτρου είναι μικρό ρωμαιοκαθολικό παρεκκλήσι στην Ταμπγκά, στην ακτή της Θάλασσας της Γαλιλαίας. Μνημονεύει μια εμφάνιση του Ιησού στους μαθητές του μετά την ανάσταση, που περιγράφεται στο κατά Ιωάννην Ευαγγέλιο, και την απονομή του πρωτείου στον Πέτρο. Το παρεκκλήσι υψώνεται ακριβώς δίπλα στο νερό.', 'Ο χώρος ανακαλεί την αφήγηση του Ιωάννη κεφ. 21, όπου ο αναστημένος Ιησούς εμφανίζεται στους μαθητές δίπλα στη λίμνη, μοιράζεται μαζί τους γεύμα από ψωμί και ψάρι και αναθέτει τρεις φορές στον Πέτρο να ποιμαίνει το ποίμνιό του. Σε προγενέστερους αιώνες υπήρχε εδώ ναός συνδεδεμένος με αυτή την παράδοση, και ίχνη προγενέστερων κατασκευών σώζονται πλησίον. Το σημερινό παρεκκλήσι χτίστηκε το 1933.', 'Το παρεκκλήσι το φροντίζει η Φραγκισκανική Κουστωδία των Αγίων Τόπων. Είναι συχνός σταθμός για τους προσκυνητές που επισκέπτονται τους τόπους γύρω από τη βόρεια ακτή της Θάλασσας της Γαλιλαίας.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'el', 'Ο Ναός της Μεταμορφώσεως είναι ρωμαιοκαθολική βασιλική στην κορυφή του Όρους Θαβώρ, που υψώνεται πάνω από την κοιλάδα του Ιζρεέλ, στην Κάτω Γαλιλαία. Μνημονεύει τη Μεταμόρφωση του Ιησού, όταν, σύμφωνα με τα Ευαγγέλια, εμφανίστηκε μεταμορφωμένος παρουσία του Μωυσή και του Ηλία. Ένας ελληνορθόδοξος ναός υψώνεται επίσης αλλού στο όρος.', 'Το Όρος Θαβώρ τιμάται από τη βυζαντινή περίοδο ως ο παραδοσιακός τόπος της Μεταμόρφωσης, και ναοί χτίστηκαν εδώ στους βυζαντινούς και σταυροφορικούς χρόνους. Τα κτίσματα αυτά αργότερα ερειπώθηκαν, και τα θεμέλιά τους παραμένουν στην κορυφή. Η σημερινή βασιλική ολοκληρώθηκε το 1924.', 'Τη βασιλική και τον περίβολό της φροντίζει η Φραγκισκανική Κουστωδία των Αγίων Τόπων. Το όρος παραμένει προσκυνηματικός προορισμός, και η κορυφή μοιράζεται με ελληνορθόδοξη μονή και ναό.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'el', 'Ο φραγκισκανικός Ναός του Γάμου υψώνεται στο Καφρ Κάνα, τον οικισμό που ευρέως ταυτίζεται με την Κανά της Γαλιλαίας των Ευαγγελίων, βόρεια της Ναζαρέτ. Μνημονεύει το γαμήλιο συμπόσιο στο οποίο, σύμφωνα με το κατά Ιωάννην Ευαγγέλιο, ο Ιησούς μετέτρεψε το νερό σε κρασί, που περιγράφεται ως το πρώτο από τα σημεία του. Ο χώρος προσελκύει προσκυνητές, και ιδίως παντρεμένα ζευγάρια, που έρχονται να τιμήσουν και να ανανεώσουν τους όρκους τους.', 'Το κατά Ιωάννην Ευαγγέλιο (κεφάλαιο 2) τοποθετεί τον Ιησού, τη μητέρα του και τους μαθητές του σε γάμο στην Κανά, όπου ο οικοδεσπότης έμεινε από κρασί και ο Ιησούς έβαλε να γεμίσουν με νερό έξι πέτρινες υδρίες, το οποίο έγινε κρασί. Στο πέρασμα των αιώνων αναπτύχθηκε στο Καφρ Κάνα εκκλησιαστική παράδοση που τιμά το θαύμα, και στον σημερινό χώρο ή κοντά του υπήρχαν προγενέστεροι τόποι λατρείας. Ο σημερινός φραγκισκανικός ναός χτίστηκε μεταξύ 1879 και 1905.', 'Τον Ναό του Γάμου φροντίζουν οι Φραγκισκανοί αδελφοί της Κουστωδίας των Αγίων Τόπων, που τον διατηρούν ως τόπο λατρείας και προσκυνήματος. Ένας ξεχωριστός ελληνορθόδοξος ναός στο Καφρ Κάνα διατηρεί επίσης πλησίον την παράδοση του θαύματος.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'el', 'Η Καπερναούμ, στη βόρεια ακτή της Θάλασσας της Γαλιλαίας, είναι η παραλίμνια πόλη που τα Ευαγγέλια περιγράφουν ως κέντρο της δράσης του Ιησού στη Γαλιλαία. Ο αρχαιολογικός χώρος διατηρεί τα λείψανα που τιμώνται ως η οικία του αποστόλου Πέτρου και μια αρχαία συναγωγή. Είναι ένας από τους σημαντικότερους τόπους της Καινής Διαθήκης στην περιοχή.', 'Τα Ευαγγέλια παρουσιάζουν την Καπερναούμ ως τον τόπο όπου ο Ιησούς δίδαξε, κάλεσε μαθητές και θεράπευσε, και συνδέουν την πόλη με τον Πέτρο και άλλους ακολούθους. Από τους πρώτους αιώνες οι χριστιανοί τιμούσαν μια οικία στον χώρο, που αργότερα περικλείστηκε σε οκταγωνικό ναό. Η πόλη κατοικήθηκε επί αιώνες προτού παρακμάσει, αφήνοντας τα ερείπια που μελετούν οι σύγχρονοι αρχαιολόγοι.', 'Ο χώρος ανήκει στη Φραγκισκανική Κουστωδία των Αγίων Τόπων και φροντίζεται από αυτήν, που επιβλέπει τον ναό, τις ανασκαφές και την πρόσβαση προσκυνητών και επισκεπτών. Στο ανατολικό άκρο της περιοχής υψώνονται ξεχωριστός ελληνορθόδοξος ναός και μονή.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'el', 'Το Παρεκκλήσι του Αγρού των Ποιμένων υψώνεται στο Μπέιτ Σαχούρ, ανατολικά της Βηθλεέμ, στον τόπο που η παράδοση ταυτίζει με τους αγρούς των ποιμένων της αφήγησης της Γέννησης. Σύμφωνα με το κατά Λουκάν Ευαγγέλιο, εκεί οι άγγελοι ανήγγειλαν τη γέννηση του Ιησού σε ποιμένες που φύλαγαν τη νύχτα τα κοπάδια τους. Το παρεκκλήσι και ο περίβολός του είναι τόπος προσευχής και προσκυνήματος, ιδίως τα Χριστούγεννα.', 'Το κατά Λουκάν Ευαγγέλιο (κεφάλαιο 2) περιγράφει ποιμένες κοντά στη Βηθλεέμ στους οποίους αναγγέλθηκε η γέννηση του Σωτήρα και οι οποίοι πήγαν να βρουν το βρέφος. Η χριστιανική τιμή προς τους αγρούς των ποιμένων κοντά στο Μπέιτ Σαχούρ είναι πολύ παλαιά, και στην περιοχή έχουν βρεθεί λείψανα προγενέστερων ναών και μοναστικών κτισμάτων. Το σημερινό φραγκισκανικό παρεκκλήσι χτίστηκε το 1953.', 'Το παρεκκλήσι και τον αγρό του φροντίζει η Φραγκισκανική Κουστωδία των Αγίων Τόπων. Πλησίον, στην ίδια περιοχή του Μπέιτ Σαχούρ, βρίσκεται ξεχωριστός ελληνορθόδοξος Αγρός των Ποιμένων, με δικό του ναό και αρχαία λείψανα.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'el', 'Το Σπήλαιο του Γάλακτος είναι παρεκκλήσι χτισμένο γύρω από ένα σπήλαιο μαλακής λευκής κιμωλίας στη Βηθλεέμ, σε μικρή απόσταση από τον Ναό της Γεννήσεως. Η παράδοση συνδέει το σπήλαιο με την Αγία Οικογένεια, συσχετίζοντάς το με τον χρόνο πριν από τη φυγή στην Αίγυπτο ή κατά τη διάρκειά της. Είναι ένας ήσυχος τόπος προσευχής, που επισκέπτονται ιδίως μητέρες και ζευγάρια που ελπίζουν να αποκτήσουν παιδιά.', 'Η τοπική παράδοση θέλει την Αγία Οικογένεια να βρήκε καταφύγιο σε αυτό το σπήλαιο και τον βράχο του να έγινε λευκός, εξ ου και το όνομα και οι λατρευτικές πρακτικές που συνδέονται με το γάλα και τη μητρότητα. Η χριστιανική τιμή προς τον χώρο τεκμηριώνεται επί πολλούς αιώνες. Το σπήλαιο βρίσκεται από παλαιά υπό φραγκισκανική φροντίδα, και στη νεότερη εποχή προστέθηκε ένα νεότερο παρεκκλήσι δίπλα στο παλαιό ιερό.', 'Το Σπήλαιο του Γάλακτος το φροντίζει η Φραγκισκανική Κουστωδία των Αγίων Τόπων, που το διατηρεί ως τόπο προσευχής και υποδέχεται προσκυνητές από πολλές χώρες. Παραμένει εστία προσωπικής ευλάβειας, ιδίως για όσους προσεύχονται για μητρότητα και οικογένεια.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
