INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'fr', 'Restauration', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'fr', 'Ce projet porte sur les besoins essentiels de restauration de la basilique, notamment les réparations structurelles, le nettoyage de la façade et la préservation des éléments architecturaux d''origine. Ces travaux garantiront que le bâtiment reste sûr et accessible pour les générations futures.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'fr', 'Restauration de la nef principale et de la façade de la Basilique de l''Annonciation.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'fr', 'Restauration de la basilique - Phase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'fr', 'Documentation', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'fr', 'Une initiative d''envergure visant à photographier, numériser et documenter les sites, objets et manuscrits du patrimoine chrétien en Israël et dans les régions environnantes. Cette archive numérique préservera des documents historiques inestimables pour les chercheurs et pour les générations futures.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'fr', 'Documentation numérique des sites du patrimoine chrétien à travers toute la Terre Sainte.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'fr', 'Documentation du patrimoine de Terre Sainte', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'he', 'בזיליקת הבשורה היא כנסייה קתולית בנצרת, ישראל. זוהי אחת הכנסיות הגדולות במזרח התיכון ומציינת את המקום המסורתי שבו בישר המלאך גבריאל למרים שהיא תלד את ישו.', 'הבזיליקה הנוכחית נבנתה ב-1969, בתכנון האדריכל האיטלקי ג''ובאני מוציו. היא ניצבת על חורבות כנסיות ביזנטיות וצלבניות קודמות. האתר היה מקום עלייה לרגל נוצרי מאז ימי קדם.', 'הכנסייה משרתת את הקהילה הקתולית המקומית בנצרת ומקבלת בברכה עולי רגל מכל רחבי העולם. מיסות מתקיימות באופן קבוע בשפות מרובות.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'he', 'כנסיית המולד בבית לחם ניצבת מעל המערה שהמסורת הנוצרית מכבדת מאז המאה ה-2 כמקום הולדתו של ישוע. זוהי אחת הכנסיות העתיקות ביותר הפועלות ברציפות בעולם, ואתר מורשת עולמית של אונסק"ו.', 'הבזיליקה הראשונה נבנתה ביוזמת הקיסר קונסטנטינוס ואמו הלנה בסביבות שנת 327 לספירה. לאחר שניזוקה במאה ה-6, שיקם אותה הקיסר יוסטיניאנוס בקנה מידה גדול יותר, וחלק ניכר מהכנסייה של היום מקורו בבנייה מחדש זו. פסיפסים ועמודים מצוירים מתקופת הצלבנים עדיין שרדו בפנים.', 'הכנסייה משותפת לקהילות היוונית-אורתודוקסית, הקתולית (הפרנציסקנית) והארמנית-אפוסטולית, במסגרת הסדר הסטטוס קוו ההיסטורי. משפחות נוצריות מקומיות מבית לחם מתפללות בה לצד עולי רגל מכל רחבי העולם, במיוחד בחג המולד.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'he', 'כנסיית הקבר בעיר העתיקה בירושלים כוללת את שני האתרים הקדושים ביותר בנצרות: גולגותא, שבה נצלב ישוע, והקבר שבו נקבר וקם לתחייה, לפי המסורת.', 'הקיסר קונסטנטינוס בנה כאן את הכנסייה הראשונה במאה ה-4; היא הוקדשה בשנת 335 לספירה. היא נהרסה בשנת 1009 ונבנתה מחדש במאה ה-11, והצלבנים העניקו לה את רוב צורתה הנוכחית במאה ה-12. האדיקולה שמעל הקבר שוחזרה בשנים 2016–2017.', 'הטיפול בכנסייה משותף לכנסיות היוונית-אורתודוקסית, הקתולית (הפרנציסקנית) והארמנית-אפוסטולית, כאשר גם לקהילות הקופטית, האתיופית והסורית-אורתודוקסית יש בה קפלות, במסגרת הסטטוס קוו משנת 1852. דלתותיה נפתחות מדי בוקר בידי משפחות מוסלמיות ששומרות על מפתחותיה במשך מאות שנים.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'he', 'כנסיית כל העמים, הידועה גם כבזיליקת הייסורים, היא כנסייה קתולית בגת שמנים שעל הר הזיתים בירושלים. היא חופפת את קטע הסלע שהמסורת מזהה כמקום שבו התפלל ישוע בייסוריו בלילה שקדם לצליבתו.', 'הבזיליקה הנוכחית נבנתה בין 1919 ל-1924 על יסודות של כנסיות ביזנטיות וצלבניות קודמות שנחשפו במהלך הבנייה. היא נודעה בשם כנסיית כל העמים משום שתרומות ממדינות רבות מימנו את הקמתה, וסמלי הנשק שלהן משובצים בתקרה.', 'בבזיליקה מטפלת משמורת ארץ הקודש הפרנציסקנית, המתחזקת את האתר ואת גן גת שמנים הסמוך על עצי הזית העתיקים שבו. היא נותרה מקום תפילה פעיל ותחנה מרכזית לצליינים המבקרים בהר הזיתים.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'he', 'כנסיית מרים המגדלית היא כנסייה רוסית אורתודוקסית במדרון המערבי של הר הזיתים בירושלים, סמוך לגן גת שמנים. היא מוכרת היטב בזכות שבע כיפות הבצל המוזהבות שלה, ציון דרך ייחודי בקו הרקיע של ירושלים.', 'הכנסייה נבנתה בין 1886 ל-1888 בידי הצאר אלכסנדר השלישי מרוסיה לזכר אמו, הקיסרית מריה אלכסנדרובנה. היא הוקדשה למרים המגדלית, הקדושה שעל שמה נקראה הקיסרית, והיא משקפת את הנוכחות הרוסית בארץ הקודש בשלהי המאה התשע-עשרה.', 'הכנסייה שייכת למנזר של נזירות אורתודוקסיות ונותרה קהילה נזירית פעילה המקבלת מבקרים וצליינים. היא ניצבת בתחומי גת שמנים על מדרונות הר הזיתים.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'he', 'דומינוס פלוויט, שפירושו בלטינית «האדון בכה», היא קפלה קתולית במדרון המערבי של הר הזיתים בירושלים. היא מציינת את המקום שבו, על פי בשורת לוקאס, בכה ישוע כשהביט אל ירושלים וניבא את חורבנה.', 'הקפלה הנוכחית נבנתה ב-1955 על אתר של מבנים דתיים קודמים, ובהם שרידי כנסייה מן התקופה הביזנטית. חפירות בשטח חשפו גם קברים ומכלי עצמות עתיקים, המעידים על שימוש ממושך במדרון כמקום קבורה.', 'בדומינוס פלוויט מטפלת משמורת ארץ הקודש הפרנציסקנית כחלק מרשת המקדשים שלה בירושלים ובסביבתה. זו תחנה תכופה לצליינים היורדים במורד הר הזיתים אל גת שמנים.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'he', 'כנסיית חנה הקדושה היא כנסייה קתולית בעיר העתיקה של ירושלים, ברובע המוסלמי לצד בריכות בית חסדא. היא ניצבת מעל אתר שהמסורת מקדשת כביתם של חנה ויואכים וכמקום הולדתה של מרים הבתולה.', 'הכנסייה נבנתה במאה השתים-עשרה בתקופת ממלכת ירושלים הצלבנית. לאחר כיבוש העיר בידי צלאח א-דין ב-1187 היא הוסבה למדרסה אסלאמית, ובמאה התשע-עשרה העניקו אותה השלטונות העות''מאניים לצרפת, שהאחראים מטעמה שיקמו את המבנה.', 'הכנסייה ושטחה מופקדים בידי מיסיונרי אפריקה, המוכרים בכינוי האבות הלבנים, המטפלים באתר ומקבלים צליינים. היא נותרה מקום תפילה ולימוד פעיל בתוך העיר העתיקה.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'he', 'כנסיית פאטר נוסטר היא כנסייה קתולית ומנזר כרמליטי על הר הזיתים בירושלים. היא ניצבת על אתר המקושר במסורת עם לימוד תלמידיו של ישוע את תפילת האדון, הידועה בלטינית בשם «פאטר נוסטר» (אבינו שבשמיים).', 'האתר משמר את זכר כנסיית האלאונה הביזנטית, שנבנתה במאה הרביעית מעל מערה על הר הזיתים בימי קונסטנטינוס. לאחר מאות שנים של חורבן הוקם כאן מנזר צרפתי במאה התשע-עשרה, ובניית מבני הכנסייה נמשכה אל תוך המאה העשרים.', 'באתר מטפלת קהילה של נזירות כרמליטיות, המתחזקות את המנזר, הכנסייה והקלויסטר. זו תחנה קבועה לצליינים ולמבקרים החוקרים את הר הזיתים.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'he', 'כנסיית הביקור היא כנסייה קתולית בכפר עין כרם, בשוליה המערביים של ירושלים. היא מציינת את האתר המסורתי שבו ביקרה מרים את קרובתה אלישבע ואמרה, על פי בשורת לוקאס, את השיר הידוע בשם מגניפיקט. באתר מטפלים הפרנציסקנים והוא יעד מבוקר לצליינים לארץ הקודש.', 'המסורת הנוצרית מזהה את עין כרם ככפר מגוריהם של זכריה ואלישבע וכזירת הביקור המתואר בבשורת לוקאס. כנסייה עמדה באתר בתקופות הביזנטית והצלבנית, והמבנה הנוכחי בן שתי הקומות משמר יסודות של מבנים קודמים אלה. הכנסייה הנוכחית פותחה במחצית הראשונה של המאה העשרים תחת משמורת ארץ הקודש הפרנציסקנית.', 'האתר בבעלות משמורת ארץ הקודש הפרנציסקנית ובאחזקתה, המטפלת במקדשים רבים ברחבי האזור. הוא נותר מקום תפילה פעיל ותחנה קבועה במסלולי העלייה לרגל בעין כרם, שבה נמצאות גם כנסיות נוספות הקשורות בלידת יוחנן המטביל.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'he', 'כנסיית האושר היא כנסייה קתולית על גבעה מעל החוף הצפון-מערבי של הכנרת. היא מציינת את האתר המסורתי של הדרשה על ההר, ושמה נגזר מן האשרות, הברכות הפותחות את הדרשה בבשורת מתי. האתר מציע תצפית רחבה על האגם ועל היישובים הסובבים אותו.', 'המסורת המזהה גבעה סמוך לכפר נחום כמקום הדרשה על ההר עתיקת יומין, ושרידים קודמים צוינו בסביבת טבחה שמתחתיה. הכנסייה הנוכחית נבנתה ב-1938 בתכנון האדריכל האיטלקי אנטוניו ברלוצי. הקמתה נתמכה בין השאר במימון מאיטליה.', 'בכנסייה ובשטחה מטפלות האחיות הפרנציסקניות המיסיונריות של הלב הקדוש. האתר משמש הן מקום פולחן והן יעד עלייה לרגל מבוקר בגליל.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'he', 'כנסיית הלחם והדגים היא כנסייה קתולית בטבחה, על החוף הצפון-מערבי של הכנרת. היא מנציחה את סיפור הבשורות על הכפלת הלחם והדגים, שבה הואכל קהל רב. הכנסייה ידועה ברצפות הפסיפס הנוצריות הקדומות שלה.', 'טבחה נערצה בתקופה הביזנטית כאתר הנס, ובמקום קפלה קטנה מן המאה הרביעית באה במאה החמישית כנסייה גדולה יותר. מבנים קדומים אלה נפלו לחורבן, ושרידיהם נתגלו מחדש ונחפרו בעת החדשה. הכנסייה הנוכחית, שנבנתה במאה העשרים, משחזרת את תכנית הבזיליקה הביזנטית.', 'בכנסייה משרתים נזירים בנדיקטינים גרמנים הקשורים במנזר הדורמיציון בירושלים. היא נותרה אתר נזירי ועלייה לרגל פעיל; שרפה פגעה בחלקים מן המתחם ב-2015, ולאחריה שוקם.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'he', 'כנסיית הבכורה של פטרוס הקדוש היא קפלה קתולית קטנה בטבחה, על חוף הכנרת. היא מנציחה התגלות של ישוע לתלמידיו לאחר תחייתו, המתוארת בבשורת יוחנן, ואת הענקת הבכורה לפטרוס. הקפלה ניצבת ממש לצד המים.', 'האתר מזכיר את המסופר בבשורת יוחנן (פרק 21), שבו ישוע הקם לתחייה נגלה לתלמידים ליד האגם, סועד עמם ארוחת לחם ודגים, ומצווה שלוש פעמים על פטרוס לרעות את צאנו. כנסייה הקשורה במסורת זו התקיימה כאן במאות קודמות, ושרידי מבנים קדומים נותרו בסמוך. הקפלה הנוכחית נבנתה ב-1933.', 'בקפלה מטפלת משמורת ארץ הקודש הפרנציסקנית. זו תחנה תכופה לצליינים המבקרים באתרים שלאורך חופה הצפוני של הכנרת.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'he', 'כנסיית ההשתנות היא בזיליקה קתולית על פסגת הר תבור, המתנשא מעל עמק יזרעאל בגליל התחתון. היא מנציחה את השתנות ישוע, שבה, על פי הבשורות, נראה משתנה בנוכחות משה ואליהו. כנסייה יוונית-אורתודוקסית ניצבת אף היא במקום אחר על ההר.', 'הר תבור נערץ מאז התקופה הביזנטית כמקום המסורתי של ההשתנות, וכנסיות נבנו בו בתקופות הביזנטית והצלבנית. מבנים אלה חרבו לימים, ויסודותיהם נותרו על הפסגה. הבזיליקה הנוכחית הושלמה ב-1924.', 'בבזיליקה ובשטחה מטפלת משמורת ארץ הקודש הפרנציסקנית. ההר נותר יעד עלייה לרגל, והפסגה משותפת עם מנזר וכנסייה יווניים-אורתודוקסיים.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'he', 'כנסיית החתונה הפרנציסקנית ניצבת בכפר כנא, היישוב המזוהה בהרחבה עם כנא הגלילית שבבשורות, מצפון לנצרת. היא מנציחה את משתה החתונה שבו, על פי בשורת יוחנן, הפך ישוע מים ליין, מעשה המתואר כראשון לאותותיו. האתר מושך צליינים, ובמיוחד זוגות נשואים הבאים לציין ולחדש את נדריהם.', 'בשורת יוחנן (פרק 2) ממקמת את ישוע, אמו ותלמידיו בחתונה בכנא, שם אזל היין למארח וישוע ציווה למלא שש כדי אבן במים שהפכו ליין. מסורת כנסייתית המכבדת את הנס בכפר כנא התפתחה לאורך הדורות, ומקומות פולחן קודמים עמדו על האתר הנוכחי או בסמוך לו. הכנסייה הפרנציסקנית הנוכחית נבנתה בין 1879 ל-1905.', 'בכנסיית החתונה מטפלים הנזירים הפרנציסקנים של משמורת ארץ הקודש, המחזיקים בה כמקום פולחן ועלייה לרגל. כנסייה יוונית-אורתודוקסית נפרדת בכפר כנא משמרת אף היא את מסורת הנס בקרבת מקום.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'he', 'כפר נחום, בחוף הצפוני של הכנרת, היא עיירת החוף שהבשורות מתארות כמרכז פעילותו של ישוע בגליל. האתר הארכיאולוגי משמר את השרידים הנערצים כביתו של השליח פטרוס וכבית כנסת עתיק. זהו אחד מאתרי הברית החדשה החשובים ביותר באזור.', 'הבשורות מציגות את כפר נחום כמקום שבו לימד ישוע, קרא לתלמידים וריפא, והן מקשרות את העיירה עם פטרוס ועם חסידים אחרים. מן המאות הראשונות נערץ בידי הנוצרים בית באתר, שהוקף מאוחר יותר בכנסייה מתומנת. העיירה הייתה מיושבת במשך מאות שנים בטרם דעכה, והותירה את השרידים הנחקרים בידי ארכאולוגים בני זמננו.', 'האתר מוחזק ומטופל בידי משמורת ארץ הקודש הפרנציסקנית, המפקחת על הכנסייה, החפירות והגישה לצליינים ולמבקרים. כנסייה ומנזר יווניים-אורתודוקסיים נפרדים ניצבים בקצה המזרחי של השטח.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'he', 'קפלת שדה הרועים ניצבת בבית סאחור, ממזרח לבית לחם, באתר המזוהה במסורת עם שדות הרועים שבסיפור המולד. על פי בשורת לוקאס, בישרו שם המלאכים לרועים ששמרו על עדריהם בלילה את לידת ישוע. הקפלה ושטחה הסובב הם מקום תפילה ועלייה לרגל, בעיקר בחג המולד.', 'בשורת לוקאס (פרק 2) מתארת רועים סמוך לבית לחם ששמעו על לידת המושיע ויצאו למצוא את הילד. הערצת הנוצרים לשדות הרועים סמוך לבית סאחור עתיקה מאוד, ובאזור נמצאו שרידי כנסיות ומבנים נזיריים קודמים. הקפלה הפרנציסקנית הנוכחית נבנתה ב-1953.', 'בקפלה ובשדה מטפלת משמורת ארץ הקודש הפרנציסקנית. שדה רועים יווני-אורתודוקסי נפרד, על כנסייתו ושרידיו העתיקים, שוכן בקרבת מקום באותו אזור של בית סאחור.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'he', 'מערת החלב היא קפלה שנבנתה סביב מערת גיר לבנה ורכה בבית לחם, מרחק הליכה קצר מכנסיית המולד. המסורת מקשרת את המערה עם המשפחה הקדושה, ומייחסת אותה לתקופה שלפני המנוסה למצרים או במהלכה. זהו מקום תפילה שקט, המבוקר בעיקר בידי אמהות וזוגות המקווים לילדים.', 'המסורת המקומית גורסת שהמשפחה הקדושה מצאה מחסה במערה זו ושסלעה הלבין, ומכאן שמה והמנהגים הקשורים בחלב ובאמהות. הערצת הנוצרים לאתר מתועדת לאורך מאות שנים רבות. המערה הייתה מזה זמן רב באחריות הפרנציסקנים, וקפלה חדשה יותר נוספה בעת החדשה לצד המקדש העתיק.', 'במערת החלב מטפלת משמורת ארץ הקודש הפרנציסקנית, המחזיקה בה כמקום תפילה ומקבלת צליינים ממדינות רבות. היא נותרה מוקד למסירות אישית, בייחוד למתפללים המבקשים אמהות ומשפחה.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
