INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'he', 'תיעוד', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'he', 'יוזמה מקיפה לצילום, סריקה ותיעוד של אתרי מורשת נוצרית, ממצאים וכתבי יד ברחבי ישראל והאזורים הסובבים. הארכיון הדיגיטלי הזה ישמר תיעוד היסטורי יקר ערך עבור חוקרים ולדורות הבאים.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'he', 'תיעוד דיגיטלי של אתרי מורשת נוצרית ברחבי ארץ הקודש.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'he', 'תיעוד מורשת ארץ הקודש', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'hi', 'घोषणा का महागिरजाघर इस्राएल के नासरत नगर में स्थित एक कैथोलिक गिरजाघर है। यह मध्य पूर्व के सबसे बड़े गिरजाघरों में से एक है और उस पारंपरिक स्थान को चिह्नित करता है जहाँ महादूत जिब्राईल ने मरियम को यह शुभ संदेश दिया था कि वह यीशु को जन्म देंगी।', 'वर्तमान महागिरजाघर 1969 में बनाया गया था और इसकी रूपरेखा इतालवी वास्तुकार जोवान्नी मूत्सियो ने तैयार की थी। यह पहले के बाइज़ेंटाइन और क्रूसेडर-कालीन गिरजाघरों के खंडहरों के ऊपर खड़ा है। यह स्थल प्राचीन काल से ही मसीही तीर्थयात्रा का केंद्र रहा है।', 'यह गिरजाघर नासरत के स्थानीय कैथोलिक समुदाय की सेवा करता है और दुनिया भर से आने वाले तीर्थयात्रियों का स्वागत करता है। यहाँ नियमित रूप से कई भाषाओं में मिस्सा अर्पित किया जाता है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'hi', 'बेथलहम में स्थित जन्म का गिरजाघर उस गुफा के ऊपर बना है जिसे मसीही परंपरा दूसरी शताब्दी से यीशु के जन्मस्थान के रूप में आदर देती आई है। यह दुनिया के उन सबसे प्राचीन गिरजाघरों में से एक है जिनका उपयोग बिना रुके होता आया है, और यह यूनेस्को का विश्व धरोहर स्थल भी है।', 'पहले महागिरजाघर का निर्माण सम्राट कॉन्स्टेंटाइन और उनकी माता हेलेना ने लगभग 327 ईस्वी में करवाया था। छठी शताब्दी में क्षतिग्रस्त होने के बाद सम्राट जस्टिनियन ने इसे और बड़े पैमाने पर दोबारा बनवाया, और आज के गिरजाघर का अधिकांश भाग उसी पुनर्निर्माण के समय का है। क्रूसेडर काल के मोज़ेक और चित्रित स्तंभ आज भी भीतर सुरक्षित हैं।', 'ऐतिहासिक यथास्थिति (स्टेटस क्वो) व्यवस्था के अंतर्गत यह गिरजाघर यूनानी ऑर्थोडॉक्स, रोमन कैथोलिक (फ़्रांसिस्कन) और आर्मेनियाई प्रेरितिक समुदायों द्वारा साझा किया जाता है। बेथलहम के स्थानीय मसीही परिवार दुनिया भर से आए तीर्थयात्रियों के साथ, विशेषकर क्रिसमस के समय, यहाँ आराधना करते हैं।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'hi', 'यरूशलेम के पुराने शहर में स्थित पवित्र कब्र के गिरजाघर में मसीही धर्म के दो सबसे पवित्र स्थल हैं: गुलगुता, जहाँ यीशु को क्रूस पर चढ़ाया गया था, और वह कब्र, जहाँ परंपरा के अनुसार उन्हें दफ़नाया गया और जहाँ से वे फिर जी उठे।', 'सम्राट कॉन्स्टेंटाइन ने चौथी शताब्दी में यहाँ पहला गिरजाघर बनवाया, जिसका प्रतिष्ठापन 335 ईस्वी में हुआ। 1009 में इसे नष्ट कर दिया गया और 11वीं शताब्दी में इसका पुनर्निर्माण हुआ; 12वीं शताब्दी में क्रूसेडरों ने इसे वह रूप दिया जो आज अधिकांशतः दिखाई देता है। कब्र के ऊपर बने छोटे पवित्र कक्ष (एडिक्यूल) का जीर्णोद्धार 2016–2017 में किया गया।', '1852 की यथास्थिति (स्टेटस क्वो) व्यवस्था के अंतर्गत इस गिरजाघर की देखरेख यूनानी ऑर्थोडॉक्स, रोमन कैथोलिक (फ़्रांसिस्कन) और आर्मेनियाई प्रेरितिक कलीसियाएँ मिलकर करती हैं, जबकि कॉप्टिक, इथियोपियाई और सीरियाई ऑर्थोडॉक्स समुदायों के भी यहाँ अपने चैपल हैं। इसके द्वार हर सुबह उन मुस्लिम परिवारों द्वारा खोले जाते हैं जो सदियों से इसकी चाबियाँ सँभालते आए हैं।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'hi', 'सर्व राष्ट्र गिरजाघर, जिसे यातना की बेसिलिका के नाम से भी जाना जाता है, यरूशलेम में जैतून पर्वत पर गतसमनी में स्थित एक रोमन कैथोलिक गिरजाघर है। इसमें चट्टान का वह हिस्सा सुरक्षित है जिसे परंपरा के अनुसार वह स्थान माना जाता है जहाँ यीशु ने अपने क्रूसीकरण से पहले की रात गहरी व्यथा में प्रार्थना की थी।', 'वर्तमान बेसिलिका 1919 से 1924 के बीच बनाई गई थी, जो निर्माण के दौरान मिली पहले की बाइज़ेंटाइन और क्रूसेडर गिरजाघरों की नींवों पर खड़ी है। इसे सर्व राष्ट्र गिरजाघर इसलिए कहा गया क्योंकि इसके निर्माण के लिए धन कई देशों के दान से जुटाया गया था, और उन देशों के राजचिह्न इसकी छत में जड़े हुए हैं।', 'बेसिलिका की देखरेख पवित्र भूमि की फ़्रांसिस्कन कस्टडी करती है, जो इस स्थल और उससे लगे गतसमनी के बगीचे तथा उसके प्राचीन जैतून के पेड़ों का रखरखाव करती है। यह प्रार्थना का एक सक्रिय स्थल बना हुआ है और जैतून पर्वत आने वाले तीर्थयात्रियों के लिए एक प्रमुख पड़ाव है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'hi', 'मरियम मग्दलीनी का गिरजाघर यरूशलेम में जैतून पर्वत की पश्चिमी ढलान पर, गतसमनी के बगीचे के निकट स्थित एक रूसी ऑर्थोडॉक्स गिरजाघर है। यह अपने सात स्वर्णिम प्याज़नुमा गुंबदों के लिए व्यापक रूप से पहचाना जाता है, जो यरूशलेम की क्षितिज-रेखा की एक विशिष्ट पहचान हैं।', 'यह गिरजाघर 1886 से 1888 के बीच रूस के ज़ार अलेक्ज़ेंडर तृतीय ने अपनी माता, महारानी मारिया अलेक्जेंड्रोव्ना की स्मृति में बनवाया था। इसे मरियम मग्दलीनी को समर्पित किया गया — वही संत जिनके नाम पर महारानी का नाम रखा गया था — और यह उन्नीसवीं शताब्दी के उत्तरार्ध में पवित्र भूमि में रूसी उपस्थिति को दर्शाता है।', 'यह गिरजाघर ऑर्थोडॉक्स संन्यासिनियों के एक मठ से संबंधित है और एक सक्रिय मठवासी समुदाय बना हुआ है जो आगंतुकों और तीर्थयात्रियों का स्वागत करता है। यह जैतून पर्वत की ढलानों पर गतसमनी के आसपास के क्षेत्र में स्थित है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'hi', 'डोमिनुस फ़्लेवित, जिसका लातिन में अर्थ है «प्रभु रोए», यरूशलेम में जैतून पर्वत की पश्चिमी ढलान पर स्थित एक रोमन कैथोलिक चैपल है। यह उस स्थान को चिह्नित करता है जहाँ, लूका के सुसमाचार के अनुसार, यीशु यरूशलेम की ओर देखते हुए रोए और उन्होंने उसके विनाश की भविष्यवाणी की।', 'वर्तमान चैपल 1955 में पहले के धार्मिक भवनों के स्थल पर बनाया गया था, जिनमें एक बाइज़ेंटाइन-कालीन गिरजाघर के अवशेष भी शामिल हैं। परिसर में हुई खुदाई में प्राचीन कब्रें और अस्थि-कलश भी मिले, जो इस बात की गवाही देते हैं कि यह ढलान लंबे समय तक दफ़न-स्थल के रूप में प्रयोग होती रही।', 'डोमिनुस फ़्लेवित की देखरेख पवित्र भूमि की फ़्रांसिस्कन कस्टडी करती है, जो इसे यरूशलेम और उसके आसपास के अपने पवित्र स्थलों के जाल के एक हिस्से के रूप में सँभालती है। यह चैपल जैतून पर्वत से गतसमनी की ओर उतरते तीर्थयात्रियों के लिए एक बार-बार का पड़ाव है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'hi', 'संत अन्ना का गिरजाघर यरूशलेम के पुराने शहर में, मुस्लिम मोहल्ले में बेथसैदा के कुंडों के पास स्थित एक रोमन कैथोलिक गिरजाघर है। यह उस स्थल पर खड़ा है जिसे परंपरा के अनुसार अन्ना और योआखिम के घर और कुँवारी मरियम के जन्मस्थान के रूप में पूजा जाता है।', 'यह गिरजाघर बारहवीं शताब्दी में क्रूसेडरों के यरूशलेम राज्य के दौरान बनाया गया था। 1187 में सलादीन द्वारा शहर पर विजय के बाद इसे एक इस्लामी मदरसे में बदल दिया गया, और उन्नीसवीं शताब्दी में ओटोमन अधिकारियों ने इसे फ़्रांस को सौंप दिया, जिसके संरक्षकों ने भवन का जीर्णोद्धार किया।', 'यह गिरजाघर और इसका परिसर अफ़्रीका के मिशनरियों को सौंपा गया है, जिन्हें आमतौर पर श्वेत पिता कहा जाता है, जो इस स्थल की देखभाल करते हैं और तीर्थयात्रियों का स्वागत करते हैं। यह पुराने शहर के भीतर प्रार्थना और अध्ययन का एक सक्रिय स्थल बना हुआ है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'hi', 'पातेर नोस्तेर गिरजाघर यरूशलेम में जैतून पर्वत पर स्थित एक रोमन कैथोलिक गिरजाघर और कार्मेलाइट मठ है। यह उस स्थल पर खड़ा है जिसे परंपरा के अनुसार यीशु के अपने शिष्यों को प्रभु की प्रार्थना सिखाने से जोड़ा जाता है, जो लातिन में «पातेर नोस्तेर» के नाम से जानी जाती है।', 'यह स्थल एलेओना के बाइज़ेंटाइन गिरजाघर की स्मृति को संजोए हुए है, जिसे चौथी शताब्दी में कॉन्स्टेंटाइन के शासनकाल में जैतून पर्वत की एक गुफा के ऊपर बनाया गया था। सदियों तक खंडहर बने रहने के बाद उन्नीसवीं शताब्दी में यहाँ एक फ़्रांसीसी मठ की स्थापना हुई, और गिरजाघर के भवनों का निर्माण बीसवीं शताब्दी तक चलता रहा।', 'इस स्थल की देखरेख कार्मेलाइट बहनों का एक समुदाय करता है, जो मठ, गिरजाघर और प्रांगण का रखरखाव करती हैं। यह जैतून पर्वत का भ्रमण करने वाले तीर्थयात्रियों और आगंतुकों के लिए एक नियमित पड़ाव है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'hi', 'भेंट का गिरजाघर यरूशलेम के पश्चिमी छोर पर बसे ऐन करेम गाँव में स्थित एक रोमन कैथोलिक गिरजाघर है। यह उस पारंपरिक स्थल को चिह्नित करता है जहाँ मरियम ने अपनी संबंधी इलीशिबा से भेंट की और, लूका के सुसमाचार के अनुसार, «मैग्निफ़िकाट» नाम से प्रसिद्ध स्तुति-गीत गाया। इस स्थल की देखरेख फ़्रांसिस्कन करते हैं और यह पवित्र भूमि के तीर्थयात्रियों के लिए एक व्यापक रूप से देखा जाने वाला गंतव्य है।', 'मसीही परंपरा ऐन करेम को जकरयाह और इलीशिबा के गृहग्राम और लूका के सुसमाचार में वर्णित भेंट के स्थल के रूप में पहचानती है। बाइज़ेंटाइन और क्रूसेडर काल में इस स्थल पर एक गिरजाघर खड़ा था, और वर्तमान दो-स्तरीय भवन इन पुराने ढाँचों के तत्वों को सुरक्षित रखे हुए है। वर्तमान गिरजाघर बीसवीं शताब्दी के पूर्वार्ध में पवित्र भूमि की फ़्रांसिस्कन कस्टडी के अधीन बनाया गया।', 'यह स्थल पवित्र भूमि की फ़्रांसिस्कन कस्टडी के स्वामित्व और देखरेख में है, जो पूरे क्षेत्र में अनेक तीर्थस्थलों की देखभाल करती है। यह प्रार्थना का एक सक्रिय स्थल और ऐन करेम से होकर गुज़रने वाले तीर्थ-मार्गों पर एक नियमित पड़ाव बना हुआ है, जहाँ योहन बपतिस्मा देने वाले के जन्म से जुड़े अन्य गिरजाघर भी हैं।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'hi', 'धन्य-वचनों का गिरजाघर गलील सागर के उत्तर-पश्चिमी तट के ऊपर एक पहाड़ी ढलान पर स्थित एक रोमन कैथोलिक गिरजाघर है। यह पर्वत-प्रवचन के पारंपरिक स्थल को चिह्नित करता है और इसका नाम धन्य-वचनों से लिया गया है — वे आशीषें जिनसे मत्ती के सुसमाचार में प्रवचन आरंभ होता है। इस स्थल से झील और उसके आसपास के गाँवों का विस्तृत दृश्य दिखाई देता है।', 'कफ़रनहूम के पास की एक पहाड़ी को पर्वत-प्रवचन का स्थल मानने की परंपरा बहुत पुरानी है, और नीचे तबगा के आसपास पहले के अवशेष देखे गए हैं। वर्तमान गिरजाघर 1938 में बना और इसकी रूपरेखा इतालवी वास्तुकार आंतोनियो बारलुत्सी ने तैयार की। इसके निर्माण में कुछ हद तक इटली से आया धन सहायक रहा।', 'इस गिरजाघर और इसके परिसर की देखरेख पवित्र हृदय की फ़्रांसिस्कन मिशनरी बहनें करती हैं। यह स्थल आराधना के स्थल के साथ-साथ गलील में एक व्यापक रूप से देखे जाने वाले तीर्थ-गंतव्य के रूप में भी कार्य करता है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'hi', 'रोटियों के गुणन का गिरजाघर गलील सागर के उत्तर-पश्चिमी तट पर तबगा में स्थित एक रोमन कैथोलिक गिरजाघर है। यह रोटियों और मछलियों के गुणन के उस सुसमाचारीय वृत्तांत का स्मरण कराता है जिससे एक बड़ी भीड़ को भोजन कराया गया। यह गिरजाघर अपने आरंभिक मसीही मोज़ेक फ़र्शों के लिए भली-भाँति जाना जाता है।', 'तबगा को बाइज़ेंटाइन काल में चमत्कार के स्थल के रूप में पूजा जाता था, और चौथी शताब्दी के एक छोटे चैपल के स्थान पर बाद में पाँचवीं शताब्दी में एक बड़ा गिरजाघर बनाया गया। ये आरंभिक भवन खंडहर हो गए, और उनके अवशेष आधुनिक काल में फिर से खोजे और खोदे गए। बीसवीं शताब्दी में बना वर्तमान गिरजाघर बाइज़ेंटाइन बेसिलिका की रूपरेखा को दोहराता है।', 'इस गिरजाघर की सेवा जर्मन बेनेडिक्टिन भिक्षु करते हैं, जो यरूशलेम में डॉर्मिशन एबे से जुड़े हैं। यह एक सक्रिय मठवासी और तीर्थस्थल बना हुआ है; 2015 में एक आग से परिसर के कुछ हिस्से क्षतिग्रस्त हुए, जिसके बाद इसकी मरम्मत की गई।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'hi', 'संत पतरस की प्रधानता का गिरजाघर गलील सागर के तट पर तबगा में स्थित एक छोटा रोमन कैथोलिक चैपल है। यह यूहन्ना के सुसमाचार में वर्णित यीशु के पुनरुत्थान के बाद अपने शिष्यों को दर्शन देने और पतरस को प्रधानता सौंपने का स्मरण कराता है। यह चैपल सीधे जल के किनारे खड़ा है।', 'यह स्थल यूहन्ना के सुसमाचार के 21वें अध्याय के वृत्तांत का स्मरण कराता है, जिसमें जी उठे यीशु झील के किनारे शिष्यों को दर्शन देते हैं, उनके साथ रोटी और मछली का भोजन करते हैं, और तीन बार पतरस को अपनी भेड़ों की चरवाही करने का आदेश देते हैं। इस परंपरा से जुड़ा एक गिरजाघर पहले की शताब्दियों में यहाँ मौजूद था, और पुराने ढाँचों के निशान पास ही सुरक्षित हैं। वर्तमान चैपल 1933 में बनाया गया था।', 'इस चैपल की देखरेख पवित्र भूमि की फ़्रांसिस्कन कस्टडी करती है। यह गलील सागर के उत्तरी तट के आसपास के स्थलों को देखने आने वाले तीर्थयात्रियों के लिए एक बार-बार का पड़ाव है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'hi', 'रूपांतरण का गिरजाघर निचले गलील में इज़्रएल की घाटी के ऊपर उठे ताबोर पर्वत की चोटी पर स्थित एक रोमन कैथोलिक बेसिलिका है। यह यीशु के रूपांतरण का स्मरण कराता है, जब सुसमाचारों के अनुसार वे मूसा और एलियाह की उपस्थिति में रूपांतरित रूप में दिखाई दिए। इसी पर्वत पर एक अन्य स्थान पर एक यूनानी ऑर्थोडॉक्स गिरजाघर भी खड़ा है।', 'ताबोर पर्वत को बाइज़ेंटाइन काल से रूपांतरण के पारंपरिक स्थल के रूप में सम्मान दिया जाता रहा है, और यहाँ बाइज़ेंटाइन तथा क्रूसेडर समय में गिरजाघर बनाए गए थे। ये ढाँचे बाद में खंडहर हो गए, और उनकी नींवें चोटी पर बनी हुई हैं। वर्तमान बेसिलिका 1924 में पूरी हुई।', 'इस बेसिलिका और इसके परिसर की देखरेख पवित्र भूमि की फ़्रांसिस्कन कस्टडी करती है। यह पर्वत एक तीर्थ-गंतव्य बना हुआ है, और इसकी चोटी एक यूनानी ऑर्थोडॉक्स मठ और गिरजाघर के साथ साझा है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'hi', 'फ़्रांसिस्कन विवाह गिरजाघर नासरत के उत्तर में कफ़्र काना में खड़ा है — वह नगर जिसे व्यापक रूप से सुसमाचारों के गलील के काना के रूप में पहचाना जाता है। यह उस विवाह-भोज का स्मरण कराता है जिसमें, यूहन्ना के सुसमाचार के अनुसार, यीशु ने पानी को दाखरस में बदल दिया, जिसे उनके पहले चिह्न के रूप में बताया गया है। यह स्थल तीर्थयात्रियों को, और विशेषकर विवाहित जोड़ों को आकर्षित करता है, जो अपने विवाह-वचनों को मनाने और उन्हें नए सिरे से दोहराने आते हैं।', 'यूहन्ना का सुसमाचार (अध्याय 2) यीशु, उनकी माता और उनके शिष्यों को काना के एक विवाह में रखता है, जहाँ मेज़बान के यहाँ दाखरस समाप्त हो गया और यीशु ने पत्थर के छह मटकों को पानी से भरवाया, जो दाखरस बन गया। कफ़्र काना में इस चमत्कार का सम्मान करने वाली गिरजाघर-परंपरा सदियों में विकसित हुई, और पहले के आराधना-स्थल वर्तमान स्थल पर या उसके पास खड़े थे। वर्तमान फ़्रांसिस्कन गिरजाघर 1879 से 1905 के बीच बनाया गया।', 'विवाह गिरजाघर की देखरेख पवित्र भूमि की कस्टडी के फ़्रांसिस्कन भिक्षु करते हैं, जो इसे आराधना और तीर्थ के स्थल के रूप में सँभालते हैं। कफ़्र काना में एक अलग यूनानी ऑर्थोडॉक्स गिरजाघर भी पास ही इस चमत्कार की परंपरा को संजोए हुए है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'hi', 'गलील सागर के उत्तरी तट पर स्थित कफ़रनहूम वह झील-किनारे का नगर है जिसे सुसमाचार गलील में यीशु की सेवकाई का केंद्र बताते हैं। यह पुरातात्विक स्थल उन अवशेषों को सुरक्षित रखता है जिन्हें प्रेरित पतरस के घर के रूप में पूजा जाता है, और एक प्राचीन आराधनालय को भी। यह क्षेत्र के सबसे महत्वपूर्ण नए नियम के स्थलों में से एक है।', 'सुसमाचार कफ़रनहूम को उस स्थान के रूप में प्रस्तुत करते हैं जहाँ यीशु ने शिक्षा दी, शिष्यों को बुलाया और चंगा किया, और वे इस नगर को पतरस तथा अन्य अनुयायियों से जोड़ते हैं। आरंभिक शताब्दियों से इस स्थल के एक घर को मसीहियों द्वारा पूजा जाता रहा और बाद में उसे एक अष्टकोणीय गिरजाघर के भीतर समेट लिया गया। यह नगर पतन से पहले सदियों तक बसा रहा, जिसके बाद वे खंडहर छूट गए जिनका अध्ययन आधुनिक पुरातत्वविद करते हैं।', 'यह स्थल पवित्र भूमि की फ़्रांसिस्कन कस्टडी के पास और उसकी देखरेख में है, जो गिरजाघर, खुदाई और तीर्थयात्रियों तथा आगंतुकों के प्रवेश का प्रबंध करती है। इस क्षेत्र के पूर्वी छोर पर एक अलग यूनानी ऑर्थोडॉक्स गिरजाघर और मठ खड़े हैं।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'hi', 'गड़ेरियों के मैदान का चैपल बेथलहम के पूर्व में बैत साहूर में उस स्थल पर खड़ा है जिसे परंपरा के अनुसार जन्म-कथा के गड़ेरियों के मैदानों से पहचाना जाता है। लूका के सुसमाचार के अनुसार, वहाँ स्वर्गदूतों ने रात में अपनी भेड़ों की रखवाली कर रहे गड़ेरियों को यीशु के जन्म की घोषणा की। यह चैपल और इसका आसपास का परिसर प्रार्थना और तीर्थ का स्थल है, विशेषकर क्रिसमस के समय।', 'लूका का सुसमाचार (अध्याय 2) बेथलहम के पास के उन गड़ेरियों का वर्णन करता है जिन्हें उद्धारकर्ता के जन्म की खबर दी गई और जो बालक को खोजने गए। बैत साहूर के पास गड़ेरियों के मैदानों की मसीही मान्यता बहुत पुरानी है, और इस क्षेत्र में पहले के गिरजाघरों तथा मठवासी ढाँचों के अवशेष मिले हैं। वर्तमान फ़्रांसिस्कन चैपल 1953 में बनाया गया।', 'इस चैपल और इसके मैदान की देखरेख पवित्र भूमि की फ़्रांसिस्कन कस्टडी करती है। एक अलग यूनानी ऑर्थोडॉक्स गड़ेरियों का मैदान, अपने गिरजाघर और प्राचीन अवशेषों के साथ, बैत साहूर के इसी क्षेत्र में पास ही स्थित है।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'hi', 'दुग्ध गुफा बेथलहम में जन्म के गिरजाघर से थोड़ी ही दूरी पर मुलायम सफ़ेद खड़िया की एक गुफा के चारों ओर बना एक चैपल है। परंपरा इस गुफा को पवित्र परिवार से जोड़ती है, इसे मिस्र भागने से पहले या उसके दौरान के समय से जोड़कर देखती है। यह प्रार्थना का एक शांत स्थल है, जहाँ विशेषकर माताएँ और संतान की आशा रखने वाले दंपती आते हैं।', 'स्थानीय परंपरा मानती है कि पवित्र परिवार ने इस गुफा में शरण ली और इसकी चट्टान सफ़ेद हो गई, जिससे इसका नाम पड़ा और दूध तथा मातृत्व से जुड़ी भक्ति की प्रथाएँ शुरू हुईं। इस स्थल की मसीही मान्यता कई शताब्दियों से प्रलेखित है। यह गुफा लंबे समय से फ़्रांसिस्कनों की देखरेख में रही है, और आधुनिक काल में पुराने पवित्रस्थल के साथ एक नया चैपल भी जोड़ा गया।', 'दुग्ध गुफा की देखरेख पवित्र भूमि की फ़्रांसिस्कन कस्टडी करती है, जो इसे प्रार्थना के स्थल के रूप में सँभालती है और अनेक देशों से आए तीर्थयात्रियों का स्वागत करती है। यह व्यक्तिगत भक्ति का एक केंद्र बना हुआ है, विशेषकर उनके लिए जो मातृत्व और परिवार के लिए प्रार्थना करते हैं।') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
