INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'c9d47aef-6caf-43fc-bb95-ac3ea1c0fca9', 'content', 'hi', 'हमारी जीर्णोद्धार परियोजना का पहला चरण शुरू हो गया है। आपके सहयोग के लिए धन्यवाद।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
