INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_visiting_info', '89ec3b57-4387-4c24-8ee4-c72083195c07', 'accessibility_info', 'hi', 'व्हीलचेयर से आने-जाने योग्य प्रवेश द्वार उपलब्ध है।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_visiting_info', '89ec3b57-4387-4c24-8ee4-c72083195c07', 'admission_info', 'hi', 'प्रवेश निःशुल्क है। गाइड के साथ भ्रमण की सुविधा उपलब्ध है।', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
