INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'hr', 'Dokumentiranje baštine Svete zemlje', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'hu', 'Az Angyali üdvözlet-bazilika egy katolikus templom az izraeli Názáretben. A Közel-Kelet egyik legnagyobb temploma, és azt a hagyomány szerinti helyet jelöli, ahol Gábriel arkangyal hírül adta Máriának, hogy Jézust fogja szülni.', 'A jelenlegi bazilikát 1969-ben építették, Giovanni Muzio olasz építész tervei alapján. Korábbi bizánci és keresztes kori templomok romjai fölött áll. A helyszín az ókor óta a keresztény zarándoklat célpontja.', 'A templom a názáreti helyi katolikus közösséget szolgálja, és a világ minden tájáról érkező zarándokokat fogad. Rendszeresen tartanak miséket több nyelven.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'hu', 'A betlehemi Születés temploma azon barlang fölött áll, amelyet a keresztény hagyomány a 2. század óta Jézus születési helyeként tisztel. A világ egyik legrégebbi, folyamatosan használt temploma, és az UNESCO világörökség része.', 'Az első bazilikát Konstantin császár és édesanyja, Ilona építtette 327 körül. Miután a 6. században megsérült, Justinianus császár nagyobb léptékben újjáépíttette, és a mai templom nagy része ebből az újjáépítésből származik. A keresztes korból származó mozaikok és festett oszlopok ma is fennmaradtak a belsejében.', 'A templomon a görögkeleti, a római katolikus (ferences) és az örmény apostoli közösség osztozik a történelmi status quo megállapodás keretében. Betlehem helyi keresztény családjai a világ minden tájáról érkező zarándokokkal együtt imádkoznak itt, különösen karácsonykor.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'hu', 'A jeruzsálemi óvárosban található Szent Sír-templom a kereszténység két legszentebb helyét foglalja magában: a Golgotát, ahol Jézust keresztre feszítették, és a sírt, amelybe a hagyomány szerint eltemették, és amelyből feltámadt.', 'Konstantin császár a 4. században itt építtette az első templomot; 335-ben szentelték fel. 1009-ben elpusztult, a 11. században újjáépítették, a keresztesek pedig a 12. században nagyrészt mai formáját adták neki. A sír fölötti Ediculát 2016–2017-ben állították helyre.', 'A templom gondozásán a görögkeleti, a római katolikus (ferences) és az örmény apostoli egyház osztozik, míg a kopt, az etióp és a szír ortodox közösségek szintén rendelkeznek kápolnákkal, az 1852-es status quo szerint. Ajtajait minden reggel muszlim családok nyitják ki, akik évszázadok óta őrzik a kulcsokat.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'hu', 'A Minden Nemzetek Temploma, más néven a Haláltusa bazilikája, római katolikus templom a jeruzsálemi Olajfák hegyén, Getszemániban. Azt az alapkőzetrészt őrzi, amelyet a hagyomány szerint azzal a hellyel azonosítanak, ahol Jézus keresztre feszítése előtti éjszakán haláltusájában imádkozott.', 'A mai bazilika 1919 és 1924 között épült a korábbi bizánci és keresztes kori templomok alapjaira, amelyeket az építkezés során tártak fel. Azért lett a Minden Nemzetek Temploma a neve, mert számos ország adományai finanszírozták az építését, és címereik a mennyezetbe vannak beépítve.', 'A bazilikáról a Ferences Szentföldi Kusztódia gondoskodik, amely fenntartja a helyet és a szomszédos Getszemáni-kertet ősi olajfáival együtt. Az imádság eleven helye marad, és fontos állomás az Olajfák hegyét felkereső zarándokok számára.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'hu', 'A Mária Magdolna-templom orosz ortodox templom az Olajfák hegyének nyugati lejtőjén, Jeruzsálemben, a Getszemáni-kert közelében. Széles körben ismert hét aranyozott hagymakupolájáról, amely Jeruzsálem látképének jellegzetes eleme.', 'A templomot 1886 és 1888 között III. Sándor orosz cár építtette édesanyja, Marija Alekszandrovna cárné emlékére. Mária Magdolnának szentelték, annak a szentnek, akiről a cárnét elnevezték, és tükrözi az orosz jelenlétet a Szentföldön a tizenkilencedik század végén.', 'A templom egy ortodox apácazárdához tartozik, és eleven szerzetesi közösség marad, amely fogadja a látogatókat és a zarándokokat. A Getszemáni környezetében áll, az Olajfák hegyének lejtőin.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'hu', 'A Dominus Flevit, ami latinul azt jelenti, hogy "Az Úr sírt", római katolikus kápolna az Olajfák hegyének nyugati lejtőjén, Jeruzsálemben. Azt a helyet jelöli, ahol Lukács evangéliuma szerint Jézus sírt, miközben Jeruzsálem felé tekintett, és megjövendölte annak pusztulását.', 'A mai kápolna 1955-ben épült korábbi vallási épületek helyén, köztük egy bizánci kori templom maradványain. A telken végzett ásatások ősi sírokat és csontházakat is feltártak, amelyek a lejtő hosszú temetkezési célú használatáról tanúskodnak.', 'A Dominus Flevitről a Ferences Szentföldi Kusztódia gondoskodik, Jeruzsálemben és környékén fenntartott szentélyhálózatának részeként. Gyakori állomása azoknak a zarándokoknak, akik az Olajfák hegyéről Getszemáni felé ereszkednek le.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'hu', 'A Szent Anna-templom római katolikus templom Jeruzsálem Óvárosában, a Muszlim negyedben, a Beteszda-tavak mellett. Azon a helyen áll, amelyet a hagyomány Anna és Joákim otthonaként, valamint Szűz Mária születési helyeként tisztel.', 'A templom a tizenkettedik században épült a keresztes Jeruzsálemi Királyság idején. Szaladin 1187-es hódítása után iszlám iskolává alakították át, a tizenkilencedik században pedig az oszmán hatóságok Franciaországnak adományozták, amelynek gondnokai helyreállították az épületet.', 'A templomot és területét Afrika Misszionáriusaira, közismert nevükön a Fehér Atyákra bízták, akik gondozzák a helyet és fogadják a zarándokokat. Az imádság és a tanulás eleven helye marad az Óvárosban.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'hu', 'A Pater Noster-templom római katolikus templom és kármelita kolostor a jeruzsálemi Olajfák hegyén. Azon a helyen áll, amelyet a hagyomány azzal köt össze, hogy Jézus itt tanította tanítványainak a Miatyánkot, amelyet latinul Pater Noster néven ismernek.', 'A hely a bizánci Eleóna-templom emlékét őrzi, amelyet a negyedik században Konstantin uralkodása idején építettek egy barlang fölé az Olajfák hegyén. Századokig tartó pusztulás után a tizenkilencedik században francia kolostort alapítottak itt, és a templomépületek építése a huszadik századba is átnyúlt.', 'A helyről kármelita nővérek közössége gondoskodik, akik fenntartják a kolostort, a templomot és a kerengőt. Rendszeres állomása az Olajfák hegyét felfedező zarándokoknak és látogatóknak.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'hu', 'A Látogatás temploma római katolikus templom Ein Karem falujában, Jeruzsálem nyugati peremén. Azt a hagyományos helyet jelöli, ahol Mária meglátogatta rokonát, Erzsébetet, és Lukács evangéliuma szerint elmondta a Magnificat néven ismert éneket. A helyről a ferencesek gondoskodnak, és a szentföldi zarándokok sűrűn látogatott célpontja.', 'A keresztény hagyomány Ein Karemet azonosítja Zakariás és Erzsébet szülőfalujaként és a Lukács evangéliumában leírt Látogatás színhelyeként. A helyen templom állt a bizánci és a keresztes korban, és a mai kétszintes épület megőrzi e korábbi építmények elemeit. A jelenlegi templom a huszadik század első felében épült ki a Ferences Szentföldi Kusztódia irányítása alatt.', 'A helyet a Ferences Szentföldi Kusztódia birtokolja és tartja fenn, amely a régió számos szentélyéről gondoskodik. Az imádság eleven helye marad, és rendszeres állomás az Ein Karemen átvezető zarándokutakon, ahol Keresztelő Szent János születéséhez kapcsolódó más templomok is találhatók.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'hu', 'A Nyolc Boldogság temploma római katolikus templom a Galileai-tenger északnyugati partja fölötti domboldalon. A Hegyi beszéd hagyományos helyét jelöli, és nevét a nyolc boldogságról kapta, azokról az áldásokról, amelyekkel a beszéd Máté evangéliumában kezdődik. Fekvése tágas kilátást nyújt a tóra és a környező falvakra.', 'Régóta él a hagyomány egy Kafarnaum közeli dombról mint a Hegyi beszéd helyéről, és korábbi maradványokat jegyeztek fel az alatta fekvő Tabgha környékén. A mai templom 1938-ban épült, Antonio Barluzzi olasz építész tervei szerint. Építését részben olaszországi támogatás segítette.', 'A templomról és területéről a Szent Szív Ferences Misszionárius Nővérei gondoskodnak. A hely istentiszteleti helyként és Galilea sűrűn látogatott zarándokcéljaként egyaránt működik.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'hu', 'A kenyérszaporítás temploma római katolikus templom Tabghában, a Galileai-tenger északnyugati partján. A kenyerek és halak megszaporításáról szóló evangéliumi elbeszélésre emlékezik, amellyel egy sokaságot tápláltak. A templom jól ismert korai keresztény mozaikpadlóiról.', 'Tabghát a bizánci korban a csoda helyeként tisztelték, és egy negyedik századi kis kápolnát később, az ötödik században nagyobb templom váltott fel. Ezek a korai épületek romba dőltek, maradványaikat pedig újkorban fedezték fel és tárták fel ásatással. A mai templom, amely a huszadik században épült, a bizánci bazilika alaprajzát reprodukálja.', 'A templomot a jeruzsálemi Dormitio-apátsághoz kötődő német bencés szerzetesek szolgálják. Eleven szerzetesi és zarándokhely marad; 2015-ben tűz rongálta meg az épületegyüttes egyes részeit, amelyeket ezután helyreállítottak.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'hu', 'Szent Péter primátusának temploma kicsiny római katolikus kápolna Tabghában, a Galileai-tenger partján. Jézusnak a feltámadása utáni, tanítványai előtt való megjelenésére emlékezik, amelyet János evangéliuma ír le, valamint a primátus Péterre ruházására. A kápolna közvetlenül a víz mellett áll.', 'A hely a János 21-ben olvasható elbeszélésre emlékeztet, amelyben a feltámadt Jézus megjelenik a tanítványoknak a tónál, kenyérből és halból álló étkezésen osztozik velük, és háromszor bízza Péterre, hogy legeltesse nyáját. Az e hagyományhoz kapcsolódó templom korábbi századokban itt állt, és a régebbi építmények nyomai a közelben fennmaradtak. A mai kápolna 1933-ban épült.', 'A kápolnáról a Ferences Szentföldi Kusztódia gondoskodik. Gyakori állomása azoknak a zarándokoknak, akik a Galileai-tenger északi partja körüli helyeket keresik fel.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'hu', 'Az Úr színeváltozásának temploma római katolikus bazilika a Tábor-hegy csúcsán, amely az Alsó-Galilea Jezréel-völgye fölé emelkedik. Jézus színeváltozására emlékezik, amikor az evangéliumok szerint Mózes és Illés jelenlétében elváltozva látták. A hegy más pontján görög ortodox templom is áll.', 'A Tábor-hegyet a bizánci kor óta tisztelik a színeváltozás hagyományos helyeként, és templomok épültek itt a bizánci és a keresztes időkben. Ezek az építmények később romba dőltek, alapjaik pedig a csúcson megmaradtak. A mai bazilika 1924-ben készült el.', 'A bazilikáról és területéről a Ferences Szentföldi Kusztódia gondoskodik. A hegy zarándokcél marad, csúcsán pedig egy görög ortodox kolostorral és templommal osztozik.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'hu', 'A ferences menyegzői templom Kafr Kannában áll, abban a városban, amelyet széles körben az evangéliumok galileai Kánájával azonosítanak, Názárettől északra. Arra a menyegzői lakomára emlékezik, amelyen János evangéliuma szerint Jézus a vizet borrá változtatta, amit jelei közül az elsőként említenek. A hely zarándokokat vonz, különösen házaspárokat, akik fogadalmuk megünneplésére és megújítására érkeznek.', 'János evangéliuma (2. fejezet) Jézust, anyját és tanítványait egy kánai menyegzőn helyezi el, ahol a házigazdának elfogyott a bora, Jézus pedig hat kőkorsót töltetett meg vízzel, amely borrá lett. A csodát tisztelő egyházi hagyomány Kafr Kannában az évszázadok során bontakozott ki, és korábbi istentiszteleti helyek álltak a mai helyen vagy annak közelében. A mai ferences templom 1879 és 1905 között épült.', 'A menyegzői templomról a Szentföldi Kusztódia ferences testvérei gondoskodnak, akik istentiszteleti és zarándokhelyként tartják fenn. Egy külön görög ortodox templom Kafr Kannában szintén őrzi a csoda hagyományát a közelben.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'hu', 'Kafarnaum a Galileai-tenger északi partján az a tóparti város, amelyet az evangéliumok Jézus galileai működésének központjaként írnak le. A régészeti lelőhely megőrzi az apostol Péter házaként tisztelt maradványokat és egy ősi zsinagógát. A régió egyik legfontosabb újszövetségi helyszíne.', 'Az evangéliumok Kafarnaumot úgy mutatják be, mint azt a helyet, ahol Jézus tanított, tanítványokat hívott el és gyógyított, és a várost Péterrel és más követőkkel kapcsolják össze. A korai századoktól kezdve a helyszínen álló egyik házat a keresztények tisztelték, később pedig nyolcszögletű templommal vették körül. A várost évszázadokon át lakták, mielőtt hanyatlásnak indult, hátrahagyva a modern régészek által vizsgált romokat.', 'A helyet a Ferences Szentföldi Kusztódia birtokolja és gondozza, amely felügyeli a templomot, az ásatásokat, valamint a zarándokok és látogatók bejutását. Külön görög ortodox templom és kolostor áll a terület keleti szélén.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'hu', 'A pásztorok mezejének kápolnája Beit Sahourban, Betlehemtől keletre áll, azon a helyen, amelyet a hagyomány a betlehemi történet pásztormezőivel azonosít. Lukács evangéliuma szerint itt jelentették be az angyalok a nyájukat éjjel őrző pásztoroknak Jézus születését. A kápolna és környező területe az imádság és a zarándoklat helye, különösen karácsonykor.', 'Lukács evangéliuma (2. fejezet) Betlehem közeli pásztorokat ír le, akiknek hírül adták a Megváltó születését, és elindultak, hogy megkeressék a gyermeket. A Beit Sahour közeli pásztormezők keresztény tisztelete igen régi, és korábbi templomok és szerzetesi építmények maradványait találták meg a környéken. A mai ferences kápolna 1953-ban épült.', 'A kápolnáról és mezejéről a Ferences Szentföldi Kusztódia gondoskodik. Külön görög ortodox pásztormező, saját templommal és ősi maradványokkal, a közelben, Beit Sahour ugyanezen részén fekszik.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'hu', 'A Tej barlangja egy puha, fehér mészkőbarlang köré épült kápolna Betlehemben, rövid sétára a Születés templomától. A hagyomány a barlangot a Szent Családdal köti össze, az egyiptomi menekülés előtti vagy alatti időhöz kapcsolva. Csendes imahely, amelyet különösen anyák és gyermeket remélő párok látogatnak.', 'A helyi hagyomány úgy tartja, hogy a Szent Család ebben a barlangban keresett menedéket, és hogy sziklája fehérré vált, ami a nevet, valamint a tejjel és az anyasággal kapcsolatos ájtatosságokat eredményezte. A hely keresztény tisztelete sok évszázadon át dokumentált. A barlang régóta ferences gondozás alatt áll, és az újkorban a régebbi szentély mellé újabb kápolnát emeltek.', 'A Tej barlangjáról a Ferences Szentföldi Kusztódia gondoskodik, amely imahelyként tartja fenn, és sok országból fogad zarándokokat. A személyes ájtatosság középpontja marad, különösen azok számára, akik anyaságért és családért imádkoznak.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
