INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'hu', 'Ez a projekt a bazilika legégetőbb felújítási igényeire összpontosít, beleértve a szerkezeti javításokat, a homlokzat tisztítását és az eredeti építészeti elemek megőrzését. A munkálatok biztosítják, hogy az épület biztonságos és megközelíthető maradjon a jövő nemzedékei számára.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'hu', 'Az Angyali üdvözlet-bazilika főhajójának és homlokzatának felújítása.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'hu', 'A bazilika felújítása – 1. szakasz', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'hu', 'Dokumentáció', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'hu', 'Átfogó kezdeményezés a keresztény örökségi helyszínek, műtárgyak és kéziratok fényképezésére, szkennelésére és dokumentálására Izraelben és a környező régiókban. Ez a digitális archívum felbecsülhetetlen értékű történelmi feljegyzéseket őriz meg a kutatók és a jövő nemzedékei számára.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'hu', 'A keresztény örökségi helyszínek digitális dokumentálása a Szentföld egész területén.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'hu', 'A Szentföld örökségének dokumentálása', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'hy', 'Ավետման բազիլիկը կաթոլիկ եկեղեցի է Իսրայելի Նազարեթ քաղաքում։ Այն Մերձավոր Արևելքի ամենամեծ եկեղեցիներից մեկն է և կանգնած է այն վայրում, որտեղ, ըստ ավանդության, Գաբրիել հրեշտակապետը Կույս Մարիամին ավետեց, որ նա պիտի ծնի Հիսուսին։', 'Ներկայիս բազիլիկը կառուցվել է 1969 թվականին՝ իտալացի ճարտարապետ Ջովաննի Մուցիոյի նախագծով։ Այն վեր է խոյանում բյուզանդական և խաչակրաց ժամանակաշրջանների ավելի վաղ եկեղեցիների ավերակների վրա։ Հնագույն ժամանակներից ի վեր այս վայրը գրավում է քրիստոնյա ուխտավորներին։', 'Եկեղեցին ծառայում է Նազարեթի տեղի կաթոլիկ համայնքին և հյուրընկալում է աշխարհի տարբեր ծայրերից եկած ուխտավորներին։ Պատարագները կանոնավոր կերպով մատուցվում են տարբեր լեզուներով։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'hy', 'Բեթղեհեմի Սուրբ Ծննդյան տաճարը կանգնած է այն քարայրի վրա, որը քրիստոնեական ավանդությունը II դարից ի վեր մեծարում է որպես Հիսուսի ծննդավայր։ Այն աշխարհի ամենահին անընդմեջ գործող եկեղեցիներից մեկն է և ընդգրկված է ՅՈՒՆԵՍԿՕ-ի Համաշխարհային ժառանգության ցանկում։', 'Առաջին բազիլիկը կառուցվել է մ.թ. մոտ 327 թվականին՝ Կոստանդիանոս կայսեր և նրա մոր՝ Հեղինեի հրամանով։ VI դարում վնասվելուց հետո Հուստինիանոս կայսրն այն վերակառուցեց ավելի մեծ չափերով, և ներկայիս տաճարի զգալի մասը հենց այդ վերակառուցման ժամանակներից է։ Ներսում մինչ օրս պահպանվել են խաչակիրների դարաշրջանի խճանկարներ և նկարազարդ սյուներ։', 'Համաձայն պատմական Ստատուս քվոյի՝ տաճարը համատեղ տնօրինում են հույն ուղղափառ, հռոմեական կաթոլիկ (ֆրանցիսկյաններ) և հայ առաքելական համայնքները։ Բեթղեհեմի տեղացի քրիստոնյա ընտանիքներն այստեղ աղոթում են աշխարհի տարբեր ծայրերից եկած ուխտավորների հետ, հատկապես Սուրբ Ծննդյան տոներին։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'hy', 'Երուսաղեմի Հին քաղաքում գտնվող Սուրբ Հարության տաճարն իր մեջ ներառում է քրիստոնեության երկու մեծագույն սրբավայրերը՝ Գողգոթան, որտեղ խաչվեց Հիսուսը, և Սուրբ Գերեզմանը, որտեղ, ըստ ավանդության, Նա թաղվեց և հարություն առավ։', 'Կոստանդիանոս կայսրն այստեղ առաջին եկեղեցին կառուցեց IV դարում, և այն օծվեց մ.թ. 335 թվականին։ 1009 թվականին տաճարն ավերվեց, XI դարում վերակառուցվեց, իսկ XII դարում խաչակիրներն էականորեն ձևավորեցին նրա ներկայիս տեսքը։ Սուրբ Գերեզմանի վրա կառուցված մատուռը վերականգնվեց 2016–2017 թվականներին։', 'Տաճարի խնամքը համատեղ իրականացնում են Հույն ուղղափառ, Հռոմեական կաթոլիկ (ֆրանցիսկյաններ) և Հայ առաքելական եկեղեցիները, իսկ իրենց մատուռներն ունեն նաև ղպտի, եթովպական և ասորի ուղղափառ համայնքները։ Այս կարգը սահմանված է 1852 թվականի Ստատուս քվոյով։ Տաճարի դռներն ամեն առավոտ բացում են մահմեդական ընտանիքները, որոնք դարեր շարունակ պահում են դրա բանալիները։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'hy', 'Բոլոր ազգերի եկեղեցին, որը հայտնի է նաև որպես Տառապանքի բազիլիկ, կաթոլիկ եկեղեցի է Երուսաղեմի Ձիթենյաց լեռան Գեթսեմանիում։ Այն իր մեջ ամփոփում է ժայռի այն հատվածը, որն ավանդությամբ համարվում է վայրը, որտեղ Հիսուսը խաչելությանը նախորդող գիշերը աղոթում էր տառապանքի մեջ։', 'Ներկայիս բազիլիկը կառուցվել է 1919–1924 թվականներին՝ շինարարության ընթացքում հայտնաբերված ավելի վաղ բյուզանդական և խաչակրաց եկեղեցիների հիմքերի վրա։ Այն Բոլոր ազգերի եկեղեցի է կոչվել, քանի որ նրա կառուցումը ֆինանսավորվել է բազմաթիվ երկրների նվիրատվություններով, որոնց զինանշանները տեղադրված են առաստաղին։', 'Բազիլիկի խնամքն իրականացնում է Սուրբ երկրի ֆրանցիսկյան կուստոդիան, որը պահպանում է վայրը և հարակից Գեթսեմանիի պարտեզն իր հնագույն ձիթենիներով։ Այն մնում է աղոթքի գործող վայր և Ձիթենյաց լեռ այցելող ուխտավորների կարևոր կանգառ։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'hy', 'Մարիամ Մագդաղենացու եկեղեցին ռուս ուղղափառ եկեղեցի է Երուսաղեմի Ձիթենյաց լեռան արևմտյան լանջին՝ Գեթսեմանիի պարտեզի մոտ։ Այն լայնորեն ճանաչված է իր յոթ ոսկեզօծ սոխաձև գմբեթներով, որոնք Երուսաղեմի համայնապատկերի տարբերակիչ նշան են։', 'Եկեղեցին կառուցվել է 1886–1888 թվականներին Ռուսաստանի կայսր Ալեքսանդր III-ի կողմից՝ ի հիշատակ իր մոր՝ կայսրուհի Մարիա Ալեքսանդրովնայի։ Այն նվիրվել է Մարիամ Մագդաղենացուն՝ այն սրբուհուն, որի անունով կոչվել էր կայսրուհին, և արտացոլում է XIX դարի վերջին Սուրբ երկրում ռուսական ներկայությունը։', 'Եկեղեցին պատկանում է ուղղափառ միանձնուհիների մի վանքի և մնում է գործող միաբանական համայնք, որը հյուրընկալում է այցելուներին ու ուխտավորներին։ Այն գտնվում է Գեթսեմանիի շրջակայքում՝ Ձիթենյաց լեռան լանջերին։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'hy', 'Դոմինուս Ֆլևիտը, որը լատիներեն նշանակում է «Տերը լաց եղավ», կաթոլիկ մատուռ է Երուսաղեմի Ձիթենյաց լեռան արևմտյան լանջին։ Այն նշում է վայրը, որտեղ, ըստ Ղուկասի Ավետարանի, Հիսուսը լաց եղավ՝ նայելով Երուսաղեմին, և կանխագուշակեց նրա կործանումը։', 'Ներկայիս մատուռը կառուցվել է 1955 թվականին՝ ավելի վաղ կրոնական շինությունների, այդ թվում բյուզանդական դարաշրջանի եկեղեցու մնացորդների տեղում։ Տարածքում կատարված պեղումները բացահայտել են նաև հնագույն դամբարաններ ու ոսկրարկղեր՝ վկայելով լանջի՝ որպես թաղման վայրի երկարատև օգտագործման մասին։', 'Դոմինուս Ֆլևիտը պահպանվում է Սուրբ երկրի ֆրանցիսկյան կուստոդիայի կողմից՝ որպես Երուսաղեմում և նրա շրջակայքում գտնվող սրբավայրերի իր ցանցի մաս։ Մատուռը հաճախակի կանգառ է Ձիթենյաց լեռից Գեթսեմանի իջնող ուխտավորների համար։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'hy', 'Սուրբ Աննայի եկեղեցին կաթոլիկ եկեղեցի է Երուսաղեմի Հին քաղաքում՝ Մահմեդական թաղամասում, Բեթհեզդայի ավազանների կողքին։ Այն կանգնած է վայրի վրա, որն ավանդությամբ մեծարվում է որպես Աննայի և Հովակիմի տունը և Կույս Մարիամի ծննդավայրը։', 'Եկեղեցին կառուցվել է XII դարում՝ խաչակիրների Երուսաղեմի թագավորության ժամանակ։ 1187 թվականին Սալահ ադ-Դինի (Սալադին) կողմից քաղաքի գրավումից հետո այն վերածվել է իսլամական դպրոցի, իսկ XIX դարում օսմանյան իշխանությունները հանձնել են այն Ֆրանսիային, որի խնամակալները վերականգնել են շենքը։', 'Եկեղեցին և նրա տարածքը վստահված են Աֆրիկայի միսիոներներին, որոնք առավել հայտնի են որպես Սպիտակ հայրեր և ովքեր խնամում են վայրը և ընդունում ուխտավորներին։ Այն մնում է աղոթքի ու ուսումնասիրության գործող վայր Հին քաղաքում։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'hy', 'Պատեր Նոստեր եկեղեցին կաթոլիկ եկեղեցի և կարմելյան վանք է Երուսաղեմի Ձիթենյաց լեռան վրա։ Այն կանգնած է վայրի վրա, որն ավանդությամբ կապվում է Հիսուսի հետ, ով իր աշակերտներին սովորեցրեց Տերունական աղոթքը, որը լատիներեն հայտնի է որպես «Պատեր Նոստեր»։', 'Այս վայրը պահպանում է Էլեոնայի բյուզանդական եկեղեցու հիշատակը, որը կառուցվել է IV դարում՝ Կոստանդիանոսի օրոք, Ձիթենյաց լեռան քարայրի վրա։ Դարերի ավերումից հետո այստեղ XIX դարում հիմնվել է ֆրանսիական վանք, իսկ եկեղեցական շինությունների կառուցումը շարունակվել է մինչև XX դարը։', 'Վայրի խնամքն իրականացնում է կարմելյան քույրերի համայնքը, որոնք պահպանում են վանքը, եկեղեցին ու սրահապատ բակը։ Այն կանոնավոր կանգառ է Ձիթենյաց լեռն ուսումնասիրող ուխտավորների ու այցելուների համար։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'hy', 'Այցելության եկեղեցին կաթոլիկ եկեղեցի է Երուսաղեմի արևմտյան եզրին գտնվող Էյն Քարեմ գյուղում։ Այն նշում է ավանդական վայրը, որտեղ Մարիամն այցելեց իր ազգական Եղիսաբեթին և, ըստ Ղուկասի Ավետարանի, արտասանեց «Մեծացուսցէ» (Magnificat) կոչվող օրհներգը։ Վայրը խնամում են ֆրանցիսկյանները, և այն Սուրբ երկիր այցելող ուխտավորների լայնորեն այցելվող վայր է։', 'Քրիստոնեական ավանդությունը Էյն Քարեմը նույնացնում է Զաքարիայի և Եղիսաբեթի հայրենի գյուղի և Ղուկասի Ավետարանում նկարագրված Այցելության վայրի հետ։ Բյուզանդական ու խաչակրաց ժամանակաշրջաններում այս վայրում եկեղեցի է կանգնած եղել, և ներկայիս երկհարկանի շինությունը պահպանում է այդ ավելի վաղ կառույցների տարրերը։ Ներկայիս եկեղեցին ձևավորվել է XX դարի առաջին կեսին՝ Սուրբ երկրի ֆրանցիսկյան կուստոդիայի ղեկավարությամբ։', 'Վայրը պատկանում է Սուրբ երկրի ֆրանցիսկյան կուստոդիային, որը խնամում է տարածաշրջանի բազմաթիվ սրբավայրեր, և պահպանվում է նրա կողմից։ Այն մնում է աղոթքի գործող վայր և Էյն Քարեմով անցնող ուխտագնացության երթուղիների կանոնավոր կանգառ, որտեղ կան նաև Հովհաննես Մկրտչի ծննդյան հետ կապված այլ եկեղեցիներ։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'hy', 'Երանիների եկեղեցին կաթոլիկ եկեղեցի է Գալիլեայի ծովի հյուսիսարևմտյան ափից վեր գտնվող բլրալանջին։ Այն նշում է Լեռան քարոզի ավանդական վայրը և իր անունը ստացել է Երանիներից՝ այն օրհնություններից, որոնցով սկսվում է Մատթեոսի Ավետարանի քարոզը։ Վայրից բացվում է լճի ու շրջակա գյուղերի լայն տեսարան։', 'Կափառնայումի մոտ գտնվող բլուրը՝ որպես Լեռան քարոզի վայր, հին ավանդույթ ունի, և ավելի վաղ շրջանի մնացորդներ նկատվել են ներքևում՝ Թաբղայի մերձակայքում։ Ներկայիս եկեղեցին կառուցվել է 1938 թվականին՝ իտալացի ճարտարապետ Անտոնիո Բարլուցիի նախագծով։ Նրա կառուցումը մասամբ ֆինանսավորվել է Իտալիայի կողմից։', 'Եկեղեցու և նրա տարածքի խնամքն իրականացնում են Սրբազան Սրտի ֆրանցիսկյան միսիոներ քույրերը։ Վայրը գործում է թե՛ որպես պաշտամունքի վայր, թե՛ որպես Գալիլեայում լայնորեն այցելվող ուխտագնացության նպատակակետ։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'hy', 'Հացերի բազմացման եկեղեցին կաթոլիկ եկեղեցի է Գալիլեայի ծովի հյուսիսարևմտյան ափին գտնվող Թաբղայում։ Այն հիշատակում է հացերի ու ձկների բազմացման ավետարանական պատմությունը, որով կերակրվեց բազմությունը։ Եկեղեցին հայտնի է իր վաղ քրիստոնեական խճանկարային հատակներով։', 'Թաբղան բյուզանդական շրջանում մեծարվում էր որպես հրաշքի վայր, և IV դարի փոքր մատուռը հետագայում փոխարինվեց V դարի ավելի մեծ եկեղեցով։ Այս վաղ շինությունները ավերվեցին, և դրանց մնացորդները վերագտնվեցին ու պեղվեցին նոր ժամանակներում։ Ներկայիս եկեղեցին, կառուցված XX դարում, վերարտադրում է բյուզանդական բազիլիկի հատակագիծը։', 'Եկեղեցուն սպասավորում են գերմանացի բենեդիկտյան վանականները, որոնք կապված են Երուսաղեմի Վերափոխման աբբայության հետ։ Այն մնում է գործող վանական ու ուխտագնացության վայր. 2015 թվականին հրդեհը վնասեց համալիրի մի մասը, որից հետո այն վերանորոգվեց։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'hy', 'Սուրբ Պետրոսի առաջնության եկեղեցին փոքր կաթոլիկ մատուռ է Գալիլեայի ծովի ափին գտնվող Թաբղայում։ Այն հիշատակում է Հովհաննեսի Ավետարանում նկարագրված՝ հարությունից հետո Հիսուսի՝ իր աշակերտներին երևալը և Պետրոսին առաջնության շնորհումը։ Մատուռը կանգնած է անմիջապես ջրի եզրին։', 'Այս վայրը հիշեցնում է Հովհաննեսի Ավետարանի 21-րդ գլխի պատմությունը, որտեղ հարություն առած Հիսուսը երևում է աշակերտներին լճի մոտ, նրանց հետ կիսում հացի ու ձկան ճաշ և երեք անգամ պատվիրում Պետրոսին հովվել իր հոտը։ Այս ավանդության հետ կապված եկեղեցի գոյություն է ունեցել այստեղ նախորդ դարերում, և նախկին կառույցների հետքերը պահպանվել են մոտակայքում։ Ներկայիս մատուռը կառուցվել է 1933 թվականին։', 'Մատուռը պահպանվում է Սուրբ երկրի ֆրանցիսկյան կուստոդիայի կողմից։ Այն հաճախակի կանգառ է Գալիլեայի ծովի հյուսիսային ափի շուրջ գտնվող վայրերն այցելող ուխտավորների համար։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'hy', 'Պայծառակերպության եկեղեցին կաթոլիկ բազիլիկ է Ստորին Գալիլեայի Հեզրայելի հովտից վեր բարձրացող Թաբոր լեռան գագաթին։ Այն հիշատակում է Հիսուսի Պայծառակերպությունը, երբ, ըստ Ավետարանների, Նա երևաց կերպարանափոխված՝ Մովսեսի ու Եղիայի ներկայությամբ։ Լեռան մեկ այլ մասում կանգնած է նաև հույն ուղղափառ եկեղեցի։', 'Թաբոր լեռը բյուզանդական շրջանից ի վեր մեծարվում է որպես Պայծառակերպության ավանդական վայր, և այստեղ եկեղեցիներ կառուցվել են բյուզանդական ու խաչակրաց ժամանակներում։ Այս կառույցները հետագայում ավերվեցին, և դրանց հիմքերը մնում են գագաթին։ Ներկայիս բազիլիկն ավարտվել է 1924 թվականին։', 'Բազիլիկի և նրա տարածքի խնամքն իրականացնում է Սուրբ երկրի ֆրանցիսկյան կուստոդիան։ Լեռը մնում է ուխտագնացության նպատակակետ, իսկ գագաթը կիսվում է հույն ուղղափառ վանքի ու եկեղեցու հետ։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'hy', 'Ֆրանցիսկյան Հարսանիքի եկեղեցին կանգնած է Նազարեթից հյուսիս գտնվող Քաֆր Քաննայում՝ այն քաղաքում, որը լայնորեն նույնացվում է Ավետարանների Գալիլեայի Կանայի հետ։ Այն հիշատակում է հարսանեկան խնջույքը, որի ժամանակ, ըստ Հովհաննեսի Ավետարանի, Հիսուսը ջուրը վերածեց գինու՝ նկարագրված որպես Նրա առաջին նշանը։ Վայրը գրավում է ուխտավորներին, և հատկապես ամուսնացած զույգերին, ովքեր գալիս են նշելու ու նորոգելու իրենց ուխտերը։', 'Հովհաննեսի Ավետարանը (գլուխ 2) Հիսուսին, Նրա մորն ու աշակերտներին տեղադրում է Կանայի հարսանիքին, որտեղ հյուրընկալողի գինին սպառվեց, և Հիսուսը հրամայեց ջրով լցնել վեց քարե սափորներ, որը դարձավ գինի։ Քաֆր Քաննայում այս հրաշքը մեծարող եկեղեցական ավանդությունը ձևավորվել է դարերի ընթացքում, և ավելի վաղ պաշտամունքի վայրեր կանգնած են եղել ներկայիս վայրում կամ դրա մոտ։ Ներկայիս ֆրանցիսկյան եկեղեցին կառուցվել է 1879–1905 թվականներին։', 'Հարսանիքի եկեղեցին խնամում են Սուրբ երկրի կուստոդիայի ֆրանցիսկյան միաբանները, որոնք պահպանում են այն որպես պաշտամունքի ու ուխտագնացության վայր։ Քաֆր Քաննայում առանձին հույն ուղղափառ եկեղեցին նույնպես մոտակայքում պահպանում է հրաշքի ավանդությունը։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'hy', 'Կափառնայումը, Գալիլեայի ծովի հյուսիսային ափին, լճափնյա քաղաք է, որը Ավետարանները նկարագրում են որպես Գալիլեայում Հիսուսի ծառայության կենտրոն։ Հնագիտական վայրը պահպանում է առաքյալ Պետրոսի տունը որպես մեծարվող մնացորդներ և հնագույն ժողովարան։ Այն տարածաշրջանի ամենակարևոր նորկտակարանային վայրերից մեկն է։', 'Ավետարանները Կափառնայումը ներկայացնում են որպես վայր, որտեղ Հիսուսը ուսուցանում էր, աշակերտներ կանչում և բժշկում, և քաղաքը կապում են Պետրոսի ու այլ հետևորդների հետ։ Վաղ դարերից վայրում գտնվող մի տուն մեծարվում էր քրիստոնյաների կողմից և հետագայում շրջափակվեց ութանկյուն եկեղեցու մեջ։ Քաղաքը դարեր շարունակ բնակեցված էր, մինչև որ անկում ապրեց՝ թողնելով ավերակներ, որոնք ուսումնասիրում են ժամանակակից հնագետները։', 'Վայրը պատկանում է և խնամվում Սուրբ երկրի ֆրանցիսկյան կուստոդիայի կողմից, որը վերահսկում է եկեղեցին, պեղումները և ուխտավորների ու այցելուների մուտքը։ Տարածքի արևելյան եզրին կանգնած են առանձին հույն ուղղափառ եկեղեցի ու վանք։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'hy', 'Հովիվների դաշտի մատուռը կանգնած է Բեթղեհեմից արևելք գտնվող Բեյթ Սահուրում՝ այն վայրում, որն ավանդությամբ նույնացվում է Սուրբ Ծննդյան պատմության հովիվների դաշտերի հետ։ Ըստ Ղուկասի Ավետարանի, հրեշտակներն այնտեղ ավետեցին Հիսուսի ծնունդը գիշերն իրենց հոտերը հսկող հովիվներին։ Մատուռն ու շրջակա տարածքը աղոթքի ու ուխտագնացության վայր են, հատկապես Սուրբ Ծննդյան ժամանակ։', 'Ղուկասի Ավետարանը (գլուխ 2) նկարագրում է Բեթղեհեմի մոտ գտնվող հովիվներին, որոնց ավետվեց Փրկչի ծնունդը և ովքեր գնացին գտնելու մանկանը։ Բեյթ Սահուրի մոտ հովիվների դաշտերի քրիստոնեական մեծարումը շատ հին է, և տարածքում հայտնաբերվել են ավելի վաղ եկեղեցիների ու վանական կառույցների մնացորդներ։ Ներկայիս ֆրանցիսկյան մատուռը կառուցվել է 1953 թվականին։', 'Մատուռի և նրա դաշտի խնամքն իրականացնում է Սուրբ երկրի ֆրանցիսկյան կուստոդիան։ Առանձին հույն ուղղափառ Հովիվների դաշտը՝ իր եկեղեցով ու հնագույն մնացորդներով, գտնվում է մոտակայքում՝ Բեյթ Սահուրի նույն տարածքում։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'hy', 'Կաթի քարայրը մատուռ է, որը կառուցված է Բեթղեհեմում փափուկ սպիտակ կավճաքարից քարայրի շուրջ՝ Սուրբ Ծննդյան տաճարից կարճ քայլելու հեռավորության վրա։ Ավանդությունը քարայրը կապում է Սուրբ Ընտանիքի հետ՝ վերագրելով այն Եգիպտոս փախուստից առաջ կամ դրա ընթացքում ընկած ժամանակին։ Այն աղոթքի հանդարտ վայր է, որ հատկապես այցելում են մայրերն ու երեխաներ ունենալ հուսացող զույգերը։', 'Տեղական ավանդությունը պնդում է, որ Սուրբ Ընտանիքն ապաստանել է այս քարայրում և որ նրա ժայռը դարձել է սպիտակ՝ ծնունդ տալով անվանմանն ու կաթի և մայրության հետ կապված պաշտամունքին։ Այս վայրի քրիստոնեական մեծարումը վավերագրված է բազում դարերի ընթացքում։ Քարայրը վաղուց գտնվում է ֆրանցիսկյան խնամքի ներքո, և նոր ժամանակներում հին սրբավայրի կողքին ավելացվել է ավելի նոր մատուռ։', 'Կաթի քարայրը խնամում է Սուրբ երկրի ֆրանցիսկյան կուստոդիան, որը պահպանում է այն որպես աղոթքի վայր և ընդունում բազմաթիվ երկրներից եկած ուխտավորների։ Այն մնում է անձնական բարեպաշտության կենտրոն, հատկապես նրանց համար, ովքեր աղոթում են մայրության ու ընտանիքի համար։') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
