INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'ba05a1f8-57a8-428d-955b-849cafe8e2d7', 'content', 'hy', 'Հրավիրում ենք Ձեզ Սուրբ Ծննդյան հատուկ պատարագներին և տոնական միջոցառումներին։ Ժամանակացույցը հասանելի է մեր կայքում։', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'ba05a1f8-57a8-428d-955b-849cafe8e2d7', 'title', 'hy', 'Սուրբ Ծննդյան տոնակատարություններ — 2025', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'c9d47aef-6caf-43fc-bb95-ac3ea1c0fca9', 'content', 'hy', 'Մեկնարկել է մեր վերականգնման նախագծի առաջին փուլը։ Շնորհակալություն Ձեր աջակցության համար։', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'c9d47aef-6caf-43fc-bb95-ac3ea1c0fca9', 'title', 'hy', 'Վերականգնման նախագծի նորություններ', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_visiting_info', '34a96c2a-68fd-4a37-8df7-ede5a4d02b7e', 'admission_info', 'hy', 'Մուտքն անվճար է։ Պահանջվում է համապատասխան հագուստ։', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_visiting_info', '89ec3b57-4387-4c24-8ee4-c72083195c07', 'accessibility_info', 'hy', 'Առկա է սայլակով այցելուների համար հասանելի մուտք։', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
