INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'id', 'Inisiatif komprehensif untuk memotret, memindai, dan mendokumentasikan situs warisan, artefak, dan manuskrip Kristen di seluruh Israel dan wilayah sekitarnya. Arsip digital ini akan melestarikan catatan sejarah yang sangat berharga bagi para peneliti dan generasi mendatang.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
