INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'it', 'Restauro', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'it', 'Questo progetto si concentra sulle esigenze fondamentali di restauro della basilica, tra cui riparazioni strutturali, pulizia della facciata e conservazione degli elementi architettonici originali. I lavori garantiranno che l''edificio rimanga sicuro e accessibile per le generazioni future.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'it', 'Restauro della navata principale e della facciata della Basilica dell''Annunciazione.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'it', 'Restauro della basilica - Fase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'it', 'Documentazione', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'it', 'Un''iniziativa completa per fotografare, scansionare e documentare siti, manufatti e manoscritti del patrimonio cristiano in Israele e nelle regioni circostanti. Questo archivio digitale preserverà documenti storici inestimabili per i ricercatori e per le generazioni future.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'it', 'Documentazione digitale dei siti del patrimonio cristiano in tutta la Terra Santa.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'it', 'Documentazione del patrimonio di Terra Santa', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ja', '受胎告知教会は、イスラエルのナザレにあるカトリックの教会です。中東最大級の教会の一つで、大天使ガブリエルがマリアに、イエスを身ごもることを告げたと伝えられる場所に建っています。', '現在の聖堂は、イタリアの建築家ジョヴァンニ・ムツィオの設計により1969年に建てられました。ビザンツ時代と十字軍時代の教会の遺構の上に建っており、この地は古くからキリスト教の巡礼地となってきました。', 'この教会はナザレの地元カトリック共同体の拠り所であると同時に、世界中から訪れる巡礼者を迎え入れています。ミサは定期的に複数の言語で捧げられています。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ja', 'ベツレヘムの聖誕教会は、2世紀以来キリスト教の伝承がイエス誕生の地として崇敬してきた洞窟の上に建っています。現在まで途切れることなく使われ続けている教会としては世界最古級のものの一つであり、ユネスコの世界遺産にも登録されています。', '最初の聖堂は、西暦327年ごろ、コンスタンティヌス帝とその母ヘレナの命によって建てられました。6世紀に損傷を受けた後、ユスティニアヌス帝がより大規模に再建し、現在の教会の大部分はこの再建時のものです。内部には十字軍時代のモザイクや彩色された円柱が今も残っています。', 'この教会は、歴史的な「ステータス・クオ（現状維持協定）」のもと、ギリシャ正教会、ローマ・カトリック教会（フランシスコ会）、アルメニア使徒教会の三つの共同体によって共有されています。ベツレヘムの地元のキリスト教徒の家族が世界各地からの巡礼者とともにここで祈りを捧げており、特にクリスマスの時期には多くの人々が集います。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ja', 'エルサレム旧市街にある聖墳墓教会には、キリスト教で最も神聖な二つの場所があります。伝承によれば、イエスが十字架にかけられたゴルゴタと、イエスが葬られ、そして復活された墓です。', '4世紀、コンスタンティヌス帝がこの地に最初の教会を建て、西暦335年に献堂されました。1009年に破壊された後、11世紀に再建され、12世紀には十字軍によって現在の姿の多くが形づくられました。墓を覆う小聖堂（エディクラ）は2016年から2017年にかけて修復されました。', '1852年のステータス・クオのもと、教会の管理はギリシャ正教会、ローマ・カトリック教会（フランシスコ会）、アルメニア使徒教会が共同で担っており、コプト正教会、エチオピア正教会、シリア正教会もそれぞれ礼拝堂を持っています。教会の扉は毎朝、何世紀にもわたって鍵を守り続けてきたイスラム教徒の家族によって開けられます。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'ja', '万国民の教会は、苦悶の聖堂とも呼ばれ、エルサレムのオリーブ山、ゲツセマネにあるローマ・カトリックの教会です。伝承によればイエスが十字架にかけられる前夜に苦しみのうちに祈った場所とされる岩の一部を、堂内に祀っています。', '現在の聖堂は1919年から1924年にかけて、建設中に発見されたより古いビザンツ時代と十字軍時代の教会の基礎の上に建てられました。その建設が多くの国々からの寄付によって支えられたことから万国民の教会と呼ばれるようになり、それらの国々の紋章が天井にはめ込まれています。', '聖堂はフランシスコ会聖地管区によって守られており、この場所と、古いオリーブの木々が茂る隣接のゲツセマネの園を維持しています。今も祈りの場として用いられ、オリーブ山を訪れる巡礼者にとって重要な立ち寄り先となっています。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'ja', 'マグダラのマリア教会は、エルサレムのオリーブ山西斜面、ゲツセマネの園の近くにあるロシア正教会の教会です。七つの金色の玉ねぎ形ドームで広く知られ、エルサレムのスカイラインを特徴づける目印となっています。', 'この教会は1886年から1888年にかけて、ロシア皇帝アレクサンドル3世が母である皇后マリア・アレクサンドロヴナを記念して建てました。皇后の名の由来となった聖人、マグダラのマリアに献堂されており、19世紀後半の聖地におけるロシアの存在を反映しています。', '教会は正教会の修道女の修道院に属し、訪問者や巡礼者を迎え入れる活動的な修道共同体であり続けています。オリーブ山の斜面、ゲツセマネの周辺に位置しています。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'ja', 'ドミヌス・フレヴィト教会は、ラテン語で「主は涙を流された」を意味し、エルサレムのオリーブ山西斜面にあるローマ・カトリックの礼拝堂です。ルカ福音書によれば、イエスがエルサレムを見て涙し、その滅亡を予言した場所を記念しています。', '現在の礼拝堂は1955年に、ビザンツ時代の教会の遺構を含む、より古い宗教建築の跡地に建てられました。敷地内の発掘では古代の墓や納骨器も見つかり、この斜面が長く埋葬地として用いられてきたことを物語っています。', 'ドミヌス・フレヴィトは、エルサレムとその周辺の聖所の一つとして、フランシスコ会聖地管区によって維持されています。オリーブ山を下ってゲツセマネへ向かう巡礼者がよく立ち寄る場所です。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'ja', '聖アンナ教会は、エルサレム旧市街のムスリム地区、ベテスダの池のそばにあるローマ・カトリックの教会です。伝承でアンナとヨアキムの家、また聖母マリアの生誕の地として崇敬されてきた場所の上に建っています。', 'この教会は12世紀、十字軍のエルサレム王国の時代に建てられました。1187年にサラディンが町を征服した後はイスラム教の学校に転用され、19世紀にオスマン帝国当局がフランスに与え、その管理者が建物を修復しました。', '教会とその敷地は、通称「白衣の神父会」として知られるアフリカ宣教会に委ねられており、彼らがこの場所を守り、巡礼者を迎えています。旧市街の中で、今も祈りと学びの活動的な場であり続けています。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'ja', '主の祈りの教会は、エルサレムのオリーブ山にあるローマ・カトリックの教会兼カルメル会修道院です。イエスが弟子たちに、ラテン語で「パーテル・ノステル」として知られる主の祈りを教えたことと伝統的に結びつけられる場所に建っています。', 'この場所は、コンスタンティヌスの治世下、4世紀にオリーブ山の洞窟の上に建てられたビザンツ時代のエレオナ教会の記憶をとどめています。数世紀の荒廃を経て、19世紀にフランスの修道院がここに設立され、教会建築の建設は20世紀まで続きました。', 'この場所はカルメル会の修道女の共同体によって守られ、修道院、教会、回廊を維持しています。オリーブ山を巡る巡礼者や訪問者が定期的に立ち寄る場所です。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'ja', '聖母訪問教会は、エルサレム西端の村エン・ケレムにあるローマ・カトリックの教会です。マリアが親族エリサベトを訪ね、ルカ福音書によれば「マニフィカト」として知られる賛歌を唱えた伝統的な場所を記念しています。この場所はフランシスコ会が守っており、聖地の巡礼者が広く訪れる目的地です。', 'キリスト教の伝承は、エン・ケレムをザカリアとエリサベトの故郷の村、またルカ福音書に記された訪問の舞台と同定しています。ビザンツ時代と十字軍時代にこの場所には教会が建っており、現在の二層の建物はこれらの古い建築の要素を残しています。現在の教会は20世紀前半、フランシスコ会聖地管区のもとで整えられました。', 'この場所はフランシスコ会聖地管区が所有・維持しており、同管区は地域全体の数多くの聖所を守っています。今も祈りの活動的な場であり、エン・ケレムを通る巡礼路の定期的な立ち寄り先であり続けています。エン・ケレムには洗礼者ヨハネの誕生に関わる他の教会もあります。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'ja', '真福八端教会は、ガリラヤ湖の北西岸を見下ろす丘の斜面にあるローマ・カトリックの教会です。山上の説教の伝統的な場所を記念し、その名はマタイ福音書で説教の冒頭を飾る祝福、すなわち真福八端に由来します。ここからは湖と周囲の村々を見渡す広い眺めが得られます。', 'カファルナウム近くの丘を山上の説教の場所とする伝承は古く、下方のタブハ付近ではより古い遺構も確認されています。現在の教会は1938年に建てられ、イタリアの建築家アントニオ・バルルッツィが設計しました。その建設は一部イタリアからの資金によって支えられました。', '教会とその敷地は、聖心フランシスコ宣教修道女会によって守られています。この場所は礼拝の場であるとともに、ガリラヤで広く訪れられる巡礼の目的地となっています。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'ja', 'パンの奇跡の教会は、ガリラヤ湖北西岸のタブハにあるローマ・カトリックの教会です。群衆が養われた、パンと魚を増やした福音書の記述を記念しています。この教会は初期キリスト教のモザイクの床でよく知られています。', 'タブハはビザンツ時代に奇跡の場所として崇敬され、4世紀の小さな礼拝堂は後に5世紀のより大きな教会に取って代わられました。これらの初期の建物は荒廃し、その遺構は近代になって再発見・発掘されました。20世紀に建てられた現在の教会は、ビザンツ様式の聖堂の平面を再現しています。', 'この教会は、エルサレムの被昇天修道院と関わりのあるドイツのベネディクト会の修道士によって奉仕されています。今も活動的な修道と巡礼の場であり続けています。2015年に火災で建物群の一部が損傷し、その後修復されました。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'ja', '聖ペトロ首位権の教会は、ガリラヤ湖の岸辺のタブハにある小さなローマ・カトリックの礼拝堂です。ヨハネ福音書に記された、復活後のイエスが弟子たちに現れたことと、ペトロに首位権が授けられたことを記念しています。礼拝堂は水辺のすぐそばに建っています。', 'この場所は、ヨハネ福音書21章の記述を思い起こさせます。そこでは復活したイエスが湖のほとりで弟子たちに現れ、パンと魚の食事をともにし、三度ペトロに自分の群れを養うよう命じます。この伝統に結びつく教会は以前の世紀にここに存在し、かつての建物の痕跡が近くに残っています。現在の礼拝堂は1933年に建てられました。', '礼拝堂はフランシスコ会聖地管区によって維持されています。ガリラヤ湖北岸周辺の場所を訪れる巡礼者がよく立ち寄る場所です。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'ja', '変容教会は、下ガリラヤのイズレエルの谷の上にそびえるタボル山の頂にあるローマ・カトリックの聖堂です。福音書によればイエスがモーセとエリヤの前で変容した姿を見せた、そのご変容を記念しています。山の別の場所にはギリシャ正教会の教会も建っています。', 'タボル山はビザンツ時代以来、変容の伝統的な場所として崇敬されており、ビザンツ時代と十字軍時代にここに教会が建てられました。これらの建物は後に荒廃し、その基礎が今も山頂に残っています。現在の聖堂は1924年に完成しました。', '聖堂とその敷地はフランシスコ会聖地管区によって守られています。山は今も巡礼の目的地であり、頂はギリシャ正教会の修道院および教会と分かち合われています。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'ja', 'フランシスコ会の婚礼教会は、ナザレの北にあるカフル・カンナに建っています。この町は福音書のガリラヤのカナと広く同定されています。ヨハネ福音書によれば、イエスが水をぶどう酒に変え、それが最初のしるしとされた婚宴を記念しています。この場所は巡礼者を、とりわけ結婚の誓いを記念し新たにするために訪れる夫婦を惹きつけています。', 'ヨハネ福音書（2章）は、イエスとその母、弟子たちをカナの婚礼の場に置いています。そこでは主人のぶどう酒が尽き、イエスが六つの石の甕を水で満たさせると、それがぶどう酒になりました。カフル・カンナでこの奇跡を敬う教会の伝統は幾世紀にもわたって形づくられ、以前の礼拝の場が現在の場所やその近くに建っていました。現在のフランシスコ会の教会は1879年から1905年にかけて建てられました。', '婚礼教会はフランシスコ会聖地管区の修道士によって守られ、礼拝と巡礼の場として維持されています。カフル・カンナには別のギリシャ正教会の教会もあり、近くでこの奇跡の伝統を守っています。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'ja', 'ガリラヤ湖の北岸にあるカファルナウムは、福音書がガリラヤにおけるイエスの宣教の中心地と描く湖畔の町です。この考古遺跡には、使徒ペトロの家として崇敬される遺構と、古代のシナゴーグが保存されています。この地域で最も重要な新約聖書ゆかりの場所の一つです。', '福音書はカファルナウムを、イエスが教え、弟子を召し、癒やしを行った場所として描き、この町をペトロや他の従う者たちと結びつけています。初期の世紀からこの場所の一軒の家はキリスト教徒によって崇敬され、後に八角形の教会の中に囲われました。町は衰退する前、幾世紀にもわたって人が住み、現代の考古学者が研究する遺跡を残しました。', 'この場所はフランシスコ会聖地管区が保有・管理しており、教会、発掘、巡礼者や訪問者の立ち入りを監督しています。この一帯の東端には別のギリシャ正教会の教会と修道院が建っています。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'ja', '羊飼いの野の礼拝堂は、ベツレヘムの東のベイト・サフールに建ち、降誕の物語に登場する羊飼いの野と伝統的に同定される場所にあります。ルカ福音書によれば、天使たちはそこで、夜に群れを見張っていた羊飼いたちにイエスの誕生を告げました。礼拝堂とその周囲の敷地は、とりわけクリスマスの時期に、祈りと巡礼の場となっています。', 'ルカ福音書（2章）は、救い主の誕生を告げられて幼子を捜しに行ったベツレヘム近くの羊飼いたちを描いています。ベイト・サフール近くの羊飼いの野に対するキリスト教の崇敬は非常に古く、この一帯ではより古い教会や修道施設の遺構が見つかっています。現在のフランシスコ会の礼拝堂は1953年に建てられました。', '礼拝堂とその野はフランシスコ会聖地管区によって守られています。別のギリシャ正教会の羊飼いの野があり、独自の教会と古代の遺構を備えて、同じベイト・サフールの一帯の近くにあります。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'ja', '乳の洞窟は、ベツレヘムで、聖誕教会から歩いてすぐの、柔らかな白い石灰岩の洞窟を囲んで建てられた礼拝堂です。伝承はこの洞窟を聖家族と結びつけ、エジプトへの逃避の前、あるいはその途上の時期と関連づけています。ここは静かな祈りの場で、とりわけ母親たちや、子を望む夫婦が訪れます。', '地元の伝承によれば、聖家族はこの洞窟に身を寄せ、その岩が白くなったとされ、そこから名が生まれ、乳と母性に結びつく信心が起こりました。この場所に対するキリスト教の崇敬は幾世紀にもわたって記録されています。洞窟は長らくフランシスコ会の管理下にあり、近代になって古い聖所の傍らにより新しい礼拝堂が加えられました。', '乳の洞窟はフランシスコ会聖地管区によって守られ、祈りの場として維持され、多くの国々からの巡礼者を迎えています。とりわけ母性と家庭のために祈る人々にとって、個人の信心の中心であり続けています。') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
