INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ja', '本プロジェクトでは、構造の補修、ファサードの洗浄、建設当初の建築要素の保存など、聖堂にとって急務となっている修復に取り組みます。この工事によって、建物は将来の世代にとっても安全で訪れやすい場所であり続けます。', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
