INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ja', 'イスラエルとその周辺地域にあるキリスト教の遺産、遺物、写本を撮影・スキャンし、記録する包括的な取り組みです。このデジタルアーカイブは、かけがえのない歴史的記録を研究者と将来の世代のために保存します。', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ja', '聖地各地のキリスト教遺産のデジタル記録。', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'ja', '聖地の遺産記録', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ka', 'ხარების ბაზილიკა კათოლიკური ტაძარია ისრაელის ქალაქ ნაზარეთში. ის ახლო აღმოსავლეთის ერთ-ერთი უდიდესი ტაძარია და დგას იმ ადგილას, სადაც, გადმოცემის თანახმად, მთავარანგელოზ გაბრიელმა ქალწულ მარიამს ახარა, რომ იგი იესოს შობდა.', 'ამჟამინდელი ბაზილიკა 1969 წელს აშენდა იტალიელი არქიტექტორის, ჯოვანი მუციოს პროექტით. ის აღმართულია ბიზანტიური და ჯვაროსნული ხანის ადრინდელი ეკლესიების ნანგრევებზე. ეს ადგილი უძველესი დროიდან ქრისტიან მომლოცველთა სალოცავია.', 'ტაძარი ემსახურება ნაზარეთის ადგილობრივ კათოლიკურ თემს და მასპინძლობს მომლოცველებს მთელი მსოფლიოდან. წირვა რეგულარულად აღევლინება რამდენიმე ენაზე.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ka', 'ბეთლემის ქრისტეს შობის ტაძარი აღმართულია გამოქვაბულზე, რომელსაც ქრისტიანული გადმოცემა II საუკუნიდან პატივს მიაგებს, როგორც იესოს შობის ადგილს. ის მსოფლიოს ერთ-ერთი უძველესი მუდმივად მოქმედი ტაძარია და შეტანილია იუნესკოს მსოფლიო მემკვიდრეობის ძეგლთა ნუსხაში.', 'პირველი ბაზილიკა დაახლოებით ახ. წ. 327 წელს აიგო იმპერატორ კონსტანტინესა და მისი დედის, ელენეს ბრძანებით. VI საუკუნეში დაზიანების შემდეგ იმპერატორ იუსტინიანემ ის უფრო დიდი მასშტაბით აღადგინა და დღევანდელი ტაძრის დიდი ნაწილი სწორედ ამ აღდგენის პერიოდით თარიღდება. ტაძრის შიგნით დღემდეა შემორჩენილი ჯვაროსანთა ეპოქის მოზაიკები და მოხატული სვეტები.', 'ისტორიული სტატუს-კვოს შესაბამისად, ტაძარს ერთობლივად განაგებენ ბერძნული მართლმადიდებლური, რომაულ-კათოლიკური (ფრანცისკელები) და სომხური სამოციქულო თემები. ბეთლემის ადგილობრივი ქრისტიანი ოჯახები აქ ლოცულობენ მთელი მსოფლიოდან ჩამოსულ მომლოცველებთან ერთად, განსაკუთრებით შობის დღესასწაულზე.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ka', 'იერუსალიმის ძველ ქალაქში მდებარე უფლის საფლავის ტაძარი ქრისტიანობის ორ უდიდეს სიწმინდეს მოიცავს: გოლგოთას, სადაც იესო ჯვარს აცვეს, და საფლავს, სადაც, გადმოცემის თანახმად, იგი დაკრძალეს და საიდანაც მკვდრეთით აღდგა.', 'პირველი ტაძარი აქ იმპერატორ კონსტანტინემ IV საუკუნეში ააგო; ის ახ. წ. 335 წელს აკურთხეს. 1009 წელს ტაძარი დაანგრიეს, XI საუკუნეში აღადგინეს, XII საუკუნეში კი ჯვაროსნებმა მას დიდწილად დღევანდელი სახე მისცეს. უფლის საფლავზე აღმართულ კუვუკლიას 2016–2017 წლებში რესტავრაცია ჩაუტარდა.', 'ტაძარზე ერთობლივად ზრუნავენ ბერძნული მართლმადიდებლური, რომაულ-კათოლიკური (ფრანცისკელები) და სომხური სამოციქულო ეკლესიები, ხოლო საკუთარი სამლოცველოები აქვთ ასევე კოპტურ, ეთიოპიურ და სირიულ მართლმადიდებლურ თემებს. ეს წესრიგი განსაზღვრულია 1852 წლის სტატუს-კვოთი. ტაძრის კარს ყოველ დილას აღებენ მუსლიმი ოჯახები, რომლებიც საუკუნეების განმავლობაში ინახავენ მის გასაღებებს.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'ka', 'ყველა ერის ეკლესია, რომელიც ასევე ცნობილია აგონიის ბაზილიკის სახელით, კათოლიკური ეკლესიაა იერუსალიმში, ზეთისხილის მთაზე, გეთსემანიაში. მასში დაცულია კლდის ის ნაწილი, რომელსაც გადმოცემით მიიჩნევენ იმ ადგილად, სადაც იესო ჯვარცმის წინა ღამეს აგონიაში ლოცულობდა.', 'ამჟამინდელი ბაზილიკა აშენდა 1919–1924 წლებში, მშენებლობისას აღმოჩენილი უფრო ადრინდელი ბიზანტიური და ჯვაროსნული ეკლესიების საძირკვლებზე. მას ყველა ერის ეკლესია ეწოდა, რადგან მისი მშენებლობა მრავალი ქვეყნის შემოწირულობით დაფინანსდა, რომელთა გერბებიც ჭერშია ჩასმული.', 'ბაზილიკაზე ზრუნავს წმინდა მიწის ფრანცისკელთა კუსტოდია, რომელიც უვლის ამ ადგილსა და მიმდებარე გეთსემანიის ბაღს მისი უძველესი ზეთისხილის ხეებით. ის რჩება მოქმედ სალოცავ ადგილად და ზეთისხილის მთის მნახველ მომლოცველთა მნიშვნელოვან გაჩერებად.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'ka', 'მარიამ მაგდალინელის ეკლესია რუსული მართლმადიდებლური ეკლესიაა იერუსალიმში, ზეთისხილის მთის დასავლეთ ფერდობზე, გეთსემანიის ბაღთან ახლოს. ის ფართოდ არის ცნობილი თავისი შვიდი მოოქროვილი ხახვისებრი გუმბათით, რაც იერუსალიმის სილუეტის გამორჩეული ნიშანია.', 'ეკლესია 1886–1888 წლებში ააშენა რუსეთის იმპერატორმა ალექსანდრე III-მ დედის, იმპერატრიცა მარია ალექსანდროვნას ხსოვნისადმი. ის მიეძღვნა მარიამ მაგდალინელს — წმინდანს, რომლის სახელიც ერქვა იმპერატრიცას, — და ასახავს XIX საუკუნის ბოლოს წმინდა მიწაზე რუსულ ყოფნას.', 'ეკლესია მართლმადიდებელ მონაზონთა მონასტერს ეკუთვნის და რჩება მოქმედ სამონასტრო თემად, რომელიც მასპინძლობს ვიზიტორებსა და მომლოცველებს. ის მდებარეობს გეთსემანიის შემოგარენში, ზეთისხილის მთის ფერდობებზე.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'ka', 'დომინუს ფლევიტი, რაც ლათინურად ნიშნავს „უფალი ატირდა“, კათოლიკური სამლოცველოა იერუსალიმში, ზეთისხილის მთის დასავლეთ ფერდობზე. ის აღნიშნავს ადგილს, სადაც, ლუკას სახარების თანახმად, იესო ატირდა იერუსალიმისკენ ყურებისას და იწინასწარმეტყველა მისი დანგრევა.', 'ამჟამინდელი სამლოცველო 1955 წელს აშენდა უფრო ადრინდელი სამლოცველო ნაგებობების ადგილას, მათ შორის ბიზანტიური ხანის ეკლესიის ნაშთებზე. ტერიტორიაზე ჩატარებულმა გათხრებმა ასევე გამოავლინა უძველესი სამარხები და ოსუარიუმები, რაც მოწმობს ფერდობის, როგორც სამარხის, ხანგრძლივ გამოყენებას.', 'დომინუს ფლევიტს უვლის წმინდა მიწის ფრანცისკელთა კუსტოდია, როგორც იერუსალიმსა და მის შემოგარენში არსებული სალოცავების ქსელის ნაწილს. სამლოცველო ხშირი გაჩერებაა მომლოცველთათვის, რომლებიც ზეთისხილის მთიდან გეთსემანიისკენ ეშვებიან.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'ka', 'წმინდა ანას ეკლესია კათოლიკური ეკლესიაა იერუსალიმის ძველ ქალაქში, მუსლიმურ კვარტალში, ბეთესდის აუზების გვერდით. ის დგას ადგილას, რომელსაც გადმოცემით პატივს მიაგებენ, როგორც ანასა და იოაკიმეს სახლსა და ქალწულ მარიამის დაბადების ადგილს.', 'ეკლესია XII საუკუნეში აშენდა ჯვაროსანთა იერუსალიმის სამეფოს დროს. 1187 წელს სალადინის მიერ ქალაქის დაპყრობის შემდეგ ის ისლამურ სკოლად გადაკეთდა, ხოლო XIX საუკუნეში ოსმალეთის ხელისუფლებამ ის საფრანგეთს გადასცა, რომლის მზრუნველებმაც შენობა აღადგინეს.', 'ეკლესია და მისი ტერიტორია მინდობილია აფრიკის მისიონერებს, უფრო ცნობილს, როგორც თეთრი მამები, რომლებიც უვლიან ამ ადგილს და მასპინძლობენ მომლოცველებს. ის რჩება ძველ ქალაქში ლოცვისა და სწავლის მოქმედ ადგილად.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'ka', 'პატერ ნოსტერის ეკლესია კათოლიკური ეკლესია და კარმელიტთა მონასტერია იერუსალიმში, ზეთისხილის მთაზე. ის დგას ადგილას, რომელიც გადმოცემით უკავშირდება იესოს, რომელმაც თავის მოწაფეებს ასწავლა უფლის ლოცვა, ლათინურად ცნობილი როგორც „პატერ ნოსტერი“.', 'ეს ადგილი ინახავს ელეონას ბიზანტიური ეკლესიის ხსოვნას, რომელიც IV საუკუნეში კონსტანტინეს მეფობისას აშენდა ზეთისხილის მთაზე მდებარე გამოქვაბულზე. საუკუნეების განმავლობაში ნანგრევად ქცევის შემდეგ აქ XIX საუკუნეში დაარსდა ფრანგული მონასტერი, ხოლო საეკლესიო ნაგებობების მშენებლობა XX საუკუნეშიც გაგრძელდა.', 'ამ ადგილს უვლის კარმელიტ დათა თემი, რომლებიც უვლიან მონასტერს, ეკლესიასა და ეზო-გალერეას. ეს არის რეგულარული გაჩერება ზეთისხილის მთის დამთვალიერებელ მომლოცველთა და ვიზიტორთათვის.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'ka', 'მოხილვის ეკლესია კათოლიკური ეკლესიაა იერუსალიმის დასავლეთ კიდეზე მდებარე სოფელ ეინ ქერემში. ის აღნიშნავს ტრადიციულ ადგილს, სადაც მარიამმა მოინახულა თავისი ნათესავი ელისაბედი და, ლუკას სახარების თანახმად, წარმოთქვა საგალობელი, ცნობილი როგორც „მაგნიფიკატი“. ამ ადგილს ფრანცისკელები უვლიან და ის წმინდა მიწის მომლოცველთა მიერ ფართოდ მონახულებადი ადგილია.', 'ქრისტიანული გადმოცემა ეინ ქერემს აიგივებს ზაქარიასა და ელისაბედის მშობლიურ სოფელთან და ლუკას სახარებაში აღწერილი მოხილვის ადგილთან. ბიზანტიურ და ჯვაროსნულ პერიოდებში ამ ადგილას ეკლესია იდგა, ხოლო ამჟამინდელი ორსართულიანი ნაგებობა ინახავს ამ ადრინდელი ნაგებობების ელემენტებს. ამჟამინდელი ეკლესია XX საუკუნის პირველ ნახევარში ჩამოყალიბდა წმინდა მიწის ფრანცისკელთა კუსტოდიის ხელმძღვანელობით.', 'ეს ადგილი ეკუთვნის და მას უვლის წმინდა მიწის ფრანცისკელთა კუსტოდია, რომელიც ზრუნავს რეგიონის მრავალ სალოცავზე. ის რჩება ლოცვის მოქმედ ადგილად და რეგულარულ გაჩერებად ეინ ქერემში გამავალ სამლოცველო მარშრუტებზე, სადაც ასევეა იოანე ნათლისმცემლის შობასთან დაკავშირებული სხვა ეკლესიები.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'ka', 'ნეტარებათა ეკლესია კათოლიკური ეკლესიაა გალილეის ზღვის ჩრდილო-დასავლეთ სანაპიროს ზემოთ მდებარე ბორცვის ფერდობზე. ის აღნიშნავს მთაზე ქადაგების ტრადიციულ ადგილს და სახელი ნეტარებებისგან მიიღო — კურთხევებისგან, რომლებითაც იწყება ქადაგება მათეს სახარებაში. ამ ადგილიდან იშლება ტბისა და მისი მიმდებარე სოფლების ფართო ხედი.', 'კაპერნაუმთან ახლოს მდებარე ბორცვის, როგორც მთაზე ქადაგების ადგილის, გადმოცემა ძველია, ხოლო უფრო ადრინდელი ნაშთები აღინიშნა ქვემოთ, ტაბღას მახლობლად. ამჟამინდელი ეკლესია 1938 წელს აშენდა იტალიელი არქიტექტორის, ანტონიო ბარლუცის პროექტით. მისი მშენებლობა ნაწილობრივ იტალიის მიერ დაფინანსდა.', 'ეკლესიასა და მის ტერიტორიას უვლიან უწმინდესი გულის ფრანცისკელი მისიონერი დები. ეს ადგილი ფუნქციონირებს როგორც სამლოცველოდ, ისე გალილეაში ფართოდ მონახულებად სამლოცველო დანიშნულების ადგილად.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'ka', 'პურის გამრავლების ეკლესია კათოლიკური ეკლესიაა ტაბღაში, გალილეის ზღვის ჩრდილო-დასავლეთ სანაპიროზე. ის უკავშირდება სახარებისეულ თხრობას პურისა და თევზის გამრავლების შესახებ, რითაც დაპურდა ხალხის სიმრავლე. ეკლესია კარგადაა ცნობილი თავისი ადრექრისტიანული მოზაიკის იატაკებით.', 'ტაბღას ბიზანტიურ პერიოდში პატივს მიაგებდნენ, როგორც სასწაულის ადგილს, და IV საუკუნის პატარა სამლოცველო მოგვიანებით V საუკუნის უფრო დიდმა ეკლესიამ შეცვალა. ეს ადრინდელი ნაგებობები ნანგრევად იქცა, ხოლო მათი ნაშთები ხელახლა აღმოაჩინეს და გათხარეს თანამედროვე დროში. ამჟამინდელი ეკლესია, აშენებული XX საუკუნეში, იმეორებს ბიზანტიური ბაზილიკის გეგმას.', 'ეკლესიას ემსახურებიან გერმანელი ბენედიქტელი ბერები, დაკავშირებულნი იერუსალიმის მიძინების სავანესთან. ის რჩება მოქმედ სამონასტრო და სამლოცველო ადგილად; 2015 წელს ხანძარმა კომპლექსის ნაწილი დააზიანა, რის შემდეგაც ის აღადგინეს.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'ka', 'წმინდა პეტრეს პირველობის ეკლესია პატარა კათოლიკური სამლოცველოა ტაბღაში, გალილეის ზღვის სანაპიროზე. ის უკავშირდება იოანეს სახარებაში აღწერილ, აღდგომის შემდეგ იესოს გამოცხადებას მოწაფეებთან და პეტრესთვის პირველობის მინიჭებას. სამლოცველო პირდაპირ წყლის პირას დგას.', 'ეს ადგილი ახსენებს იოანეს სახარების 21-ე თავის თხრობას, სადაც აღმდგარი იესო ეცხადება მოწაფეებს ტბის პირას, უზიარებს მათ პურისა და თევზის ტრაპეზს და სამჯერ ავალებს პეტრეს, დამწყემსოს მისი სამწყსო. ამ გადმოცემასთან დაკავშირებული ეკლესია აქ არსებობდა წინა საუკუნეებში, ხოლო ყოფილი ნაგებობების კვალი მახლობლად შემორჩა. ამჟამინდელი სამლოცველო 1933 წელს აშენდა.', 'სამლოცველოს უვლის წმინდა მიწის ფრანცისკელთა კუსტოდია. ეს ხშირი გაჩერებაა მომლოცველთათვის, რომლებიც სტუმრობენ გალილეის ზღვის ჩრდილოეთ სანაპიროს გარშემო არსებულ ადგილებს.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'ka', 'ფერისცვალების ეკლესია კათოლიკური ბაზილიკაა თაბორის მთის მწვერვალზე, რომელიც ქვემო გალილეაში იზრეელის ველის ზემოთ იმართება. ის უკავშირდება იესოს ფერისცვალებას, როდესაც, სახარებების თანახმად, ის მოსესა და ელიას თანდასწრებით გარდაფერილი გამოჩნდა. მთის სხვა ადგილას ასევე დგას ბერძნული მართლმადიდებლური ეკლესია.', 'თაბორის მთას ბიზანტიური პერიოდიდან პატივს მიაგებენ, როგორც ფერისცვალების ტრადიციულ ადგილს, და აქ ეკლესიები აშენდა ბიზანტიურ და ჯვაროსნულ დროში. ეს ნაგებობები მოგვიანებით დაინგრა, ხოლო მათი საძირკვლები მწვერვალზე შემორჩა. ამჟამინდელი ბაზილიკა 1924 წელს დასრულდა.', 'ბაზილიკასა და მის ტერიტორიას უვლის წმინდა მიწის ფრანცისკელთა კუსტოდია. მთა რჩება სამლოცველო დანიშნულების ადგილად, ხოლო მწვერვალს მას იზიარებს ბერძნული მართლმადიდებლური მონასტერი და ეკლესია.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'ka', 'ფრანცისკელთა ქორწილის ეკლესია დგას კაფრ ქანაში — ქალაქში ნაზარეთის ჩრდილოეთით, რომელიც ფართოდ აიგივება სახარებების გალილეის კანასთან. ის უკავშირდება საქორწილო ლხინს, რომელზეც, იოანეს სახარების თანახმად, იესომ წყალი ღვინოდ აქცია, აღწერილი როგორც მისი პირველი სასწაული. ეს ადგილი იზიდავს მომლოცველებს და, განსაკუთრებით, დაქორწინებულ წყვილებს, რომლებიც მოდიან თავიანთი აღთქმების აღსანიშნავად და განსაახლებლად.', 'იოანეს სახარება (თავი 2) იესოს, მის დედასა და მოწაფეებს ათავსებს ქორწილში კანაში, სადაც მასპინძელს ღვინო გამოელია და იესომ ბრძანა ექვსი ქვის ჭურჭლის წყლით ავსება, რომელიც ღვინოდ იქცა. კაფრ ქანაში ამ სასწაულის მადიდებელი საეკლესიო გადმოცემა საუკუნეების განმავლობაში ჩამოყალიბდა, ხოლო უფრო ადრინდელი სამლოცველო ადგილები ამჟამინდელ ადგილას ან მის მახლობლად იდგა. ამჟამინდელი ფრანცისკელთა ეკლესია 1879–1905 წლებში აშენდა.', 'ქორწილის ეკლესიას უვლიან წმინდა მიწის კუსტოდიის ფრანცისკელი ბერები, რომლებიც მას თაყვანისცემისა და მომლოცველობის ადგილად ინახავენ. კაფრ ქანაში ცალკე ბერძნული მართლმადიდებლური ეკლესიაც ინახავს მახლობლად ამ სასწაულის გადმოცემას.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'ka', 'კაპერნაუმი, გალილეის ზღვის ჩრდილოეთ სანაპიროზე, ტბისპირა ქალაქია, რომელსაც სახარებები აღწერენ, როგორც გალილეაში იესოს მსახურების ცენტრს. არქეოლოგიური ძეგლი ინახავს ნაშთებს, რომლებსაც პატივს მიაგებენ, როგორც მოციქულ პეტრეს სახლს, და უძველეს სინაგოგას. ის რეგიონის ერთ-ერთი უმნიშვნელოვანესი ახალაღთქმისეული ადგილია.', 'სახარებები კაპერნაუმს წარმოადგენენ, როგორც ადგილს, სადაც იესო ასწავლიდა, მოწაფეებს იხმობდა და კურნავდა, და ქალაქს უკავშირებენ პეტრესა და სხვა მიმდევრებს. ადრეული საუკუნეებიდან ამ ადგილას მდებარე სახლს ქრისტიანები პატივს მიაგებდნენ და მოგვიანებით ის რვაკუთხა ეკლესიით შემოისაზღვრა. ქალაქი საუკუნეების განმავლობაში დასახლებული იყო, სანამ დაკნინდებოდა და დატოვებდა ნანგრევებს, რომლებსაც თანამედროვე არქეოლოგები იკვლევენ.', 'ამ ადგილს ფლობს და უვლის წმინდა მიწის ფრანცისკელთა კუსტოდია, რომელიც ზედამხედველობს ეკლესიას, გათხრებსა და მომლოცველთა და ვიზიტორთა ხელმისაწვდომობას. ტერიტორიის აღმოსავლეთ კიდეზე დგას ცალკე ბერძნული მართლმადიდებლური ეკლესია და მონასტერი.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'ka', 'მწყემსთა მინდვრის სამლოცველო დგას ბეით საჰურში, ბეთლემის აღმოსავლეთით, ადგილას, რომელიც გადმოცემით აიგივება შობის ისტორიის მწყემსთა მინდვრებთან. ლუკას სახარების თანახმად, ანგელოზებმა იქ აუწყეს იესოს დაბადება მწყემსებს, რომლებიც ღამით თავიანთ ფარას იცავდნენ. სამლოცველო და მისი მიმდებარე ტერიტორია ლოცვისა და მომლოცველობის ადგილია, განსაკუთრებით შობის დღესასწაულზე.', 'ლუკას სახარება (თავი 2) აღწერს ბეთლემთან ახლოს მყოფ მწყემსებს, რომლებსაც აუწყეს მხსნელის დაბადება და რომლებიც წავიდნენ ბავშვის მოსაძებნად. ბეით საჰურთან მწყემსთა მინდვრების ქრისტიანული თაყვანისცემა ძალიან ძველია, და ამ ტერიტორიაზე აღმოჩენილია უფრო ადრინდელი ეკლესიებისა და სამონასტრო ნაგებობების ნაშთები. ამჟამინდელი ფრანცისკელთა სამლოცველო 1953 წელს აშენდა.', 'სამლოცველოსა და მის მინდორს უვლის წმინდა მიწის ფრანცისკელთა კუსტოდია. ცალკე ბერძნული მართლმადიდებლური მწყემსთა მინდორი, საკუთარი ეკლესიითა და უძველესი ნაშთებით, მდებარეობს მახლობლად, ბეით საჰურის იმავე ტერიტორიაზე.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'ka', 'რძის გამოქვაბული სამლოცველოა, აშენებული ბეთლემში რბილი თეთრი ცარცის გამოქვაბულის გარშემო, შობის ტაძრიდან მცირე მანძილზე. გადმოცემა გამოქვაბულს უკავშირებს წმინდა ოჯახს, აკავშირებს მას ეგვიპტეში გაქცევის წინა ან მისი მიმდინარეობის დროსთან. ეს ლოცვის მშვიდი ადგილია, რომელსაც განსაკუთრებით სტუმრობენ დედები და შვილების მოსურნე წყვილები.', 'ადგილობრივი გადმოცემა ამბობს, რომ წმინდა ოჯახი ამ გამოქვაბულში შეაფარა თავს და მისი კლდე გათეთრდა, რამაც წარმოშვა სახელი და რძესა და დედობასთან დაკავშირებული თაყვანისცემა. ამ ადგილის ქრისტიანული თაყვანისცემა მრავალი საუკუნის განმავლობაშია დადასტურებული. გამოქვაბული დიდი ხანია ფრანცისკელთა მზრუნველობის ქვეშაა, ხოლო ახალ დროში ძველი სალოცავის გვერდით უფრო ახალი სამლოცველო დაემატა.', 'რძის გამოქვაბულს უვლის წმინდა მიწის ფრანცისკელთა კუსტოდია, რომელიც მას ლოცვის ადგილად ინახავს და იღებს მომლოცველებს მრავალი ქვეყნიდან. ის რჩება პირადი ღვთისმოსაობის კერად, განსაკუთრებით მათთვის, ვინც დედობასა და ოჯახზე ლოცულობს.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
