INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'ba05a1f8-57a8-428d-955b-849cafe8e2d7', 'content', 'ka', 'გიწვევთ შობის სადღესასწაულო წირვებსა და ღონისძიებებზე. განრიგი გამოქვეყნებულია ჩვენს ვებგვერდზე.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'ba05a1f8-57a8-428d-955b-849cafe8e2d7', 'title', 'ka', 'შობის დღესასწაული — 2025', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'c9d47aef-6caf-43fc-bb95-ac3ea1c0fca9', 'content', 'ka', 'დაიწყო ჩვენი სარესტავრაციო პროექტის პირველი ეტაპი. გმადლობთ მხარდაჭერისთვის.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('church_update', 'c9d47aef-6caf-43fc-bb95-ac3ea1c0fca9', 'title', 'ka', 'სარესტავრაციო პროექტის სიახლეები', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
