INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ka', 'ფართომასშტაბიანი ინიციატივა ისრაელსა და მიმდებარე რეგიონებში ქრისტიანული მემკვიდრეობის ძეგლების, არტეფაქტებისა და ხელნაწერების ფოტოგადაღების, სკანირებისა და დოკუმენტირებისთვის. ეს ციფრული არქივი მკვლევრებისა და მომავალი თაობებისთვის შეინახავს ფასდაუდებელ ისტორიულ წყაროებს.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ka', 'ქრისტიანული მემკვიდრეობის ძეგლების ციფრული დოკუმენტირება მთელ წმინდა მიწაზე.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'ka', 'წმინდა მიწის მემკვიდრეობის დოკუმენტირება', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'ko', '주님 탄생 예고 대성당은 이스라엘 나자렛에 위치한 가톨릭 교회입니다. 중동에서 가장 큰 교회 중 하나이며, 대천사 가브리엘이 마리아에게 예수를 잉태할 것이라고 알린 전통적인 장소를 기념합니다.', '현재의 대성당은 1969년에 이탈리아 건축가 조반니 무치오의 설계로 건립되었습니다. 이전의 비잔틴 및 십자군 시대 교회 유적 위에 세워졌습니다. 이곳은 고대부터 그리스도교 순례지로 여겨져 왔습니다.', '이 교회는 나자렛의 지역 가톨릭 공동체를 섬기며 전 세계에서 온 순례자들을 맞이합니다. 여러 언어로 정기적인 미사가 봉헌됩니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'ko', '베들레헴에 있는 예수 탄생 교회는 그리스도교 전통에서 2세기부터 예수님의 탄생지로 공경해 온 동굴 위에 세워져 있습니다. 세계에서 가장 오래도록 계속 사용되어 온 교회 중 하나이며 유네스코 세계문화유산입니다.', '최초의 대성당은 서기 327년경 콘스탄티누스 황제와 그의 어머니 헬레나에 의해 건립되었습니다. 6세기에 훼손된 후 유스티니아누스 황제가 더 큰 규모로 재건했으며, 오늘날 교회의 많은 부분이 이 재건 당시의 모습입니다. 십자군 시대의 모자이크와 채색 기둥이 내부에 여전히 남아 있습니다.', '이 교회는 역사적인 현상 유지 협정 아래 그리스 정교회, 로마 가톨릭(프란치스코회), 아르메니아 사도교회 공동체가 함께 관리합니다. 베들레헴의 지역 그리스도교 가정들은 특히 성탄절에 전 세계에서 온 순례자들과 함께 이곳에서 예배를 드립니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'ko', '예루살렘 구시가지에 있는 성묘 교회에는 그리스도교의 가장 거룩한 두 장소가 있습니다. 예수님이 십자가에 못 박히신 골고다와, 전통에 따르면 그분이 묻히고 부활하신 무덤입니다.', '콘스탄티누스 황제가 4세기에 이곳에 최초의 교회를 세웠으며, 335년에 봉헌되었습니다. 1009년에 파괴되었다가 11세기에 재건되었고, 12세기에 십자군이 현재의 모습을 크게 형성했습니다. 무덤 위의 에디큘(성작은집)은 2016~2017년에 복원되었습니다.', '이 교회의 관리는 그리스 정교회, 로마 가톨릭(프란치스코회), 아르메니아 사도교회가 공동으로 맡고 있으며, 콥트, 에티오피아, 시리아 정교회 공동체도 1852년의 현상 유지 협정에 따라 각각 경당을 소유하고 있습니다. 문은 수 세기 동안 열쇠를 지켜온 무슬림 가문이 매일 아침 엽니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'ko', '만국 교회는 고통의 대성당이라고도 불리며, 예루살렘 올리브산 겟세마니에 있는 로마 가톨릭 교회입니다. 전통적으로 예수님이 십자가에 못 박히기 전날 밤 고뇌 속에서 기도하신 곳으로 여겨지는 바위의 일부를 안에 모시고 있습니다.', '현재의 대성당은 1919년에서 1924년 사이에, 공사 중 발견된 더 오래된 비잔틴 시대와 십자군 시대 교회의 기초 위에 세워졌습니다. 그 건립이 여러 나라의 기부로 이루어졌기에 만국 교회로 불리게 되었으며, 그 나라들의 문장이 천장에 새겨져 있습니다.', '대성당은 성지 프란치스코회 관구가 돌보고 있으며, 이곳과 오래된 올리브 나무가 있는 인접한 겟세마니 동산을 관리합니다. 지금도 기도의 장소로 쓰이며, 올리브산을 찾는 순례자들에게 중요한 방문지입니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'ko', '막달레나 마리아 교회는 예루살렘 올리브산 서쪽 비탈, 겟세마니 동산 가까이에 있는 러시아 정교회 교회입니다. 일곱 개의 도금된 양파 모양 돔으로 널리 알려져 있으며, 예루살렘 스카이라인의 독특한 상징입니다.', '이 교회는 1886년에서 1888년 사이에 러시아의 차르 알렉산드르 3세가 자신의 어머니 마리야 알렉산드로브나 황후를 기리기 위해 세웠습니다. 황후의 이름이 유래한 성인인 막달레나 마리아에게 봉헌되었으며, 19세기 말 성지에서의 러시아의 존재를 보여 줍니다.', '교회는 정교회 수녀들의 수도원에 속해 있으며, 방문객과 순례자를 맞이하는 활동적인 수도 공동체로 남아 있습니다. 올리브산 비탈, 겟세마니 주변에 자리하고 있습니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'ko', '도미누스 플레비트 교회는 라틴어로 「주님께서 우셨다」를 뜻하며, 예루살렘 올리브산 서쪽 비탈에 있는 로마 가톨릭 경당입니다. 루카 복음서에 따르면 예수님이 예루살렘을 바라보며 우시고 그 멸망을 예언하신 곳을 기념합니다.', '현재의 경당은 1955년에 비잔틴 시대 교회의 유적을 포함한 더 오래된 종교 건물 터 위에 세워졌습니다. 경내의 발굴에서는 고대 무덤과 유골함도 드러나, 이 비탈이 오랫동안 매장지로 쓰였음을 증언합니다.', '도미누스 플레비트는 예루살렘과 그 주변에 있는 성소망의 일부로서 성지 프란치스코회 관구가 관리합니다. 올리브산에서 겟세마니로 내려가는 순례자들이 자주 들르는 곳입니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'ko', '성 안나 교회는 예루살렘 옛 도시의 무슬림 구역, 벳자타 못 옆에 있는 로마 가톨릭 교회입니다. 전통적으로 안나와 요아킴의 집이자 동정 마리아의 탄생지로 공경받아 온 곳 위에 서 있습니다.', '이 교회는 12세기 십자군 예루살렘 왕국 시대에 세워졌습니다. 1187년 살라딘이 도시를 정복한 뒤에는 이슬람 학교로 바뀌었고, 19세기에 오스만 당국이 프랑스에 넘겨주어 그 관리자들이 건물을 복원했습니다.', '교회와 그 부지는 흔히 백의 신부회로 알려진 아프리카 선교회에 맡겨져 있으며, 이들이 이곳을 돌보고 순례자를 맞이합니다. 옛 도시 안에서 지금도 기도와 학문의 활동적인 장소로 남아 있습니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'ko', '주님의 기도 교회는 예루살렘 올리브산에 있는 로마 가톨릭 교회이자 가르멜회 수도원입니다. 예수님이 제자들에게 라틴어로 「파테르 노스테르」로 알려진 주님의 기도를 가르치신 것과 전통적으로 연결되는 곳에 서 있습니다.', '이곳은 콘스탄티누스 재위 중 4세기에 올리브산의 한 동굴 위에 세워진 비잔틴 시대의 엘레오나 교회의 기억을 간직하고 있습니다. 수 세기의 폐허를 거쳐 19세기에 이곳에 프랑스 수도원이 설립되었고, 교회 건물의 건축은 20세기까지 이어졌습니다.', '이곳은 가르멜회 수녀 공동체가 돌보며, 수도원과 교회, 회랑을 관리합니다. 올리브산을 둘러보는 순례자와 방문객이 정기적으로 들르는 곳입니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'ko', '성모 방문 교회는 예루살렘 서쪽 끝의 마을 아인 카렘에 있는 로마 가톨릭 교회입니다. 마리아가 친척 엘리사벳을 방문하고, 루카 복음서에 따르면 「마니피캇」으로 알려진 찬가를 노래한 전통적인 곳을 기념합니다. 이곳은 프란치스코회가 돌보며, 성지 순례자들이 널리 찾는 목적지입니다.', '그리스도교 전통은 아인 카렘을 즈카르야와 엘리사벳의 고향 마을이자 루카 복음서에 기록된 성모 방문의 무대로 여깁니다. 비잔틴 시대와 십자군 시대에 이곳에 교회가 서 있었으며, 현재의 2층 건물은 이 이전 건축물들의 요소를 간직하고 있습니다. 현재의 교회는 20세기 전반에 성지 프란치스코회 관구 아래에서 조성되었습니다.', '이곳은 성지 프란치스코회 관구가 소유하고 관리하며, 이 관구는 지역 전역의 수많은 성소를 돌봅니다. 지금도 기도의 활동적인 장소이자 아인 카렘을 지나는 순례길의 정기적인 방문지로 남아 있으며, 아인 카렘에는 세례자 요한의 탄생과 관련된 다른 교회들도 있습니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'ko', '참행복 교회는 갈릴래아 호수 북서 기슭 위의 언덕 비탈에 있는 로마 가톨릭 교회입니다. 산상 설교의 전통적인 장소를 기념하며, 그 이름은 마태오 복음서에서 설교를 여는 축복인 참행복에서 유래합니다. 이곳에서는 호수와 주변 마을들을 바라보는 넓은 전망이 펼쳐집니다.', '카파르나움 근처의 한 언덕을 산상 설교의 장소로 보는 전통은 오래되었으며, 아래쪽 타브가 부근에서는 더 오래된 유적도 확인되었습니다. 현재의 교회는 1938년에 세워졌고, 이탈리아 건축가 안토니오 바를루치가 설계했습니다. 그 건립은 부분적으로 이탈리아의 후원으로 이루어졌습니다.', '교회와 그 부지는 예수 성심 프란치스코 선교 수녀회가 돌봅니다. 이곳은 예배의 장소이자 갈릴래아에서 널리 찾는 순례 목적지로 기능합니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'ko', '오병이어 교회는 갈릴래아 호수 북서 기슭 타브가에 있는 로마 가톨릭 교회입니다. 무리가 배불리 먹은, 빵과 물고기를 늘리신 복음서의 이야기를 기념합니다. 이 교회는 초기 그리스도교의 모자이크 바닥으로 잘 알려져 있습니다.', '타브가는 비잔틴 시대에 기적의 장소로 공경받았으며, 4세기의 작은 경당은 이후 5세기에 더 큰 교회로 대체되었습니다. 이 초기 건물들은 폐허가 되었고, 그 유적은 근대에 다시 발견되어 발굴되었습니다. 20세기에 세워진 현재의 교회는 비잔틴 대성당의 평면을 재현하고 있습니다.', '교회는 예루살렘의 성모 영면 수도원과 관련된 독일 베네딕도회 수도자들이 섬깁니다. 지금도 활동적인 수도와 순례의 장소로 남아 있으며, 2015년에 화재로 복합 건물의 일부가 손상되었다가 이후 복구되었습니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'ko', '성 베드로 수위권 교회는 갈릴래아 호수 기슭 타브가에 있는 작은 로마 가톨릭 경당입니다. 요한 복음서에 기록된, 부활 후 예수님이 제자들에게 나타나신 것과 베드로에게 수위권이 주어진 것을 기념합니다. 경당은 바로 물가에 서 있습니다.', '이곳은 요한 복음서 21장의 이야기를 떠올리게 합니다. 그곳에서 부활하신 예수님은 호숫가에서 제자들에게 나타나시어 빵과 물고기의 식사를 함께 나누시고, 세 번 베드로에게 당신의 양 떼를 먹이라고 이르십니다. 이 전통과 관련된 교회가 이전 세기에 이곳에 있었으며, 옛 건물의 흔적이 인근에 남아 있습니다. 현재의 경당은 1933년에 세워졌습니다.', '경당은 성지 프란치스코회 관구가 관리합니다. 갈릴래아 호수 북쪽 기슭 주변의 장소를 찾는 순례자들이 자주 들르는 곳입니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'ko', '거룩한 변모 교회는 하 갈릴래아의 이즈르엘 평야 위로 솟은 타보르산 정상에 있는 로마 가톨릭 대성당입니다. 복음서에 따르면 예수님이 모세와 엘리야가 있는 가운데 변모하신 모습을 보이신, 그 거룩한 변모를 기념합니다. 산의 다른 곳에는 그리스 정교회 교회도 서 있습니다.', '타보르산은 비잔틴 시대 이래로 거룩한 변모의 전통적인 장소로 공경받아 왔으며, 비잔틴 시대와 십자군 시대에 이곳에 교회가 세워졌습니다. 이 건물들은 후에 폐허가 되었고, 그 기초가 지금도 정상에 남아 있습니다. 현재의 대성당은 1924년에 완공되었습니다.', '대성당과 그 부지는 성지 프란치스코회 관구가 돌봅니다. 산은 지금도 순례 목적지로 남아 있으며, 정상은 그리스 정교회 수도원 및 교회와 공유되고 있습니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'ko', '프란치스코회 혼인 교회는 나자렛 북쪽의 카프르 칸나에 서 있으며, 이 마을은 복음서의 갈릴래아 카나와 널리 동일시됩니다. 요한 복음서에 따르면 예수님이 물을 포도주로 바꾸신, 그분의 첫 표징으로 전해지는 혼인 잔치를 기념합니다. 이곳은 순례자를, 특히 혼인 서약을 기념하고 새로이 하려고 찾아오는 부부를 끌어들입니다.', '요한 복음서(2장)는 예수님과 그 어머니, 제자들을 카나의 혼인 잔치에 두는데, 그곳에서 주인의 포도주가 떨어지자 예수님이 여섯 개의 돌항아리를 물로 채우게 하시니 그것이 포도주가 되었습니다. 카프르 칸나에서 이 기적을 기리는 교회 전통은 수 세기에 걸쳐 형성되었고, 이전의 예배 장소가 현재의 자리나 그 근처에 서 있었습니다. 현재의 프란치스코회 교회는 1879년에서 1905년 사이에 세워졌습니다.', '혼인 교회는 성지 관구의 프란치스코회 수도자들이 돌보며, 예배와 순례의 장소로 관리합니다. 카프르 칸나에는 별도의 그리스 정교회 교회도 있어 인근에서 이 기적의 전통을 간직하고 있습니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'ko', '갈릴래아 호수 북쪽 기슭에 있는 카파르나움은 복음서가 갈릴래아에서의 예수님 활동의 중심지로 묘사하는 호숫가 마을입니다. 이 고고학 유적지에는 사도 베드로의 집으로 공경받는 유적과 고대 회당이 보존되어 있습니다. 이 지역에서 가장 중요한 신약 성경의 장소 중 하나입니다.', '복음서는 카파르나움을 예수님이 가르치고 제자를 부르며 병을 고치신 곳으로 제시하고, 이 마을을 베드로와 다른 추종자들과 연결합니다. 초기 세기부터 이곳의 한 집이 그리스도인들에게 공경받았고, 후에 팔각형 교회 안에 둘러싸였습니다. 이 마을은 쇠퇴하기 전까지 수 세기 동안 사람이 살았으며, 오늘날 현대 고고학자들이 연구하는 유적을 남겼습니다.', '이곳은 성지 프란치스코회 관구가 소유하고 돌보며, 교회와 발굴, 순례자 및 방문객의 출입을 관리합니다. 이 구역의 동쪽 끝에는 별도의 그리스 정교회 교회와 수도원이 서 있습니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'ko', '목자들의 들판 경당은 베들레헴 동쪽 베이트 사후르에 서 있으며, 전통적으로 성탄 이야기 속 목자들의 들판과 동일시되는 곳에 있습니다. 루카 복음서에 따르면, 천사들이 그곳에서 밤에 양 떼를 지키던 목자들에게 예수님의 탄생을 알렸습니다. 경당과 그 주변의 부지는 특히 성탄 시기에 기도와 순례의 장소가 됩니다.', '루카 복음서(2장)는 구세주의 탄생 소식을 듣고 아기를 찾아 나선 베들레헴 근처의 목자들을 묘사합니다. 베이트 사후르 근처 목자들의 들판에 대한 그리스도교의 공경은 매우 오래되었으며, 이 지역에서 더 오래된 교회와 수도 건물의 유적이 발견되었습니다. 현재의 프란치스코회 경당은 1953년에 세워졌습니다.', '경당과 그 들판은 성지 프란치스코회 관구가 돌봅니다. 별도의 그리스 정교회 목자들의 들판이 자체 교회와 고대 유적을 갖추고 같은 베이트 사후르 지역의 인근에 있습니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'ko', '젖 동굴은 베들레헴에서 예수 탄생 교회로부터 걸어서 가까운 거리에 있는, 부드러운 흰 백악 동굴을 둘러싸고 세워진 경당입니다. 전통은 이 동굴을 성가정과 연결하여, 이집트로 피난하기 전이나 그 도중의 시기와 관련짓습니다. 이곳은 조용한 기도의 장소로, 특히 어머니들과 자녀를 바라는 부부가 찾습니다.', '지역 전통에 따르면 성가정이 이 동굴에 몸을 피했고 그 바위가 희게 변했다고 하며, 여기에서 이름이 생겨나고 젖과 모성에 관련된 신심이 일어났습니다. 이곳에 대한 그리스도교의 공경은 여러 세기에 걸쳐 기록되어 있습니다. 동굴은 오래도록 프란치스코회의 돌봄 아래 있었으며, 근대에 옛 성소 옆에 더 새로운 경당이 더해졌습니다.', '젖 동굴은 성지 프란치스코회 관구가 돌보며, 기도의 장소로 관리하고 여러 나라에서 온 순례자를 맞이합니다. 특히 모성과 가정을 위해 기도하는 이들에게 개인 신심의 중심으로 남아 있습니다.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
