INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', '593f2031-2c23-4d15-86c5-7487a8296b4f', 'content', 'ml', 'ഘടനാപരമായ വിലയിരുത്തൽ ഘട്ടം വിജയകരമായി പൂർത്തിയായി. ശ്രദ്ധ ആവശ്യമുള്ള പ്രധാന മേഖലകൾ എൻജിനിയർമാർ കണ്ടെത്തിയിട്ടുണ്ട്.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', '593f2031-2c23-4d15-86c5-7487a8296b4f', 'title', 'ml', 'വിലയിരുത്തൽ പൂർത്തിയായി', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', 'ee7631c8-fb98-4e45-b8ea-9fa78251cd23', 'content', 'ml', 'ഉയർന്ന റെസല്യൂഷനുള്ള ഫോട്ടോഗ്രഫിയും 3D സ്കാനുകളും ഉപയോഗിച്ച് ഞങ്ങളുടെ ആദ്യ 50 പൈതൃക കേന്ദ്രങ്ങൾ വിജയകരമായി രേഖപ്പെടുത്തി.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project_update', 'ee7631c8-fb98-4e45-b8ea-9fa78251cd23', 'title', 'ml', 'ആദ്യ 50 കേന്ദ്രങ്ങൾ രേഖപ്പെടുത്തി', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'ml', 'പുനരുദ്ധാരണം', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ml', 'ഘടനാപരമായ അറ്റകുറ്റപ്പണികൾ, മുൻഭാഗം വൃത്തിയാക്കൽ, യഥാർത്ഥ വാസ്തുവിദ്യാ ഘടകങ്ങളുടെ സംരക്ഷണം എന്നിവയുൾപ്പെടെ ബസിലിക്കയുടെ അത്യാവശ്യ പുനരുദ്ധാരണ ആവശ്യങ്ങളിലാണ് ഈ പദ്ധതി ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നത്. വരുംതലമുറകൾക്കായി കെട്ടിടം സുരക്ഷിതവും പ്രാപ്യവുമായി തുടരുന്നുവെന്ന് ഈ പ്രവർത്തനം ഉറപ്പാക്കും.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'ml', 'മംഗളവാർത്ത ബസിലിക്കയുടെ പ്രധാന നടുത്തളത്തിന്റെയും മുൻഭാഗത്തിന്റെയും പുനരുദ്ധാരണം.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'ml', 'ബസിലിക്ക പുനരുദ്ധാരണം - ഒന്നാം ഘട്ടം', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'ml', 'രേഖപ്പെടുത്തൽ', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ml', 'ഇസ്രായേലിലും സമീപ പ്രദേശങ്ങളിലുമുള്ള ക്രൈസ്തവ പൈതൃക കേന്ദ്രങ്ങൾ, പുരാവസ്തുക്കൾ, കൈയെഴുത്തുപ്രതികൾ എന്നിവ ഫോട്ടോയെടുക്കാനും സ്കാൻ ചെയ്യാനും രേഖപ്പെടുത്താനുമുള്ള സമഗ്രമായ ഒരു സംരംഭം. ഈ ഡിജിറ്റൽ ശേഖരം ഗവേഷകർക്കും വരുംതലമുറകൾക്കുമായി വിലമതിക്കാനാവാത്ത ചരിത്രരേഖകൾ കാത്തുസൂക്ഷിക്കും.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ml', 'വിശുദ്ധനാട്ടിലുടനീളമുള്ള ക്രൈസ്തവ പൈതൃക കേന്ദ്രങ്ങളുടെ ഡിജിറ്റൽ രേഖപ്പെടുത്തൽ.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'ml', 'വിശുദ്ധനാട് പൈതൃക രേഖപ്പെടുത്തൽ', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'nl', 'De Basiliek van de Aankondiging is een katholieke kerk in Nazareth, Israël. Het is een van de grootste kerken in het Midden-Oosten en markeert de traditionele plaats waar de aartsengel Gabriël aan Maria verkondigde dat zij Jezus zou baren.', 'De huidige basiliek werd in 1969 gebouwd, ontworpen door de Italiaanse architect Giovanni Muzio. Ze staat boven de ruïnes van eerdere Byzantijnse en kruisvaarderskerken. De plaats is sinds de oudheid een oord van christelijke bedevaart.', 'De kerk dient de plaatselijke katholieke gemeenschap in Nazareth en verwelkomt pelgrims van over de hele wereld. Er worden regelmatig missen in meerdere talen gehouden.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'nl', 'De Geboortekerk in Bethlehem staat boven de grot die de christelijke traditie sinds de 2e eeuw vereert als de geboorteplaats van Jezus. Het is een van de oudste onafgebroken gebruikte kerken ter wereld en een werelderfgoed van UNESCO.', 'De eerste basiliek werd rond 327 na Chr. in opdracht gegeven door keizer Constantijn en zijn moeder Helena. Nadat ze in de 6e eeuw beschadigd raakte, liet keizer Justinianus haar op grotere schaal herbouwen, en een groot deel van de huidige kerk stamt uit die herbouw. Mozaïeken en beschilderde zuilen uit de kruisvaarderstijd zijn binnen nog bewaard gebleven.', 'De kerk wordt gedeeld door de Grieks-orthodoxe, de rooms-katholieke (franciscaanse) en de Armeens-apostolische gemeenschap onder de historische status-quoregeling. Plaatselijke christelijke families uit Bethlehem bidden hier samen met pelgrims van over de hele wereld, vooral met Kerstmis.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'nl', 'De Heilig Grafkerk in de oude stad van Jeruzalem bevat de twee heiligste plaatsen van het christendom: Golgotha, waar Jezus werd gekruisigd, en het graf waar hij volgens de traditie werd begraven en weer opstond.', 'Keizer Constantijn liet hier in de 4e eeuw de eerste kerk bouwen; ze werd in 335 na Chr. ingewijd. Ze werd in 1009 verwoest en in de 11e eeuw herbouwd, en de kruisvaarders gaven haar in de 12e eeuw grotendeels haar huidige vorm. De Edicula boven het graf werd in 2016–2017 gerestaureerd.', 'De zorg voor de kerk wordt gedeeld door de Grieks-orthodoxe, de rooms-katholieke (franciscaanse) en de Armeens-apostolische kerk, terwijl de Koptische, Ethiopische en Syrisch-orthodoxe gemeenschappen ook kapellen bezitten, onder de status quo van 1852. De deuren worden elke ochtend geopend door moslimfamilies die de sleutels al eeuwenlang bewaren.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'nl', 'De Kerk van Alle Naties, ook bekend als de Basiliek van de Doodsangst, is een rooms-katholieke kerk bij Getsemane op de Olijfberg in Jeruzalem. Zij omsluit het stuk rots dat volgens de traditie wordt aangewezen als de plaats waar Jezus in doodsangst bad in de nacht vóór zijn kruisiging.', 'De huidige basiliek werd tussen 1919 en 1924 gebouwd op de funderingen van eerdere Byzantijnse en kruisvaarderskerken die tijdens de bouw werden blootgelegd. Zij kreeg de naam Kerk van Alle Naties omdat giften uit vele landen de bouw bekostigden; hun wapenschilden zijn in het plafond aangebracht.', 'De basiliek wordt verzorgd door de Franciscaanse Custodie van het Heilige Land, die de plaats en de aangrenzende Hof van Getsemane met haar eeuwenoude olijfbomen onderhoudt. Zij blijft een levendige gebedsplaats en een belangrijke halte voor pelgrims die de Olijfberg bezoeken.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'nl', 'De Kerk van Maria Magdalena is een Russisch-orthodoxe kerk op de westelijke helling van de Olijfberg in Jeruzalem, nabij de Hof van Getsemane. Zij is alom bekend om haar zeven vergulde uivormige koepels, een kenmerkend baken aan de horizon van Jeruzalem.', 'De kerk werd tussen 1886 en 1888 gebouwd door tsaar Alexander III van Rusland ter nagedachtenis aan zijn moeder, keizerin Maria Alexandrovna. Zij werd gewijd aan Maria Magdalena, de heilige naar wie de keizerin was vernoemd, en weerspiegelt de Russische aanwezigheid in het Heilige Land aan het eind van de negentiende eeuw.', 'De kerk behoort tot een klooster van orthodoxe nonnen en vormt een levende monastieke gemeenschap die bezoekers en pelgrims verwelkomt. Zij ligt in de omgeving van Getsemane op de hellingen van de Olijfberg.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'nl', 'Dominus Flevit, wat in het Latijn "de Heer weende" betekent, is een rooms-katholieke kapel op de westelijke helling van de Olijfberg in Jeruzalem. Zij markeert de plaats waar Jezus volgens het Evangelie van Lucas weende toen hij naar Jeruzalem keek en zijn verwoesting voorspelde.', 'De huidige kapel werd in 1955 gebouwd op de plek van eerdere religieuze gebouwen, waaronder de resten van een kerk uit de Byzantijnse tijd. Opgravingen op het terrein legden ook oude graven en ossuaria bloot, wat getuigt van het langdurige gebruik van de helling als begraafplaats.', 'Dominus Flevit wordt onderhouden door de Franciscaanse Custodie van het Heilige Land als onderdeel van haar netwerk van heiligdommen in en rond Jeruzalem. Het is een veelbezochte halte voor pelgrims die de Olijfberg afdalen naar Getsemane.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'nl', 'De Sint-Annakerk is een rooms-katholieke kerk in de oude stad van Jeruzalem, in de moslimwijk naast de Vijvers van Bethesda. Zij staat boven een plaats die volgens de traditie wordt vereerd als het huis van Anna en Joachim en de geboorteplaats van de Maagd Maria.', 'De kerk werd in de twaalfde eeuw gebouwd tijdens het kruisvaarderskoninkrijk Jeruzalem. Na de verovering van de stad door Saladin in 1187 werd zij omgevormd tot een islamitische school, en in de negentiende eeuw schonken de Ottomaanse autoriteiten haar aan Frankrijk, wiens custodes het gebouw restaureerden.', 'De kerk en haar terrein zijn toevertrouwd aan de Missionarissen van Afrika, algemeen bekend als de Witte Paters, die de plaats verzorgen en pelgrims verwelkomen. Zij blijft een levendige plaats van gebed en studie binnen de oude stad.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'nl', 'De Pater Noster-kerk is een rooms-katholieke kerk en karmelietenklooster op de Olijfberg in Jeruzalem. Zij staat op een plaats die volgens de traditie in verband wordt gebracht met Jezus die zijn leerlingen het Onzevader leerde, in het Latijn bekend als de Pater Noster.', 'De plaats bewaart de herinnering aan de Byzantijnse Eleona-kerk, in de vierde eeuw tijdens de regering van Constantijn gebouwd boven een grot op de Olijfberg. Na eeuwen van verval werd hier in de negentiende eeuw een Frans klooster gesticht, en de bouw van kerkgebouwen werd tot in de twintigste eeuw voortgezet.', 'De plaats wordt verzorgd door een gemeenschap van karmelietessen, die het klooster, de kerk en de kloostergang onderhouden. Het is een vaste halte voor pelgrims en bezoekers die de Olijfberg verkennen.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'nl', 'De Kerk van het Bezoek van Maria is een rooms-katholieke kerk in het dorp Ein Karem, aan de westelijke rand van Jeruzalem. Zij markeert de traditionele plaats waar Maria haar bloedverwante Elisabet bezocht en, volgens het Evangelie van Lucas, de lofzang uitsprak die bekendstaat als het Magnificat. De plaats wordt verzorgd door de franciscanen en is een veelbezochte bestemming voor pelgrims naar het Heilige Land.', 'De christelijke traditie vereenzelvigt Ein Karem met het thuisdorp van Zacharias en Elisabet en met het toneel van het Bezoek van Maria zoals beschreven in het Evangelie van Lucas. Op de plaats stond een kerk in de Byzantijnse en de kruisvaarderstijd, en het huidige gebouw met twee niveaus bewaart elementen van deze eerdere bouwwerken. De huidige kerk kwam in de eerste helft van de twintigste eeuw tot stand onder de Franciscaanse Custodie van het Heilige Land.', 'De plaats is eigendom van en wordt onderhouden door de Franciscaanse Custodie van het Heilige Land, die talrijke heiligdommen in de regio verzorgt. Zij blijft een levendige gebedsplaats en een vaste halte op pelgrimsroutes door Ein Karem, waar ook andere kerken staan die verbonden zijn met de geboorte van Johannes de Doper.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'nl', 'De Kerk van de Zaligsprekingen is een rooms-katholieke kerk op een heuvel boven de noordwestelijke oever van het Meer van Galilea. Zij markeert de traditionele plaats van de Bergrede en ontleent haar naam aan de Zaligsprekingen, de zaligheden waarmee de rede in het Evangelie van Matteüs opent. De ligging biedt een weids uitzicht over het meer en de omliggende dorpen.', 'De traditie van een heuvel bij Kafarnaüm als plaats van de Bergrede is oud, en er zijn eerdere resten opgemerkt in de omgeving van het lager gelegen Tabgha. De huidige kerk werd in 1938 gebouwd en ontworpen door de Italiaanse architect Antonio Barluzzi. De bouw ervan werd deels gefinancierd vanuit Italië.', 'De kerk en haar terrein worden verzorgd door de Franciscaanse Missiezusters van het Heilig Hart. De plaats fungeert zowel als plaats van eredienst als als veelbezochte pelgrimsbestemming in Galilea.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'nl', 'De Kerk van de Broodvermenigvuldiging is een rooms-katholieke kerk in Tabgha, aan de noordwestelijke oever van het Meer van Galilea. Zij herdenkt het evangelieverhaal van de vermenigvuldiging van de broden en de vissen, waarmee een menigte werd gevoed. De kerk staat bekend om haar vroegchristelijke mozaïekvloeren.', 'Tabgha werd in de Byzantijnse tijd vereerd als de plaats van het wonder, en een kleine kapel uit de vierde eeuw werd later in de vijfde eeuw vervangen door een grotere kerk. Deze vroege gebouwen raakten in verval, en hun resten werden in de moderne tijd herontdekt en opgegraven. De huidige kerk, gebouwd in de twintigste eeuw, geeft de plattegrond van de Byzantijnse basiliek weer.', 'De kerk wordt bediend door Duitse benedictijner monniken die verbonden zijn aan de Dormitio-abdij in Jeruzalem. Zij blijft een levende monastieke en pelgrimsplaats; een brand beschadigde in 2015 delen van het complex, waarna het werd hersteld.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'nl', 'De Kerk van het Primaat van Sint-Petrus is een kleine rooms-katholieke kapel in Tabgha, aan de oever van het Meer van Galilea. Zij herdenkt een verschijning van Jezus aan zijn leerlingen na de verrijzenis, beschreven in het Evangelie van Johannes, en de verlening van het primaat aan Petrus. De kapel staat pal aan het water.', 'De plaats verwijst naar het verhaal in Johannes 21, waarin de verrezen Jezus aan de leerlingen verschijnt bij het meer, een maaltijd van brood en vis met hen deelt en Petrus driemaal opdraagt zijn kudde te weiden. Hier stond in eerdere eeuwen een kerk die met deze traditie verbonden was, en in de nabijheid resten er sporen van vroegere bouwwerken. De huidige kapel werd in 1933 gebouwd.', 'De kapel wordt onderhouden door de Franciscaanse Custodie van het Heilige Land. Het is een veelbezochte halte voor pelgrims die de plaatsen rond de noordelijke oever van het Meer van Galilea bezoeken.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'nl', 'De Kerk van de Gedaanteverandering is een rooms-katholieke basiliek op de top van de berg Tabor, die oprijst boven de Jizreëlvallei in Neder-Galilea. Zij herdenkt de gedaanteverandering van Jezus, toen hij volgens de evangeliën van gedaante veranderd werd gezien in het bijzijn van Mozes en Elia. Elders op de berg staat ook een Grieks-orthodoxe kerk.', 'De berg Tabor wordt sinds de Byzantijnse tijd geëerd als de traditionele plaats van de gedaanteverandering, en er werden hier in de Byzantijnse en de kruisvaarderstijd kerken gebouwd. Deze bouwwerken raakten later in verval, en hun funderingen blijven op de top bewaard. De huidige basiliek werd in 1924 voltooid.', 'De basiliek en haar terrein worden verzorgd door de Franciscaanse Custodie van het Heilige Land. De berg blijft een pelgrimsbestemming, en de top wordt gedeeld met een Grieks-orthodox klooster en een kerk.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'nl', 'De franciscaanse Bruiloftskerk staat in Kafr Kanna, de plaats die algemeen wordt vereenzelvigd met het Kana van Galilea uit de evangeliën, ten noorden van Nazareth. Zij herdenkt het bruiloftsfeest waarop Jezus volgens het Evangelie van Johannes water in wijn veranderde, beschreven als het eerste van zijn tekenen. De plaats trekt pelgrims, en in het bijzonder gehuwde paren, die komen om hun geloften te vieren en te hernieuwen.', 'Het Evangelie van Johannes (hoofdstuk 2) plaatst Jezus, zijn moeder en zijn leerlingen op een bruiloft in Kana, waar de gastheer geen wijn meer had en Jezus zes stenen kruiken met water liet vullen die wijn werden. Een kerkelijke traditie ter ere van het wonder ontwikkelde zich in de loop der eeuwen te Kafr Kanna, en op of nabij de huidige plaats stonden eerdere gebedshuizen. De huidige franciscaanse kerk werd tussen 1879 en 1905 gebouwd.', 'De Bruiloftskerk wordt verzorgd door de franciscaner broeders van de Custodie van het Heilige Land, die haar onderhouden als plaats van eredienst en bedevaart. Een afzonderlijke Grieks-orthodoxe kerk in Kafr Kanna bewaart de traditie van het wonder in de nabijheid eveneens.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'nl', 'Kafarnaüm, aan de noordoever van het Meer van Galilea, is de plaats aan het meer die de evangeliën beschrijven als een centrum van Jezus'' bediening in Galilea. De archeologische site bewaart de resten die worden vereerd als het huis van de apostel Petrus en een oude synagoge. Het is een van de belangrijkste nieuwtestamentische plaatsen in de regio.', 'De evangeliën stellen Kafarnaüm voor als de plaats waar Jezus onderwees, leerlingen riep en genas, en zij verbinden de plaats met Petrus en andere volgelingen. Vanaf de eerste eeuwen werd een huis op de plek door christenen vereerd en later omsloten door een achthoekige kerk. De plaats was eeuwenlang bewoond voordat zij in verval raakte en de ruïnes achterliet die door moderne archeologen zijn bestudeerd.', 'De plaats is in bezit van en wordt verzorgd door de Franciscaanse Custodie van het Heilige Land, die toezicht houdt op de kerk, de opgravingen en de toegang voor pelgrims en bezoekers. Aan de oostelijke rand van het gebied staan een afzonderlijke Grieks-orthodoxe kerk en een klooster.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'nl', 'De Kapel van het Herdersveld staat in Beit Sahour, ten oosten van Bethlehem, op de plaats die volgens de traditie wordt vereenzelvigd met de velden van de herders in het kerstverhaal. Volgens het Evangelie van Lucas kondigden engelen daar aan herders, die ''s nachts hun kudden hoedden, de geboorte van Jezus aan. De kapel en het omliggende terrein zijn een plaats van gebed en bedevaart, vooral met Kerstmis.', 'Het Evangelie van Lucas (hoofdstuk 2) beschrijft herders bij Bethlehem aan wie de geboorte van de Verlosser werd verkondigd en die het kind gingen opzoeken. De christelijke verering van herdersvelden bij Beit Sahour is zeer oud, en in het gebied zijn resten van eerdere kerken en monastieke bouwwerken gevonden. De huidige franciscaanse kapel werd in 1953 gebouwd.', 'De kapel en haar veld worden verzorgd door de Franciscaanse Custodie van het Heilige Land. Een afzonderlijk Grieks-orthodox Herdersveld, met een eigen kerk en oude resten, ligt in de nabijheid in hetzelfde gebied van Beit Sahour.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'nl', 'De Melkgrot is een kapel die is gebouwd rond een zachte, witte krijtgrot in Bethlehem, op korte loopafstand van de Geboortekerk. De traditie brengt de grot in verband met de Heilige Familie en verbindt haar met de tijd vóór of tijdens de vlucht naar Egypte. Het is een stille plaats van gebed, vooral bezocht door moeders en door paren die hopen op kinderen.', 'De plaatselijke traditie houdt in dat de Heilige Familie in deze grot schuilde en dat de rots ervan wit werd, wat de naam en de devoties rond melk en moederschap deed ontstaan. De christelijke verering van de plaats is over vele eeuwen gedocumenteerd. De grot staat al lang onder franciscaanse zorg, en in de moderne tijd werd naast het oudere heiligdom een nieuwere kapel toegevoegd.', 'De Melkgrot wordt verzorgd door de Franciscaanse Custodie van het Heilige Land, die haar onderhoudt als plaats van gebed en pelgrims uit vele landen ontvangt. Zij blijft een brandpunt van persoonlijke devotie, in het bijzonder voor wie bidt om moederschap en gezin.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
