INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'nl', 'Restauratie', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'nl', 'Dit project richt zich op de dringende restauratiebehoeften van de basiliek, waaronder structurele reparaties, reiniging van de gevel en behoud van originele architectonische elementen. De werkzaamheden zorgen ervoor dat het gebouw veilig en toegankelijk blijft voor toekomstige generaties.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'nl', 'Restauratie van het middenschip en de gevel van de Basiliek van de Aankondiging.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'nl', 'Restauratie van de basiliek – fase 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'nl', 'Documentatie', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'nl', 'Een uitgebreid initiatief om christelijke erfgoedlocaties, artefacten en manuscripten in Israël en de omliggende regio’s te fotograferen, te scannen en te documenteren. Dit digitale archief bewaart onschatbare historische gegevens voor onderzoekers en toekomstige generaties.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'nl', 'Digitale documentatie van christelijke erfgoedlocaties in het hele Heilige Land.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'nl', 'Documentatie van het erfgoed van het Heilige Land', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'pl', 'Bazylika Zwiastowania to kościół katolicki w Nazarecie, w Izraelu. Jest jednym z największych kościołów na Bliskim Wschodzie i wyznacza tradycyjne miejsce, w którym archanioł Gabriel zwiastował Maryi, że pocznie i porodzi Jezusa.', 'Obecna bazylika została zbudowana w 1969 roku według projektu włoskiego architekta Giovanniego Muzio. Wznosi się nad ruinami wcześniejszych kościołów bizantyjskich i krzyżowieckich. Miejsce to jest celem chrześcijańskich pielgrzymek od czasów starożytnych.', 'Kościół służy miejscowej wspólnocie katolickiej w Nazarecie i przyjmuje pielgrzymów z całego świata. Regularne msze odprawiane są w wielu językach.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'pl', 'Bazylika Narodzenia Pańskiego w Betlejem wznosi się nad grotą, którą tradycja chrześcijańska czci od II wieku jako miejsce narodzin Jezusa. Jest to jeden z najstarszych nieprzerwanie użytkowanych kościołów na świecie oraz obiekt z Listy Światowego Dziedzictwa UNESCO.', 'Pierwszą bazylikę wzniesiono z polecenia cesarza Konstantyna i jego matki Heleny około 327 roku n.e. Po zniszczeniach w VI wieku cesarz Justynian odbudował ją na większą skalę, a znaczna część dzisiejszego kościoła pochodzi z tej przebudowy. Wewnątrz zachowały się mozaiki i malowane kolumny z okresu wypraw krzyżowych.', 'Kościołem opiekują się wspólnie wspólnoty greckoprawosławna, rzymskokatolicka (franciszkańska) i ormiańsko-apostolska, zgodnie z historycznym porozumieniem status quo. Miejscowe chrześcijańskie rodziny z Betlejem modlą się tu wraz z pielgrzymami z całego świata, zwłaszcza w okresie Bożego Narodzenia.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'pl', 'Bazylika Grobu Świętego w Starym Mieście w Jerozolimie mieści dwa najświętsze miejsca chrześcijaństwa: Golgotę, gdzie ukrzyżowano Jezusa, oraz grób, w którym – według tradycji – został złożony i zmartwychwstał.', 'Cesarz Konstantyn wzniósł tu pierwszy kościół w IV wieku; został on poświęcony w 335 roku n.e. Zniszczony w 1009 roku, odbudowany w XI wieku, a krzyżowcy nadali mu w dużej mierze obecny kształt w XII wieku. Edikula nad grobem została odrestaurowana w latach 2016–2017.', 'Opiekę nad kościołem sprawują wspólnie Kościoły greckoprawosławny, rzymskokatolicki (franciszkański) i ormiańsko-apostolski, a wspólnoty koptyjska, etiopska i syryjska prawosławna posiadają tu również własne kaplice, zgodnie ze status quo z 1852 roku. Jego drzwi każdego ranka otwierają muzułmańskie rodziny, które od wieków strzegą kluczy.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'pl', 'Kościół Wszystkich Narodów, znany także jako Bazylika Konania, to kościół rzymskokatolicki w Getsemani na Górze Oliwnej w Jerozolimie. Mieści fragment skały, który tradycja wskazuje jako miejsce, gdzie Jezus modlił się w udręce w noc poprzedzającą ukrzyżowanie.', 'Obecną bazylikę wzniesiono w latach 1919–1924 na fundamentach wcześniejszych kościołów bizantyjskiego i krzyżowieckiego, odsłoniętych podczas budowy. Nazwę Kościoła Wszystkich Narodów zawdzięcza temu, że jej budowę sfinansowały datki z wielu krajów, których herby umieszczono w sklepieniu.', 'Bazyliką opiekuje się franciszkańska Kustodia Ziemi Świętej, która utrzymuje to miejsce oraz sąsiedni Ogród Getsemani z jego starymi drzewami oliwnymi. Pozostaje czynnym miejscem modlitwy i ważnym przystankiem dla pielgrzymów odwiedzających Górę Oliwną.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'pl', 'Cerkiew św. Marii Magdaleny to rosyjska cerkiew prawosławna na zachodnim stoku Góry Oliwnej w Jerozolimie, w pobliżu Ogrodu Getsemani. Jest powszechnie rozpoznawalna dzięki siedmiu złoconym cebulastym kopułom, charakterystycznemu elementowi panoramy Jerozolimy.', 'Cerkiew zbudował w latach 1886–1888 car Aleksander III Rosyjski ku pamięci swojej matki, cesarzowej Marii Aleksandrowny. Poświęcono ją Marii Magdalenie, świętej, od której imię otrzymała cesarzowa, i odzwierciedla ona rosyjską obecność w Ziemi Świętej pod koniec XIX wieku.', 'Cerkiew należy do klasztoru mniszek prawosławnych i pozostaje czynną wspólnotą monastyczną, przyjmującą odwiedzających i pielgrzymów. Wznosi się w otoczeniu Getsemani, na stokach Góry Oliwnej.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'pl', 'Dominus Flevit, co po łacinie znaczy „Pan zapłakał”, to rzymskokatolicka kaplica na zachodnim stoku Góry Oliwnej w Jerozolimie. Upamiętnia miejsce, w którym według Ewangelii Łukasza Jezus zapłakał, spoglądając na Jerozolimę, i zapowiedział jej zniszczenie.', 'Obecną kaplicę zbudowano w 1955 roku na miejscu wcześniejszych budowli sakralnych, w tym pozostałości kościoła z epoki bizantyjskiej. Wykopaliska na terenie odsłoniły również dawne groby i ossuaria, świadczące o długim użytkowaniu stoku jako miejsca pochówku.', 'Dominus Flevit znajduje się pod opieką franciszkańskiej Kustodii Ziemi Świętej, w ramach jej sieci sanktuariów w Jerozolimie i okolicach. To częsty przystanek dla pielgrzymów schodzących z Góry Oliwnej ku Getsemani.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'pl', 'Kościół św. Anny to kościół rzymskokatolicki w Starym Mieście w Jerozolimie, w dzielnicy muzułmańskiej, obok sadzawek Betesda. Wznosi się nad miejscem czczonym przez tradycję jako dom Anny i Joachima oraz miejsce narodzin Maryi Panny.', 'Kościół wzniesiono w XII wieku, w czasach krzyżowego Królestwa Jerozolimskiego. Po zdobyciu miasta przez Saladyna w 1187 roku zamieniono go w szkołę islamską, a w XIX wieku władze osmańskie przekazały go Francji, której zarządcy odrestaurowali budowlę.', 'Kościół i jego teren powierzono Misjonarzom Afryki, powszechnie znanym jako Ojcowie Biali, którzy dbają o to miejsce i przyjmują pielgrzymów. Pozostaje czynnym miejscem modlitwy i studium w obrębie Starego Miasta.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'pl', 'Kościół Pater Noster to kościół rzymskokatolicki i klasztor karmelitanek na Górze Oliwnej w Jerozolimie. Wznosi się w miejscu wiązanym przez tradycję z nauczaniem przez Jezusa swoich uczniów Modlitwy Pańskiej, znanej po łacinie jako Pater Noster.', 'Miejsce to zachowuje pamięć bizantyjskiego kościoła Eleona, wzniesionego w IV wieku nad grotą na Górze Oliwnej za panowania Konstantyna. Po wiekach ruiny w XIX wieku założono tu francuski klasztor, a budowę obiektów kościelnych kontynuowano w XX wieku.', 'Miejscem opiekuje się wspólnota sióstr karmelitanek, które utrzymują klasztor, kościół i krużganek. To stały przystanek dla pielgrzymów i zwiedzających poznających Górę Oliwną.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'pl', 'Kościół Nawiedzenia to kościół rzymskokatolicki we wsi Ein Karem, na zachodnim krańcu Jerozolimy. Upamiętnia tradycyjne miejsce, w którym Maryja odwiedziła swoją krewną Elżbietę i według Ewangelii Łukasza wypowiedziała kantyk znany jako Magnificat. Miejscem opiekują się franciszkanie i jest ono chętnie odwiedzanym celem pielgrzymów do Ziemi Świętej.', 'Tradycja chrześcijańska utożsamia Ein Karem z rodzinną wsią Zachariasza i Elżbiety oraz miejscem Nawiedzenia opisanego w Ewangelii Łukasza. W okresach bizantyjskim i krzyżowieckim stał tu kościół, a obecny dwupoziomowy budynek zachowuje elementy tych wcześniejszych budowli. Obecny kościół rozbudowano w pierwszej połowie XX wieku pod franciszkańską Kustodią Ziemi Świętej.', 'Miejsce jest własnością franciszkańskiej Kustodii Ziemi Świętej i przez nią utrzymywane, a opiekuje się ona licznymi sanktuariami w całym regionie. Pozostaje czynnym miejscem modlitwy i stałym przystankiem na szlakach pielgrzymkowych przez Ein Karem, w którym znajdują się także inne kościoły związane z narodzinami Jana Chrzciciela.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'pl', 'Kościół Błogosławieństw to kościół rzymskokatolicki na wzgórzu nad północno-zachodnim brzegiem Jeziora Galilejskiego. Upamiętnia tradycyjne miejsce Kazania na Górze i bierze nazwę od Błogosławieństw, błogosławieństw otwierających kazanie w Ewangelii Mateusza. Miejsce oferuje rozległy widok na jezioro i okoliczne wioski.', 'Tradycja wskazująca wzgórze w pobliżu Kafarnaum jako miejsce Kazania na Górze jest dawna, a w sąsiedztwie położonej niżej Tabghy odnotowano wcześniejsze pozostałości. Obecny kościół zbudowano w 1938 roku według projektu włoskiego architekta Antonia Barluzziego. Jego budowę częściowo wsparło finansowanie z Włoch.', 'Kościołem i jego terenem opiekują się Franciszkańskie Siostry Misjonarki Najświętszego Serca. Miejsce pełni funkcję zarówno miejsca kultu, jak i chętnie odwiedzanego celu pielgrzymkowego w Galilei.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'pl', 'Kościół Rozmnożenia Chleba to kościół rzymskokatolicki w Tabgha, nad północno-zachodnim brzegiem Jeziora Galilejskiego. Upamiętnia ewangeliczny opis rozmnożenia chleba i ryb, którymi nakarmiono tłum. Kościół słynie ze swoich wczesnochrześcijańskich posadzek mozaikowych.', 'Tabghę czczono w okresie bizantyjskim jako miejsce cudu, a niewielką kaplicę z IV wieku zastąpiono później większym kościołem w V wieku. Te wczesne budowle popadły w ruinę, a ich pozostałości odkryto na nowo i przebadano w czasach nowożytnych. Obecny kościół, zbudowany w XX wieku, odtwarza plan bazyliki bizantyjskiej.', 'Kościół obsługują niemieccy mnisi benedyktyni związani z opactwem Zaśnięcia NMP w Jerozolimie. Pozostaje czynnym miejscem monastycznym i pielgrzymkowym; w 2015 roku pożar uszkodził części kompleksu, po czym zostały one naprawione.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'pl', 'Kościół Prymatu św. Piotra to niewielka rzymskokatolicka kaplica w Tabgha, nad brzegiem Jeziora Galilejskiego. Upamiętnia ukazanie się Jezusa uczniom po zmartwychwstaniu, opisane w Ewangelii Jana, oraz nadanie prymatu Piotrowi. Kaplica stoi tuż nad wodą.', 'Miejsce to przywołuje opis z Ewangelii Jana (rozdział 21), w którym zmartwychwstały Jezus ukazuje się uczniom nad jeziorem, dzieli z nimi posiłek z chleba i ryby oraz trzykrotnie poleca Piotrowi paść swoją owczarnię. W minionych wiekach stał tu kościół związany z tą tradycją, a w pobliżu zachowały się ślady wcześniejszych budowli. Obecną kaplicę zbudowano w 1933 roku.', 'Kaplicą opiekuje się franciszkańska Kustodia Ziemi Świętej. To częsty przystanek dla pielgrzymów odwiedzających miejsca wokół północnego brzegu Jeziora Galilejskiego.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'pl', 'Kościół Przemienienia Pańskiego to rzymskokatolicka bazylika na szczycie góry Tabor, wznoszącej się nad Doliną Jizreel w Dolnej Galilei. Upamiętnia Przemienienie Jezusa, gdy według Ewangelii ukazał się przemieniony w obecności Mojżesza i Eliasza. W innym miejscu na górze wznosi się również cerkiew greckoprawosławna.', 'Górę Tabor czczono od okresu bizantyjskiego jako tradycyjne miejsce Przemienienia, a w czasach bizantyjskich i krzyżowieckich wznoszono tu kościoły. Budowle te później popadły w ruinę, a ich fundamenty pozostają na szczycie. Obecną bazylikę ukończono w 1924 roku.', 'Bazyliką i jej terenem opiekuje się franciszkańska Kustodia Ziemi Świętej. Góra pozostaje celem pielgrzymek, a szczyt jest dzielony z greckoprawosławnym monasterem i cerkwią.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'pl', 'Franciszkański Kościół Wesela wznosi się w Kafr Kanna, miejscowości powszechnie utożsamianej z Kaną Galilejską z Ewangelii, na północ od Nazaretu. Upamiętnia ucztę weselną, na której według Ewangelii Jana Jezus przemienił wodę w wino, opisane jako pierwszy z jego znaków. Miejsce przyciąga pielgrzymów, a zwłaszcza małżeństwa, które przybywają, by uczcić i odnowić swoje przyrzeczenia.', 'Ewangelia Jana (rozdział 2) umieszcza Jezusa, jego matkę i uczniów na weselu w Kanie, gdzie gospodarzowi zabrakło wina, a Jezus polecił napełnić wodą sześć kamiennych stągwi, która stała się winem. Na przestrzeni wieków w Kafr Kanna rozwinęła się tradycja kościelna czcząca cud, a na obecnym miejscu lub w jego pobliżu stały wcześniejsze miejsca kultu. Obecny kościół franciszkański zbudowano w latach 1879–1905.', 'Kościołem Wesela opiekują się bracia franciszkanie z Kustodii Ziemi Świętej, którzy utrzymują go jako miejsce kultu i pielgrzymek. Odrębna cerkiew greckoprawosławna w Kafr Kanna również zachowuje w pobliżu tradycję cudu.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'pl', 'Kafarnaum, na północnym brzegu Jeziora Galilejskiego, to nadjeziorne miasteczko, które Ewangelie opisują jako ośrodek działalności Jezusa w Galilei. Stanowisko archeologiczne zachowuje pozostałości czczone jako dom apostoła Piotra oraz starożytną synagogę. To jedno z najważniejszych miejsc Nowego Testamentu w regionie.', 'Ewangelie przedstawiają Kafarnaum jako miejsce, gdzie Jezus nauczał, powoływał uczniów i uzdrawiał, oraz wiążą miasteczko z Piotrem i innymi naśladowcami. Od pierwszych wieków chrześcijanie czcili tu dom, który później objęto ośmioboczną świątynią. Miasteczko było zamieszkane przez stulecia, zanim podupadło, pozostawiając ruiny badane przez współczesnych archeologów.', 'Miejsce jest własnością franciszkańskiej Kustodii Ziemi Świętej i pozostaje pod jej opieką, sprawującej pieczę nad kościołem, wykopaliskami oraz dostępem dla pielgrzymów i zwiedzających. Na wschodnim skraju terenu stoją odrębna cerkiew i monaster greckoprawosławne.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'pl', 'Kaplica Pola Pasterzy wznosi się w Beit Sahour, na wschód od Betlejem, w miejscu utożsamianym przez tradycję z polami pasterzy z opowieści o Bożym Narodzeniu. Według Ewangelii Łukasza aniołowie ogłosili tam narodziny Jezusa pasterzom, którzy nocą strzegli swoich trzód. Kaplica i jej teren są miejscem modlitwy i pielgrzymek, zwłaszcza w okresie Bożego Narodzenia.', 'Ewangelia Łukasza (rozdział 2) opisuje pasterzy w pobliżu Betlejem, którym ogłoszono narodziny Zbawiciela i którzy wyruszyli, by odnaleźć dziecię. Chrześcijańska cześć dla pól pasterzy w pobliżu Beit Sahour jest bardzo dawna, a na tym terenie odnaleziono pozostałości wcześniejszych kościołów i budowli monastycznych. Obecną kaplicę franciszkańską zbudowano w 1953 roku.', 'Kaplicą i jej polem opiekuje się franciszkańska Kustodia Ziemi Świętej. W pobliżu, w tej samej okolicy Beit Sahour, znajduje się odrębne greckoprawosławne Pole Pasterzy z własną cerkwią i dawnymi pozostałościami.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'pl', 'Grota Mleczna to kaplica wzniesiona wokół groty z miękkiej białej kredy w Betlejem, w niewielkiej odległości od Bazyliki Narodzenia Pańskiego. Tradycja wiąże grotę ze Świętą Rodziną, łącząc ją z czasem przed ucieczką do Egiptu lub w jej trakcie. To ciche miejsce modlitwy, odwiedzane zwłaszcza przez matki oraz małżeństwa pragnące potomstwa.', 'Miejscowa tradycja głosi, że Święta Rodzina schroniła się w tej grocie, a jej skała zbielała, skąd wzięły się nazwa oraz nabożeństwa związane z mlekiem i macierzyństwem. Chrześcijańska cześć dla tego miejsca jest udokumentowana na przestrzeni wielu wieków. Grota od dawna pozostaje pod opieką franciszkanów, a w czasach nowożytnych obok dawnego sanktuarium dobudowano nowszą kaplicę.', 'Grotą Mleczną opiekuje się franciszkańska Kustodia Ziemi Świętej, która utrzymuje ją jako miejsce modlitwy i przyjmuje pielgrzymów z wielu krajów. Pozostaje ośrodkiem osobistej pobożności, w szczególności dla modlących się o macierzyństwo i rodzinę.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
