INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'ru', 'Реставрация', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'ru', 'Проект направлен на решение неотложных реставрационных задач базилики, включая ремонт конструкций, очистку фасада и сохранение подлинных архитектурных элементов. Работы обеспечат безопасность и доступность здания для будущих поколений.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'ru', 'Реставрация главного нефа и фасада Базилики Благовещения.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'ru', 'Реставрация базилики — этап 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'ru', 'Документирование', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'ru', 'Масштабная инициатива по фотографированию, сканированию и документированию объектов христианского наследия, артефактов и рукописей в Израиле и соседних регионах. Этот цифровой архив сохранит бесценные исторические свидетельства для исследователей и будущих поколений.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'ru', 'Цифровое документирование объектов христианского наследия по всей Святой земле.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'ru', 'Документирование наследия Святой земли', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'sr', 'Базилика Благовести је католичка црква у Назарету, у Израелу. То је једна од највећих цркава на Блиском истоку и обележава место које по предању означава где је арханђео Гаврило објавио Марији да ће родити Исуса.', 'Данашња базилика саграђена је 1969. године, по пројекту италијанског архитекте Ђованија Муција. Уздиже се над рушевинама ранијих византијских и крсташких цркава. Ово место је од давнина одредиште хришћанских ходочасника.', 'Црква служи локалној католичкој заједници у Назарету и дочекује ходочаснике из целог света. Мисе се редовно служе на више језика.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'sr', 'Црква Рождења Христовог у Витлејему уздиже се над пећином коју хришћанска традиција од 2. века поштује као место рођења Исуса. То је једна од најстаријих непрекидно коришћених цркава на свету и место Светске баштине УНЕСКО-а.', 'Прву базилику подигли су око 327. године цар Константин и његова мајка Јелена. Пошто је оштећена у 6. веку, цар Јустинијан обновио ју је у већем обиму, а велики део данашње цркве потиче из те обнове. Унутра су и данас сачувани мозаици и осликани стубови из доба крсташа.', 'Црквом заједнички управљају грчка православна, римокатоличка (фрањевачка) и јерменска апостолска заједница, у складу са историјским статусом кво. Локалне хришћанске породице из Витлејема се овде моле заједно са ходочасницима из целог света, нарочито о Божићу.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'sr', 'Црква Светог гроба у Старом граду Јерусалима садржи две најсветије светиње хришћанства: Голготу, где је Исус разапет, и гроб у коме је, по предању, сахрањен и васкрсао.', 'Цар Константин је овде у 4. веку саградио прву цркву; освештана је 335. године. Порушена је 1009. и обновљена у 11. веку, а крсташи су јој у 12. веку дали највећи део данашњег изгледа. Едикула над гробом обновљена је 2016–2017. године.', 'О цркви заједнички брину грчка православна, римокатоличка (фрањевачка) и јерменска апостолска црква, док своје капеле имају и коптска, етиопска и сиријска православна заједница, у складу са статусом кво из 1852. године. Њена врата свако јутро отварају муслиманске породице које вековима чувају кључеве.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'sr', 'Црква свих народа, позната и као Базилика самртне борбе, римокатоличка је црква у Гетсиманији на Маслинској гори у Јерусалиму. Она чува део стене који се по предању поистовећује са местом где се Исус у самртној борби молио у ноћи пре свог распећа.', 'Данашња базилика саграђена је између 1919. и 1924. године на темељима ранијих византијских и крсташких цркава откривених током градње. Названа је Црквом свих народа зато што су њену изградњу финансирали прилози из многих земаља, чији су грбови уграђени у таваницу.', 'О базилици се стара Фрањевачка кустодија Свете земље, која одржава ово место и суседни Гетсимански врт са његовим древним маслинама. Она остаје живо место молитве и важна станица за ходочаснике који посећују Маслинску гору.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'sr', 'Црква Марије Магдалене руска је православна црква на западној падини Маслинске горе у Јерусалиму, близу Гетсиманског врта. Надалеко је позната по седам позлаћених луковичастих купола, препознатљивом обележју јерусалимске силуете.', 'Цркву је између 1886. и 1888. године подигао руски цар Александар III у спомен на своју мајку, царицу Марију Александровну. Посвећена је Марији Магдалени, светитељки по којој је царица добила име, и одражава руско присуство у Светој земљи крајем деветнаестог века.', 'Црква припада манастиру православних монахиња и остаје жива монашка заједница која дочекује посетиоце и ходочаснике. Смештена је у окружењу Гетсиманије на падинама Маслинске горе.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'sr', 'Доминус Флевит, што на латинском значи „Господ заплака”, римокатоличка је капела на западној падини Маслинске горе у Јерусалиму. Она обележава место на коме је, према Јеванђељу по Луки, Исус заплакао гледајући ка Јерусалиму и прорекао његово разарање.', 'Данашња капела саграђена је 1955. године на месту ранијих верских грађевина, укључујући остатке цркве из византијског доба. Ископавања на имању открила су и древне гробнице и костурнице, које сведоче о дуготрајној употреби падине као гробља.', 'О Доминус Флевиту стара се Фрањевачка кустодија Свете земље као о делу своје мреже светилишта у Јерусалиму и око њега. То је честа станица ходочасника који силазе низ Маслинску гору ка Гетсиманији.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'sr', 'Црква свете Ане римокатоличка је црква у Старом граду Јерусалима, у Муслиманској четврти поред Витездиних рибњака. Стоји над местом које се по предању поштује као дом Ане и Јоакима и родно место Девице Марије.', 'Црква је саграђена у дванаестом веку у време крсташког Јерусалимског краљевства. Након што је Саладин 1187. године освојио град, претворена је у исламску школу, а у деветнаестом веку османске власти уступиле су је Француској, чији су је старатељи обновили.', 'Црква и њено имање поверени су Мисионарима Африке, општепознатим као Бели оци, који се старају о овом месту и дочекују ходочаснике. Она остаје живо место молитве и учења у Старом граду.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'sr', 'Црква Оченаша римокатоличка је црква и кармелићански манастир на Маслинској гори у Јерусалиму. Стоји на месту које предање повезује са тим да је Исус учио своје ученике молитви Оченаш, на латинском познатој као Патер ностер.', 'Ово место чува спомен на византијску цркву Елеона, подигнуту у четвртом веку над пећином на Маслинској гори за време Константинове владавине. После вековног пропадања, овде је у деветнаестом веку основан француски манастир, а изградња црквених грађевина настављена је у двадесети век.', 'О месту се стара заједница кармелићанских сестара, која одржава манастир, цркву и клаустар. То је редовна станица ходочасника и посетилаца који разгледају Маслинску гору.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'sr', 'Црква Похођења римокатоличка је црква у селу Ејн Карем, на западном ободу Јерусалима. Она обележава традиционално место на коме је Марија посетила своју рођаку Јелисавету и, према Јеванђељу по Луки, изговорила химну познату као Магнификат. О месту се старају фрањевци и оно је радо посећивано одредиште ходочасника у Свету земљу.', 'Хришћанско предање поистовећује Ејн Карем са родним селом Захарије и Јелисавете и позорницом Похођења описаног у Јеванђељу по Луки. Црква је на овом месту постојала у византијском и крсташком раздобљу, а данашња двоспратна грађевина чува елементе тих ранијих грађевина. Садашња црква изграђена је у првој половини двадесетог века под Фрањевачком кустодијом Свете земље.', 'Место је у власништву и на одржавању Фрањевачке кустодије Свете земље, која се стара о бројним светилиштима широм регије. Оно остаје живо место молитве и редовна станица на ходочасничким путевима кроз Ејн Карем, где се налазе и друге цркве повезане са рођењем Јована Крститеља.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'sr', 'Црква блаженстава римокатоличка је црква на падини изнад северозападне обале Галилејског језера. Она обележава традиционално место Беседе на гори и назив носи по блаженствима, благословима којима та беседа започиње у Јеванђељу по Матеју. Положај пружа широк поглед на језеро и околна села.', 'Предање о брду близу Кафарнаума као месту Беседе на гори је дуготрајно, а ранији остаци забележени су у околини Табге испод њега. Данашња црква саграђена је 1938. године по пројекту италијанског архитекте Антонија Барлуција. Њену изградњу делом су помогла средства из Италије.', 'О цркви и њеном имању старају се Фрањевачке мисионарке сестре Пресветог Срца. Место служи и као богослужбено место и као радо посећивано ходочасничко одредиште у Галилеји.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'sr', 'Црква умножења хлебова римокатоличка је црква у Табги, на северозападној обали Галилејског језера. Она спомиње јеванђељски догађај умножења хлебова и риба, којим је нахрањено мноштво народа. Црква је добро позната по својим ранохришћанским мозаичким подовима.', 'Табга је у византијском раздобљу поштована као место чуда, а малу капелу из четвртог века касније је у петом веку заменила већа црква. Те ране грађевине запустеле су, а њихови остаци поново су откривени и ископани у новије доба. Данашња црква, саграђена у двадесетом веку, репродукује основу византијске базилике.', 'Цркви служе немачки бенедиктински монаси повезани са опатијом Успења у Јерусалиму. Она остаје живо монашко и ходочасничко место; пожар је 2015. године оштетио делове комплекса, који је потом обновљен.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'sr', 'Црква Петровог првенства мала је римокатоличка капела у Табги, на обали Галилејског језера. Она спомиње Исусово јављање ученицима после васкрсења, описано у Јеванђељу по Јовану, и предавање првенства Петру. Капела стоји непосредно уз воду.', 'Место подсећа на догађај из Јована 21, у коме се васкрсли Исус јавља ученицима крај језера, дели с њима оброк хлеба и рибе и трипут налаже Петру да напаса његово стадо. Црква повезана с овим предањем постојала је овде у ранијим вековима, а трагови претходних грађевина сачувани су у близини. Данашња капела саграђена је 1933. године.', 'О капели се стара Фрањевачка кустодија Свете земље. То је честа станица ходочасника који посећују места око северне обале Галилејског језера.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'sr', 'Црква Преображења римокатоличка је базилика на врху Горе Тавор, која се уздиже над Језраелском долином у Доњој Галилеји. Она спомиње Исусово Преображење, када је, према јеванђељима, виђен преображен у присуству Мојсија и Илије. На другом делу горе стоји и грчка православна црква.', 'Гора Тавор поштована је од византијског раздобља као традиционално место Преображења, а цркве су овде подигнуте у византијско и крсташко доба. Те грађевине касније су запустеле, а њихови темељи остају на врху. Данашња базилика довршена је 1924. године.', 'О базилици и њеном имању стара се Фрањевачка кустодија Свете земље. Гора остаје ходочасничко одредиште, а врх дели са грчким православним манастиром и црквом.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'sr', 'Фрањевачка црква венчања налази се у Кафр Кани, граду који се надалеко поистовећује са јеванђељском Каном Галилејском, северно од Назарета. Она спомиње свадбену гозбу на којој је, према Јеванђељу по Јовану, Исус претворио воду у вино, што се описује као први од његових знакова. Место привлачи ходочаснике, а посебно венчане парове, који долазе да обележе и обнове своје завете.', 'Јеванђеље по Јовану (глава 2) смешта Исуса, његову мајку и његове ученике на свадбу у Кани, где је домаћину понестало вина, а Исус је наложио да се шест камених судова напуни водом која је постала вино. Црквено предање које поштује ово чудо у Кафр Кани развијало се вековима, а ранија богослужбена места стајала су на данашњем месту или у његовој близини. Садашња фрањевачка црква саграђена је између 1879. и 1905. године.', 'О Цркви венчања старају се фрањевачки редовници Кустодије Свете земље, који је одржавају као место богослужења и ходочашћа. Засебна грчка православна црква у Кафр Кани такође у близини чува предање о чуду.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'sr', 'Кафарнаум, на северној обали Галилејског језера, приобални је град који јеванђеља описују као средиште Исусовог деловања у Галилеји. Археолошко налазиште чува остатке поштоване као кућа апостола Петра и древну синагогу. То је једно од најважнијих новозаветних места у регији.', 'Јеванђеља приказују Кафарнаум као место где је Исус учио, позивао ученике и исцељивао, и повезују град са Петром и другим следбеницима. Од раних векова кућу на овом месту поштовали су хришћани, а касније је обухваћена осмоугаоном црквом. Град је био насељен вековима пре него што је опао, оставивши рушевине које проучавају савремени археолози.', 'Местом влада и о њему се стара Фрањевачка кустодија Свете земље, која надзире цркву, ископавања и приступ ходочасницима и посетиоцима. Засебна грчка православна црква и манастир стоје на источном ободу овог подручја.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'sr', 'Капела Пастирског поља налази се у Беит Сахуру, источно од Витлејема, на месту које се по предању поистовећује са пољима пастира из приче о Рождеству. Према Јеванђељу по Луки, тамо су анђели објавили рођење Исуса пастирима који су ноћу чували своја стада. Капела и њено окружење место су молитве и ходочашћа, нарочито о Божићу.', 'Јеванђеље по Луки (глава 2) описује пастире близу Витлејема којима је објављено рођење Спаситеља и који су пошли да пронађу дете. Хришћанско поштовање пастирских поља близу Беит Сахура веома је старо, а у том подручју пронађени су остаци ранијих цркава и монашких грађевина. Данашња фрањевачка капела саграђена је 1953. године.', 'О капели и њеном пољу стара се Фрањевачка кустодија Свете земље. Засебно грчко православно Пастирско поље, са сопственом црквом и древним остацима, налази се у близини, у истом делу Беит Сахура.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'sr', 'Млечна пећина капела је саграђена око пећине од меког белог кречњака у Витлејему, на кратком пешачком одстојању од Цркве Рождења. Предање повезује пећину са Светом породицом, доводећи је у везу са временом пре бекства у Египат или током њега. То је тихо место молитве, које нарочито посећују мајке и парови који се надају деци.', 'По месном предању, Света породица склонила се у ову пећину и њена стена постала је бела, одакле потичу назив и побожности повезане са млеком и материнством. Хришћанско поштовање овог места забележено је током многих векова. Пећина је одавно под старатељством фрањеваца, а у новије доба, поред старијег светилишта, дозидана је новија капела.', 'О Млечној пећини стара се Фрањевачка кустодија Свете земље, која је одржава као место молитве и прима ходочаснике из многих земаља. Она остаје жариште личне побожности, нарочито за оне који се моле за материнство и породицу.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
