INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'sv', 'Restaurering', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'sv', 'Detta projekt fokuserar på basilikans mest akuta restaureringsbehov, inklusive strukturella reparationer, rengöring av fasaden och bevarande av ursprungliga arkitektoniska element. Arbetet säkerställer att byggnaden förblir säker och tillgänglig för kommande generationer.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'sv', 'Restaurering av mittskeppet och fasaden på Bebådelsebasilikan.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'sv', 'Restaurering av basilikan – fas 1', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'sv', 'Dokumentation', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'sv', 'Ett omfattande initiativ för att fotografera, skanna och dokumentera kristna kulturarvsplatser, artefakter och manuskript i Israel och de omgivande regionerna. Detta digitala arkiv bevarar ovärderliga historiska uppgifter för forskare och kommande generationer.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'sv', 'Digital dokumentation av kristna kulturarvsplatser i hela Heliga landet.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'sv', 'Dokumentation av Heliga landets arv', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'tr', 'Müjde Bazilikası, İsrail''in Nasıra kentinde bir Katolik kilisesidir. Orta Doğu''nun en büyük kiliselerinden biridir ve geleneğe göre Başmelek Cebrail''in Meryem''e İsa''yı doğuracağını müjdelediği yeri işaret eder.', 'Bugünkü bazilika, İtalyan mimar Giovanni Muzio''nun tasarımıyla 1969 yılında inşa edilmiştir. Daha önceki Bizans ve Haçlı dönemi kiliselerinin kalıntıları üzerinde yükselir. Bu mekân, kadim zamanlardan beri bir Hristiyan hac merkezidir.', 'Kilise, Nasıra''daki yerel Katolik topluluğa hizmet eder ve dünyanın dört bir yanından hacıları ağırlar. Ayinler düzenli olarak birçok dilde yapılır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'tr', 'Beytüllahim''deki Doğuş Kilisesi, Hristiyan geleneğinin 2. yüzyıldan beri İsa''nın doğum yeri olarak andığı mağaranın üzerinde yükselir. Dünyada kesintisiz kullanılan en eski kiliselerden biri ve bir UNESCO Dünya Mirası alanıdır.', 'İlk bazilika, yaklaşık MS 327 yılında İmparator Konstantin ve annesi Helena tarafından yaptırılmıştır. 6. yüzyılda zarar gördükten sonra İmparator Justinianus onu daha büyük ölçekte yeniden inşa ettirmiş ve bugünkü kilisenin büyük bölümü bu yeniden inşadan kalmıştır. İçeride Haçlı dönemine ait mozaikler ve boyalı sütunlar hâlâ ayaktadır.', 'Kilise, tarihi Statüko düzenlemesi uyarınca Rum Ortodoks, Roma Katolik (Fransisken) ve Ermeni Apostolik topluluklarınca paylaşılır. Beytüllahim''in yerel Hristiyan aileleri, özellikle Noel''de dünyanın dört bir yanından gelen hacılarla birlikte burada ibadet eder.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'tr', 'Kudüs''ün Eski Şehri''ndeki Kutsal Kabir Kilisesi, Hristiyanlığın en kutsal iki yerini barındırır: İsa''nın çarmıha gerildiği Golgota ve geleneğe göre gömülüp yeniden dirildiği kabir.', 'İmparator Konstantin ilk kiliseyi burada 4. yüzyılda inşa ettirdi; MS 335''te ibadete açıldı. 1009''da yıkıldı ve 11. yüzyılda yeniden inşa edildi; Haçlılar 12. yüzyılda ona bugünkü görünümünün büyük bölümünü kazandırdı. Kabrin üzerindeki Edikül 2016–2017''de restore edildi.', 'Kilisenin bakımı, 1852 Statükosu uyarınca Rum Ortodoks, Roma Katolik (Fransisken) ve Ermeni Apostolik kiliselerince paylaşılır; Kıpti, Etiyopya ve Süryani Ortodoks topluluklarının da burada şapelleri vardır. Kapıları her sabah, anahtarları yüzyıllardır saklayan Müslüman aileler tarafından açılır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'tr', 'Istırap Bazilikası olarak da bilinen Tüm Milletler Kilisesi, Kudüs''teki Zeytin Dağı''nda, Getsemani''de bulunan bir Roma Katolik kilisesidir. Geleneğe göre İsa''nın çarmıha gerilmesinden önceki gece ıstırap içinde dua ettiği yer olarak tanımlanan ana kaya bölümünü barındırır.', 'Bugünkü bazilika, inşaat sırasında ortaya çıkarılan daha eski Bizans ve Haçlı dönemi kiliselerinin temelleri üzerine 1919 ile 1924 arasında yapıldı. Yapımı birçok ülkeden gelen bağışlarla finanse edildiği için Tüm Milletler Kilisesi olarak anılmaya başlandı ve bu ülkelerin armaları tavana işlenmiştir.', 'Bazilikaya, burayı ve bitişikteki kadim zeytin ağaçlarıyla Getsemani Bahçesi''ni bakımlı tutan Kutsal Toprakların Fransisken Kustodyası bakar. Burası hâlâ etkin bir dua yeri ve Zeytin Dağı''nı ziyaret eden hacılar için önemli bir durak olmayı sürdürür.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'tr', 'Mecdelli Meryem Kilisesi, Kudüs''teki Zeytin Dağı''nın batı yamacında, Getsemani Bahçesi yakınında bir Rus Ortodoks kilisesidir. Kudüs siluetinin belirgin bir simgesi olan yedi yaldızlı soğan kubbesiyle geniş çapta tanınır.', 'Kilise, Rus Çarı III. Aleksandr tarafından annesi İmparatoriçe Maria Aleksandrovna''nın anısına 1886 ile 1888 arasında yaptırıldı. İmparatoriçenin adını taşıdığı aziz olan Mecdelli Meryem''e adandı ve on dokuzuncu yüzyılın sonlarında Kutsal Topraklar''daki Rus varlığını yansıtır.', 'Kilise, Ortodoks rahibelerden oluşan bir manastıra aittir ve ziyaretçileri ve hacıları ağırlayan etkin bir manastır topluluğu olmayı sürdürür. Zeytin Dağı''nın yamaçlarında, Getsemani çevresinde yer alır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'tr', 'Latince "Rab ağladı" anlamına gelen Dominus Flevit, Kudüs''teki Zeytin Dağı''nın batı yamacında bir Roma Katolik şapelidir. Luka İncili''ne göre İsa''nın Kudüs''e bakarak ağladığı ve şehrin yıkımını önceden bildirdiği yeri işaret eder.', 'Bugünkü şapel, Bizans dönemine ait bir kilisenin kalıntıları da dahil olmak üzere daha eski dini yapıların bulunduğu yerde 1955''te inşa edildi. Arazide yapılan kazılar, yamacın uzun süre mezarlık olarak kullanıldığına tanıklık eden kadim mezarları ve kemik mahzenlerini de ortaya çıkardı.', 'Dominus Flevit''e, Kudüs ve çevresindeki kutsal mekânlar ağının bir parçası olarak Kutsal Toprakların Fransisken Kustodyası bakar. Zeytin Dağı''ndan Getsemani''ye inen hacılar için sık uğranan bir duraktır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'tr', 'Aziz Anna Kilisesi, Kudüs''ün Eski Şehri''nde, Müslüman Mahallesi''nde Bethesda Havuzları''nın yanında bir Roma Katolik kilisesidir. Geleneksel olarak Anna ile Yoahim''in evi ve Bakire Meryem''in doğum yeri olarak saygı gösterilen bir yerin üzerinde yükselir.', 'Kilise, Haçlı Kudüs Krallığı döneminde on ikinci yüzyılda inşa edildi. Selahaddin''in 1187''de şehri fethetmesinin ardından bir İslam medresesine dönüştürüldü ve on dokuzuncu yüzyılda Osmanlı yönetimi onu, yapıyı onaran görevlileriyle Fransa''ya devretti.', 'Kilise ve arazisi, yaygın olarak Beyaz Babalar diye bilinen Afrika Misyonerleri''ne emanet edilmiştir; onlar bu mekâna bakar ve hacıları ağırlar. Eski Şehir''de etkin bir dua ve ilim yeri olmayı sürdürür.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'tr', 'Pater Noster Kilisesi, Kudüs''teki Zeytin Dağı''nda bir Roma Katolik kilisesi ve Karmelit manastırıdır. Geleneksel olarak İsa''nın öğrencilerine Latincede Pater Noster diye bilinen Rab''bin Duası''nı öğretmesiyle ilişkilendirilen bir yerde yükselir.', 'Bu mekân, Konstantin''in hükümdarlığı sırasında dördüncü yüzyılda Zeytin Dağı''ndaki bir mağaranın üzerine inşa edilen Bizans dönemi Eleona Kilisesi''nin anısını korur. Yüzyıllar süren yıkımın ardından burada on dokuzuncu yüzyılda bir Fransız manastırı kuruldu ve kilise yapılarının inşası yirminci yüzyıla kadar sürdü.', 'Mekâna, manastırı, kiliseyi ve avluyu bakımlı tutan bir Karmelit rahibeler topluluğu bakar. Zeytin Dağı''nı gezen hacılar ve ziyaretçiler için düzenli bir duraktır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'tr', 'Ziyaret Kilisesi, Kudüs''ün batı kenarındaki Ein Karem köyünde bir Roma Katolik kilisesidir. Meryem''in akrabası Elizabet''i ziyaret ettiği ve Luka İncili''ne göre Magnificat diye bilinen ilahiyi söylediği geleneksel yeri işaret eder. Mekâna Fransiskenler bakar ve Kutsal Topraklar''a gelen hacılar için çok ziyaret edilen bir hedeftir.', 'Hristiyan geleneği Ein Karem''i Zekeriya ile Elizabet''in memleket köyü ve Luka İncili''nde anlatılan Ziyaret''in geçtiği yer olarak tanımlar. Bizans ve Haçlı dönemlerinde bu yerde bir kilise bulunuyordu ve bugünkü iki katlı yapı, bu daha eski yapılara ait öğeleri korur. Şimdiki kilise, yirminci yüzyılın ilk yarısında Kutsal Toprakların Fransisken Kustodyası altında geliştirildi.', 'Mekân, bölge genelindeki pek çok kutsal yere bakan Kutsal Toprakların Fransisken Kustodyası''na aittir ve onun tarafından bakımlı tutulur. Etkin bir dua yeri ve Ein Karem içinden geçen hac güzergâhlarında düzenli bir durak olmayı sürdürür; Ein Karem''de ayrıca Vaftizci Yahya''nın doğumuyla bağlantılı başka kiliseler de vardır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'tr', 'Ne Mutlular Kilisesi, Celile Gölü''nün kuzeybatı kıyısının üzerindeki bir yamaçta bulunan bir Roma Katolik kilisesidir. Dağdaki Vaaz''ın geleneksel yerini işaret eder ve adını, Matta İncili''nde vaazı açan kutsamalar olan "ne mutlular" sözlerinden alır. Konumu, göl ve çevresindeki köyler üzerinde geniş bir manzara sunar.', 'Kefernahum yakınlarındaki bir tepenin Dağdaki Vaaz''ın yeri olduğu geleneği eskidir ve aşağıda, Tabgha çevresinde daha eski kalıntılar kaydedilmiştir. Bugünkü kilise 1938''de inşa edildi ve İtalyan mimar Antonio Barluzzi tarafından tasarlandı. Yapımı kısmen İtalya''dan gelen fonlarla desteklendi.', 'Kiliseye ve arazisine Kutsal Kalp Fransisken Misyoner Rahibeleri bakar. Mekân hem bir ibadet yeri hem de Celile''de çok ziyaret edilen bir hac hedefi olarak işlev görür.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'tr', 'Ekmeklerin Çoğaltılması Kilisesi, Celile Gölü''nün kuzeybatı kıyısındaki Tabgha''da bir Roma Katolik kilisesidir. İncil''de anlatılan, bir kalabalığın doyurulduğu ekmeklerin ve balıkların çoğaltılması olayını anar. Kilise, erken Hristiyanlık dönemine ait mozaik zeminleriyle iyi bilinir.', 'Tabgha, Bizans döneminde mucizenin gerçekleştiği yer olarak saygı görürdü ve dördüncü yüzyıla ait küçük bir şapel, sonradan beşinci yüzyılda daha büyük bir kiliseyle değiştirildi. Bu erken yapılar harabeye döndü ve kalıntıları çağımızda yeniden keşfedilip kazılarla ortaya çıkarıldı. Yirminci yüzyılda inşa edilen bugünkü kilise, Bizans bazilikasının planını yeniden üretir.', 'Kiliseye, Kudüs''teki Dormisyon Manastırı''yla bağlantılı Alman Benedikten rahipleri hizmet eder. Etkin bir manastır ve hac yeri olmayı sürdürür; 2015''te çıkan bir yangın külliyenin bazı bölümlerine zarar verdi, ardından onarıldı.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'tr', 'Aziz Petrus''un Önceliği Kilisesi, Celile Gölü kıyısındaki Tabgha''da küçük bir Roma Katolik şapelidir. Yuhanna İncili''nde anlatılan, İsa''nın dirilişinden sonra öğrencilerine görünmesini ve Petrus''a önceliğin verilmesini anar. Şapel doğrudan suyun kıyısında yer alır.', 'Mekân, dirilmiş İsa''nın göl kenarında öğrencilerine göründüğü, onlarla ekmek ve balıktan bir öğün paylaştığı ve Petrus''a üç kez sürüsünü gütmesini buyurduğu Yuhanna 21''deki anlatıyı hatırlatır. Bu gelenekle bağlantılı bir kilise burada önceki yüzyıllarda vardı ve yakınlarda önceki yapıların izleri günümüze ulaşmıştır. Bugünkü şapel 1933''te inşa edildi.', 'Şapele Kutsal Toprakların Fransisken Kustodyası bakar. Celile Gölü''nün kuzey kıyısı çevresindeki mekânları ziyaret eden hacılar için sık uğranan bir duraktır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'tr', 'Başkalaşım Kilisesi, Aşağı Celile''deki Yizreel Vadisi''nin üzerinde yükselen Tabor Dağı''nın zirvesinde bir Roma Katolik bazilikasıdır. İncillere göre İsa''nın Musa ile İlyas''ın huzurunda görünümünün değiştiği İsa''nın Başkalaşımı''nı anar. Dağın başka bir yerinde bir Rum Ortodoks kilisesi de bulunur.', 'Tabor Dağı, Bizans döneminden bu yana Başkalaşım''ın geleneksel yeri olarak onurlandırılmış ve burada Bizans ile Haçlı dönemlerinde kiliseler inşa edilmiştir. Bu yapılar sonradan harabeye döndü ve temelleri zirvede günümüze ulaştı. Bugünkü bazilika 1924''te tamamlandı.', 'Bazilikaya ve arazisine Kutsal Toprakların Fransisken Kustodyası bakar. Dağ bir hac hedefi olmayı sürdürür ve zirve bir Rum Ortodoks manastırı ve kilisesiyle paylaşılır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'tr', 'Fransisken Düğün Kilisesi, Nasıra''nın kuzeyinde, İncillerdeki Celile''deki Kana ile geniş çapta özdeşleştirilen Kafr Kanna kasabasında yer alır. Yuhanna İncili''ne göre İsa''nın suyu şaraba dönüştürdüğü ve mucizelerinin ilki olarak nitelenen düğün ziyafetini anar. Mekân hacıları, özellikle de yeminlerini anmak ve yenilemek için gelen evli çiftleri kendine çeker.', 'Yuhanna İncili (2. bölüm) İsa''yı, annesini ve öğrencilerini Kana''daki bir düğüne yerleştirir; burada ev sahibinin şarabı tükenir ve İsa, altı taş küpü suyla doldurtur, su da şaraba dönüşür. Kafr Kanna''da mucizeyi onurlandıran bir kilise geleneği yüzyıllar içinde gelişti ve bugünkü yerin üzerinde ya da yakınında daha önceki ibadet yerleri bulunuyordu. Şimdiki Fransisken kilisesi 1879 ile 1905 arasında inşa edildi.', 'Düğün Kilisesi''ne, onu bir ibadet ve hac yeri olarak bakımlı tutan Kutsal Toprakların Kustodyası''na bağlı Fransisken rahipleri bakar. Kafr Kanna''daki ayrı bir Rum Ortodoks kilisesi de yakınlarda mucize geleneğini korur.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'tr', 'Celile Gölü''nün kuzey kıyısındaki Kefernahum, İncillerin İsa''nın Celile''deki hizmetinin merkezi olarak betimlediği göl kıyısı kasabasıdır. Arkeolojik alan, Havari Petrus''un evi olarak saygı gösterilen kalıntıları ve kadim bir sinagogu barındırır. Bölgedeki en önemli Yeni Ahit mekânlarından biridir.', 'İnciller Kefernahum''u İsa''nın öğrettiği, öğrenciler çağırdığı ve şifa dağıttığı yer olarak sunar ve kasabayı Petrus ile diğer izleyicilerle ilişkilendirir. İlk yüzyıllardan itibaren alandaki bir ev Hristiyanlarca saygı gördü ve sonradan sekizgen bir kilisenin içine alındı. Kasaba, gerilemeden önce yüzyıllarca yerleşim gördü ve çağdaş arkeologların incelediği kalıntıları geride bıraktı.', 'Alan, kiliseyi, kazıları ve hacılarla ziyaretçilerin girişini gözeten Kutsal Toprakların Fransisken Kustodyası''nın elinde olup onun tarafından bakımlı tutulur. Alanın doğu kenarında ayrı bir Rum Ortodoks kilisesi ve manastırı bulunur.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'tr', 'Çobanlar Tarlası Şapeli, Beytüllahim''in doğusundaki Beit Sahour''da, geleneksel olarak Doğuş öyküsündeki çobanların tarlalarıyla özdeşleştirilen yerde bulunur. Luka İncili''ne göre melekler orada, gece sürülerini bekleyen çobanlara İsa''nın doğumunu müjdelemiştir. Şapel ve çevresindeki arazi, özellikle Noel''de bir dua ve hac yeridir.', 'Luka İncili (2. bölüm) Beytüllahim yakınlarında, kendilerine Kurtarıcı''nın doğumu bildirilen ve çocuğu bulmaya giden çobanları anlatır. Beit Sahour yakınındaki çoban tarlalarına gösterilen Hristiyan saygısı çok eskidir ve bu bölgede daha eski kiliselerin ve manastır yapılarının kalıntıları bulunmuştur. Bugünkü Fransisken şapeli 1953''te inşa edildi.', 'Şapele ve tarlasına Kutsal Toprakların Fransisken Kustodyası bakar. Kendi kilisesi ve kadim kalıntıları olan ayrı bir Rum Ortodoks Çobanlar Tarlası, Beit Sahour''un aynı bölgesinde yakınlarda yer alır.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'tr', 'Süt Mağarası, Beytüllahim''de, Doğuş Kilisesi''ne kısa bir yürüme mesafesinde, yumuşak beyaz tebeşirli bir mağaranın çevresine inşa edilmiş bir şapeldir. Gelenek mağarayı Kutsal Aile ile ilişkilendirir ve onu Mısır''a kaçıştan önceki ya da o sıradaki zamana bağlar. Özellikle anneler ve çocuk sahibi olmayı uman çiftlerce ziyaret edilen sakin bir dua yeridir.', 'Yerel gelenek, Kutsal Aile''nin bu mağaraya sığındığını ve kayasının beyaza döndüğünü, adın ve sütle annelikle bağlantılı ibadetlerin bundan doğduğunu kabul eder. Mekâna gösterilen Hristiyan saygısı pek çok yüzyıl boyunca belgelenmiştir. Mağara uzun süredir Fransisken bakımındadır ve çağımızda daha eski mabedin yanına daha yeni bir şapel eklenmiştir.', 'Süt Mağarası''na, onu bir dua yeri olarak bakımlı tutan ve birçok ülkeden hacıları ağırlayan Kutsal Toprakların Fransisken Kustodyası bakar. Özellikle annelik ve aile için dua edenler açısından kişisel ibadetin bir odağı olmayı sürdürür.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
