INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'category', 'tr', 'Restorasyon', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'full_description', 'tr', 'Bu proje, yapısal onarımlar, cephe temizliği ve özgün mimari ögelerin korunması dâhil olmak üzere bazilikanın acil restorasyon ihtiyaçlarına odaklanmaktadır. Çalışmalar, yapının gelecek nesiller için güvenli ve erişilebilir kalmasını sağlayacaktır.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'short_description', 'tr', 'Müjde Bazilikası''nın ana nefinin ve cephesinin restorasyonu.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000001', 'title', 'tr', 'Bazilika Restorasyonu — 1. Aşama', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'category', 'tr', 'Belgeleme', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'tr', 'İsrail ve çevre bölgelerdeki Hristiyan miras alanlarını, eserlerini ve el yazmalarını fotoğraflamaya, taramaya ve belgelemeye yönelik kapsamlı bir girişim. Bu dijital arşiv, araştırmacılar ve gelecek nesiller için paha biçilmez tarihi kayıtları koruyacaktır.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'short_description', 'tr', 'Kutsal Topraklar genelinde Hristiyan miras alanlarının dijital olarak belgelenmesi.', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'title', 'tr', 'Kutsal Topraklar Miras Belgeleme', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000001', 'uk', 'Базиліка Благовіщення — католицький храм у Назареті (Ізраїль). Це одна з найбільших церков на Близькому Сході. Вона стоїть на місці, де, за переданням, Архангел Гавриїл сповістив Діві Марії, що вона народить Ісуса.', 'Нинішню базиліку збудовано 1969 року за проєктом італійського архітектора Джованні Муціо. Вона височіє над руїнами давніших церков візантійської доби та часів хрестових походів. Від давніх часів це місце приваблює християнських паломників.', 'Храм служить місцевій католицькій громаді Назарета й приймає паломників з усього світу. Меси регулярно відправляють кількома мовами.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000002', 'uk', 'Храм Різдва Христового у Вифлеємі стоїть над печерою, яку християнське передання з II століття шанує як місце народження Ісуса. Це один із найдавніших храмів світу, у якому богослужіння звершуються безперервно, і об’єкт Світової спадщини ЮНЕСКО.', 'Першу базиліку спорудили близько 327 року н. е. з волі імператора Костянтина та його матері Олени. Після пошкоджень у VI столітті імператор Юстиніан відбудував її в більшому масштабі, і значна частина нинішнього храму походить саме з тієї відбудови. Усередині досі збереглися мозаїки та розписані колони доби хрестоносців.', 'Храм перебуває в спільному віданні трьох громад — грецької православної, римо-католицької (францисканці) та вірменської апостольської — відповідно до історичного статус-кво. Місцеві християнські родини Вифлеєма моляться тут разом із паломниками з усього світу, особливо на Різдво.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000003', 'uk', 'Храм Гробу Господнього в Старому місті Єрусалима об’єднує дві найбільші святині християнства: Голгофу, де було розіп’ято Ісуса, і Гріб Господній — місце, де, за переданням, Він був похований і воскрес.', 'Перший храм тут збудував імператор Костянтин у IV столітті; його освятили 335 року н. е. У 1009 році храм зруйнували, в XI столітті відбудували, а в XII столітті хрестоносці значною мірою надали йому нинішнього вигляду. Кувуклію над Гробом Господнім відреставрували в 2016–2017 роках.', 'Храм перебуває в спільному віданні трьох церков — Грецької православної, Римо-католицької (францисканці) та Вірменської апостольської; власні каплиці мають також православні громади коптів, ефіопів і сирійців. Цей устрій закріплено статус-кво 1852 року. Щоранку двері храму відчиняють мусульманські родини, які століттями зберігають його ключі.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000004', 'uk', 'Церква Всіх Націй, відома також як Базиліка Агонії, — католицький храм у Гефсиманії на Оливній горі в Єрусалимі. У ньому зберігається ділянка скелі, яку за переданням вважають місцем, де Ісус молився у смертельній тузі в ніч перед розп’яттям.', 'Нинішню базиліку збудовано у 1919–1924 роках на фундаментах давніших візантійської та хрестоносної церков, виявлених під час будівництва. Вона дістала назву Церкви Всіх Націй, бо її зведення фінансували пожертви з багатьох країн, чиї герби вміщено в стелю.', 'Про базиліку дбає Францисканська Кустодія Святої Землі, яка утримує це місце та прилеглий Гефсиманський сад із його давніми оливами. Храм залишається діючим місцем молитви й важливою зупинкою для паломників, що відвідують Оливну гору.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000005', 'uk', 'Церква Марії Магдалини — російський православний храм на західному схилі Оливної гори в Єрусалимі, поблизу Гефсиманського саду. Він широко відомий своїми сімома золоченими цибулястими банями — прикметною рисою єрусалимського обрію.', 'Храм збудував у 1886–1888 роках російський імператор Олександр III на згадку про свою матір, імператрицю Марію Олександрівну. Його присвячено Марії Магдалині — святій, на честь якої було наречено імператрицю, — і він відображає російську присутність у Святій Землі наприкінці XIX століття.', 'Храм належить жіночому православному монастирю й залишається діючою чернечою спільнотою, яка приймає відвідувачів і паломників. Він розташований в околицях Гефсиманії на схилах Оливної гори.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000006', 'uk', 'Домінус Флевіт, що латиною означає «Господь заплакав», — католицька каплиця на західному схилі Оливної гори в Єрусалимі. Вона позначає місце, де, згідно з Євангелієм від Луки, Ісус заплакав, дивлячись на Єрусалим, і провістив його руйнування.', 'Нинішню каплицю збудовано 1955 року на місці давніших культових споруд, зокрема решток церкви візантійської доби. Розкопки на її території також відкрили давні гробниці та осуарії, що свідчать про тривале використання схилу як місця поховання.', 'Домінус Флевіт утримує Францисканська Кустодія Святої Землі як частину своєї мережі святинь у Єрусалимі та його околицях. Каплиця — часта зупинка для паломників, які спускаються з Оливної гори до Гефсиманії.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000007', 'uk', 'Церква Святої Анни — католицький храм у Старому місті Єрусалима, у Мусульманському кварталі, поряд із Віфездою (Овечою купіллю). Він стоїть над місцем, яке за переданням шанують як дім Анни та Йоакима і місце народження Діви Марії.', 'Храм збудовано у XII столітті за часів Єрусалимського королівства хрестоносців. Після завоювання міста Саладіном 1187 року його перетворили на мусульманську школу, а в XIX столітті османська влада передала його Франції, чиї опікуни відновили будівлю.', 'Храм і його територію ввірено Місіонерам Африки, більш відомим як Білі отці, які дбають про це місце та приймають паломників. Він залишається діючим місцем молитви та навчання в межах Старого міста.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000008', 'uk', 'Церква Патер Ностер — католицький храм і кармелітський монастир на Оливній горі в Єрусалимі. Він розташований на місці, яке за переданням пов’язують із тим, як Ісус навчив учнів молитви Господньої, відомої латиною як «Патер Ностер» («Отче наш»).', 'Це місце зберігає пам’ять про візантійську церкву Елеона, збудовану в IV столітті над печерою на Оливній горі за правління Костянтина. Після століть занепаду тут у XIX столітті засновано французький монастир, а зведення церковних споруд тривало й у XX столітті.', 'Про це місце дбає спільнота сестер-кармеліток, які утримують монастир, храм і клуатр. Це постійна зупинка для паломників і відвідувачів, що оглядають Оливну гору.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000009', 'uk', 'Церква Відвідин — католицький храм у селищі Ейн-Карем на західній околиці Єрусалима. Він позначає традиційне місце, де Марія відвідала свою родичку Єлисавету і, згідно з Євангелієм від Луки, промовила гимн, відомий як «Магніфікат». Про це місце дбають францисканці, і воно широко відвідуване паломниками Святої Землі.', 'Християнське передання ототожнює Ейн-Карем із рідним селищем Захарії та Єлисавети і місцем Відвідин, описаних у Євангелії від Луки. Церква стояла тут за візантійської доби й за часів хрестоносців, і нинішня дворівнева будівля зберігає елементи цих давніших споруд. Сучасний храм постав у першій половині XX століття під орудою Францисканської Кустодії Святої Землі.', 'Це місце належить Францисканській Кустодії Святої Землі, яка дбає про численні святині по всьому регіоні, і утримується нею. Храм залишається діючим місцем молитви та постійною зупинкою на паломницьких маршрутах через Ейн-Карем, де є й інші церкви, пов’язані з народженням Івана Хрестителя.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000010', 'uk', 'Церква Блаженств — католицький храм на схилі пагорба над північно-західним берегом Галілейського моря. Він позначає традиційне місце Нагірної проповіді й дістав назву від Заповідей блаженства — благословень, якими відкривається проповідь у Євангелії від Матвія. З цього місця відкривається широкий краєвид на озеро та навколишні селища.', 'Передання про пагорб поблизу Капернаума як місце Нагірної проповіді давнє, а давніші рештки відзначено неподалік, у Табзі внизу. Нинішній храм збудовано 1938 року за проєктом італійського архітектора Антоніо Барлуцці. Його зведення частково фінансувала Італія.', 'Про храм і його територію дбають Францисканські сестри-місіонерки Святого Серця. Це місце слугує як місцем богослужіння, так і широко відвідуваною метою паломництва в Галілеї.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000011', 'uk', 'Церква Примноження хлібів і риб — католицький храм у Табзі, на північно-західному березі Галілейського моря. Він увічнює євангельську оповідь про примноження хлібів і риб, якими було нагодовано натовп. Храм добре відомий своїми ранньохристиянськими мозаїчними підлогами.', 'Табху шанували за візантійської доби як місце чуда: невелику каплицю IV століття згодом замінив більший храм V століття. Ці ранні споруди занепали, а їхні рештки було віднайдено й розкопано в новітні часи. Нинішній храм, збудований у XX столітті, відтворює план візантійської базиліки.', 'Храмові служать німецькі ченці-бенедиктинці, пов’язані з абатством Успіння в Єрусалимі. Він залишається діючим монастирським і паломницьким місцем; 2015 року пожежа пошкодила частину комплексу, після чого його було відновлено.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000012', 'uk', 'Церква Першості святого Петра — невелика католицька каплиця в Табзі, на березі Галілейського моря. Вона увічнює описану в Євангелії від Івана появу Ісуса перед учнями після воскресіння та надання першості Петрові. Каплиця стоїть просто біля води.', 'Це місце нагадує про оповідь у 21-му розділі Євангелія від Івана, де воскреслий Ісус з’являється учням біля озера, розділяє з ними трапезу з хліба та риби і тричі доручає Петрові пасти Своє стадо. Церква, пов’язана з цим переданням, існувала тут у попередні століття, і сліди колишніх споруд збереглися поблизу. Нинішню каплицю збудовано 1933 року.', 'Каплицю утримує Францисканська Кустодія Святої Землі. Це часта зупинка для паломників, що відвідують місцини на північному березі Галілейського моря.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000013', 'uk', 'Церква Преображення — католицька базиліка на вершині гори Фавор, що височіє над Ізреельською долиною в Нижній Галілеї. Вона увічнює Преображення Ісуса, коли, згідно з Євангеліями, Він постав преображеним у присутності Мойсея та Іллі. В іншому місці на горі стоїть також грецький православний храм.', 'Гору Фавор шанують від візантійської доби як традиційне місце Преображення, і церкви зводили тут за візантійських часів і за часів хрестоносців. Ці споруди згодом було зруйновано, а їхні фундаменти збереглися на вершині. Нинішню базиліку завершено 1924 року.', 'Про базиліку та її територію дбає Францисканська Кустодія Святої Землі. Гора залишається метою паломництва, а вершину поділяють із нею грецький православний монастир і храм.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000014', 'uk', 'Францисканська Церква Вінчання стоїть у Кафр-Кані — містечку на північ від Назарета, яке широко ототожнюють із євангельською Каною Галілейською. Вона увічнює весільний бенкет, на якому, згідно з Євангелієм від Івана, Ісус перетворив воду на вино, що названо першим із Його знамень. Це місце приваблює паломників, і особливо подружні пари, які приїжджають, щоб відзначити й оновити свої шлюбні обітниці.', 'Євангеліє від Івана (розділ 2) поміщає Ісуса, Його Матір та учнів на весілля в Кані, де в господаря скінчилося вино і Ісус звелів наповнити водою шість кам’яних посудин, і вода стала вином. Церковне передання, що шанує це чудо в Кафр-Кані, складалося впродовж століть, а колишні місця богослужіння стояли на нинішньому місці або поблизу нього. Сучасний францисканський храм збудовано у 1879–1905 роках.', 'Про Церкву Вінчання дбають францисканські брати Кустодії Святої Землі, які утримують її як місце богослужіння та паломництва. Окремий грецький православний храм у Кафр-Кані також зберігає неподалік передання про це чудо.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000015', 'uk', 'Капернаум на північному березі Галілейського моря — приозерне містечко, яке Євангелія описують як осередок служіння Ісуса в Галілеї. Археологічна пам’ятка зберігає рештки, шановані як дім апостола Петра, і давню синагогу. Це одне з найважливіших новозавітних місць у регіоні.', 'Євангелія подають Капернаум як місце, де Ісус навчав, покликав учнів та зціляв, і пов’язують містечко з Петром та іншими послідовниками. Від перших століть дім на цьому місці шанували християни, а згодом його оточили восьмигранною церквою. Містечко було залюднене впродовж століть, доки не занепало, лишивши руїни, які вивчають сучасні археологи.', 'Цим місцем володіє й дбає про нього Францисканська Кустодія Святої Землі, яка відає храмом, розкопками та доступом для паломників і відвідувачів. На східній околиці цієї місцевості стоять окремі грецький православний храм і монастир.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000016', 'uk', 'Каплиця Поля пастухів стоїть у Бейт-Сахурі, на схід від Вифлеєма, на місці, яке за переданням ототожнюють із полями пастухів з оповіді про Різдво. Згідно з Євангелієм від Луки, ангели там сповістили про народження Ісуса пастухам, що вночі стерегли свої отари. Каплиця та навколишня територія — місце молитви й паломництва, особливо на Різдво.', 'Євангеліє від Луки (розділ 2) описує пастухів поблизу Вифлеєма, яким сповістили про народження Спасителя і які пішли знайти Дитя. Християнське шанування пастуших полів поблизу Бейт-Сахура дуже давнє, і в цій місцевості знайдено рештки давніших церков та монастирських споруд. Нинішню францисканську каплицю збудовано 1953 року.', 'Про каплицю та її поле дбає Францисканська Кустодія Святої Землі. Окреме грецьке православне Поле пастухів зі своїм храмом і давніми рештками розташоване поблизу, у тій самій місцевості Бейт-Сахура.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
INSERT INTO public.church_descriptions (church_id, locale, overview, story, community) VALUES ('10000000-0000-0000-0000-000000000017', 'uk', 'Молочний грот — каплиця, збудована навколо грота з м’якої білої крейди у Вифлеємі, за кілька хвилин ходьби від Храму Різдва. Передання пов’язує грот зі Святою Родиною, відносячи його до часу перед втечею до Єгипту або під час неї. Це тихе місце молитви, яке особливо відвідують матері та пари, що сподіваються на дітей.', 'Місцеве передання каже, що Свята Родина сховалася в цьому гроті і що його камінь став білим, звідки й походить назва та пов’язані з молоком і материнством форми побожності. Християнське шанування цього місця засвідчене впродовж багатьох століть. Грот здавна перебуває під опікою францисканців, а в новітню добу поряд зі старою святинею прибудовано новішу каплицю.', 'Про Молочний грот дбає Францисканська Кустодія Святої Землі, яка утримує його як місце молитви та приймає паломників із багатьох країн. Він залишається осередком особистої побожності, особливо для тих, хто молиться про материнство та родину.') ON CONFLICT (church_id, locale) DO UPDATE SET overview = EXCLUDED.overview, story = EXCLUDED.story, community = EXCLUDED.community;
