INSERT INTO public.translations (entity_type, entity_id, field, locale, content, status, source_locale) VALUES ('project', '20000000-0000-0000-0000-000000000002', 'full_description', 'zh', '这是一项全面的计划，旨在对以色列及周边地区的基督教遗产地、文物和手稿进行拍摄、扫描和记录。这一数字档案将为研究人员和后代保存珍贵的历史资料。', 'PUBLISHED', 'en') ON CONFLICT (entity_type, entity_id, field, locale) DO UPDATE SET content = EXCLUDED.content, status = 'PUBLISHED', updated_at = NOW();
